// COMPOSITION D'UNE RESERVATION EN ACTIVITES. La fiche programme du serveur
// (program.items : id + nom du catalogue vivant) fait foi ; sans elle, le type
// et les fenetres de ressources disent bowling / laser ; un type inconnu reste
// nomme plutot qu'avale par une categorie fourre-tout.
function getReservationActivityEntries(reservation) {
  const items = reservation && reservation.program && Array.isArray(reservation.program.items)
    ? reservation.program.items
    : [];
  if (items.length) {
    const seen = new Map();
    items.forEach(item => {
      const id = String(item.activityId || 'autre');
      if (!seen.has(id)) seen.set(id, { id, name: item.name || ACTIVITY_LABELS[id] || id });
    });
    return [...seen.values()];
  }
  const entries = [];
  if (getBowlingWindowsFromReservation(reservation).length) entries.push({ id: 'bowling', name: ACTIVITY_LABELS.bowling });
  if (getLaserWindowsFromReservation(reservation).length) entries.push({ id: 'laser_game', name: ACTIVITY_LABELS.laser_game });
  if (!entries.length) {
    const id = String(reservation.type || 'autre');
    entries.push({ id, name: ACTIVITY_LABELS[id] || 'Autre activité' });
  }
  return entries;
}

// UNE RESERVATION = UNE PART du donut, classee par sa composition : une seule
// activite -> cette activite ; une formule -> Formules ; un panier libre de
// plusieurs activites -> Multi-activites. Les parts somment donc toujours au
// nombre de reservations, et chaque pourcentage vient de SON compte (jamais
// d'un reste).
function buildStaffActivityMix(activeReservations = []) {
  const buckets = new Map();
  activeReservations.forEach(reservation => {
    const entries = getReservationActivityEntries(reservation);
    const isFormule = reservation.type === 'formule' || reservation.formuleId;
    const key = isFormule ? 'formule' : (entries.length > 1 ? 'multi' : entries[0].id);
    const label = isFormule ? 'Formules' : (entries.length > 1 ? 'Multi-activités' : entries[0].name);
    const bucket = buckets.get(key) || { key, label, count: 0, revenue: 0, players: 0 };
    bucket.count += 1;
    bucket.revenue += Number(reservation.price) || 0;
    bucket.players += Number(reservation.pax) || 0;
    buckets.set(key, bucket);
  });
  return [...buckets.values()].sort((left, right) => right.count - left.count || left.label.localeCompare(right.label));
}

// OCCURRENCES PAR ACTIVITE : combien de dossiers contiennent chaque activite
// du catalogue (une visite bowling + billards compte dans les deux). C'est la
// lecture « qu'est-ce qui tourne aujourd'hui », servie par le detail.
function buildStaffActivityOccurrences(activeReservations = []) {
  const buckets = new Map();
  activeReservations.forEach(reservation => {
    getReservationActivityEntries(reservation).forEach(entry => {
      const bucket = buckets.get(entry.id) || { id: entry.id, name: entry.name, count: 0, revenue: 0, rows: [] };
      bucket.count += 1;
      bucket.rows.push(reservation);
      buckets.set(entry.id, bucket);
    });
  });
  return [...buckets.values()].sort((left, right) => right.count - left.count || left.name.localeCompare(right.name));
}

// SERIE QUOTIDIENNE SERVIE PAR LE SERVEUR. Le cache local (state.reservations)
// ne contient QUE les dates deja visitees sur CE poste : la carte Revenus
// affichait 0 sur les jours jamais ouverts (« des fois ca montre des fois
// non », capture Movsar 2026-08-18). Le serveur agrege la vraie plage ; le
// calcul local reste le repli tant que la reponse n'est pas la.
// Cache PAR FENETRE (cle centre|date de fin) : la carte Revenus navigue par
// jours (fleches), chaque fenetre garde sa reponse ~60 s. 14 jours par appel :
// la fenetre affichee (7) + la precedente, pour une tendance « vs periode
// precedente » calculee sur de vraies donnees serveur.
const staffDaySeriesCache = new Map();

function getStaffDaySeries(endDate = state.currentDate) {
  const entry = staffDaySeriesCache.get(`${getCurrentStaffCenterId()}|${endDate}`);
  return entry ? entry.days : [];
}

async function ensureStaffDaySeries(endDate = state.currentDate) {
  const key = `${getCurrentStaffCenterId()}|${endDate}`;
  const entry = staffDaySeriesCache.get(key);
  // Une serie vide attend aussi avant de se relire : lue sans delai, elle redessine, se relit, et fige l ecran.
  if (entry && (entry.loading || (Date.now() - entry.at) < (entry.days.length ? 60000 : 15000))) return;
  staffDaySeriesCache.set(key, { days: entry ? entry.days : [], at: entry ? entry.at : 0, loading: true });
  try {
    const centerQuery = encodeURIComponent(getCurrentStaffCenterId());
    const payload = await apiRequest(`${API_ENDPOINTS.staffState}?date=${encodeURIComponent(endDate)}&centerId=${centerQuery}&days=14`);
    const days = Array.isArray(payload.days) ? payload.days : [];
    staffDaySeriesCache.set(key, { days, at: Date.now(), loading: false });
    if (days.length && state.view === 'staff' && state.staffMenuPage === 'dashboard') renderStaffDashboard();
  } catch (error) {
    // Repli silencieux sur la serie locale : la carte reste honnete, juste
    // limitee aux dates connues du poste.
    staffDaySeriesCache.set(key, { days: [], at: Date.now(), loading: false });
  }
}

function getStaffDashboardMetrics(dayReservations = todaysReservations()) {
  // (un groupe « Pas venu » n a ni joue ni paye : ni chiffre, ni joueurs, ni pistes)
  const activeReservations = dayReservations.filter(tientSesPlaces);
  const now = currentTimeDecimal();
  const planningWindow = getPlanningWindow(state.currentDate);
  const openHours = planningWindow.closed ? 0 : Math.max(planningWindow.close - planningWindow.open, 0);
  const bowlingWindows = activeReservations.flatMap(reservation => getBowlingWindowsFromReservation(reservation).map(window => ({ ...window, reservation })));
  const laserWindows = activeReservations.flatMap(reservation => getLaserWindowsFromReservation(reservation).map(window => ({ ...window, reservation })));
  const revenue = activeReservations.reduce((sum, reservation) => sum + (Number(reservation.price) || 0), 0);
  const collected = activeReservations.filter(reservation => reservation.status === 'paid').reduce((sum, reservation) => sum + (Number(reservation.price) || 0), 0);
  const players = activeReservations.reduce((sum, reservation) => sum + (Number(reservation.pax) || 0), 0);
  const laneHours = bowlingWindows.reduce((sum, window) => sum + ((Number(window.duration) || 0) * Math.max((window.lanes || []).length, 1)), 0);
  const laneCount = getAvailabilityLaneCount();
  const bowlingCapacity = laneCount * openHours;
  const occupancy = bowlingCapacity ? Math.round((laneHours / bowlingCapacity) * 100) : 0;
  const upcoming = activeReservations
    .filter(reservation => getReservationFirstResourceStart(reservation, 'all') >= (state.currentDate === todayStr() ? now : 0))
    .sort((left, right) => getReservationFirstResourceStart(left, 'all') - getReservationFirstResourceStart(right, 'all'));
  const activeNow = activeReservations.filter(reservation => {
    return getStaffResourceWindows(reservation, 'all').some(window => window.start <= now && now < window.end);
  });
  // REPARTITION PAR ACTIVITE tiree de la COMPOSITION REELLE de chaque
  // reservation (program.items du serveur, sinon type et fenetres), plus
  // jamais du seul couple bowling/laser : 7 resas dont 2 golf/arcades
  // donnaient « Complet 43 % » avec 1 dossier (2026-08-18, capture Movsar),
  // parce que le pourcentage etait un RESTE (100 - bowling - laser) et que
  // toute activite hors bowling/laser tombait dedans en silence.
  const activityMix = buildStaffActivityMix(activeReservations);
  const activityOccurrences = buildStaffActivityOccurrences(activeReservations);
  // EN CE MOMENT : la regle de la page Terrain, pas une seconde. Un groupe en
  // retard, sur place ou a cloturer l est ici exactement comme la-bas.
  const liveNow = getStaffDashNow(activeReservations);
  // Mini-séries 7 jours HONNÊTES : chaque point vient des réservations réelles
  // du jour (state.reservations), jamais d'une interpolation fabriquée.
  const days = Array.from({ length: 7 }, (_, index) => addDays(state.currentDate, index - 6));
  const dayRows = days.map(date => state.reservations.filter(reservation => reservation.date === date && reservation.status !== 'cancelled'));
  const revenueSeries = dayRows.map(rows => rows.reduce((sum, reservation) => sum + (Number(reservation.price) || 0), 0));
  const reservationSeries = dayRows.map(rows => rows.length);
  const playerSeries = dayRows.map(rows => rows.reduce((sum, reservation) => sum + (Number(reservation.pax) || 0), 0));
  const collectedSeries = dayRows.map(rows => rows.filter(reservation => reservation.status === 'paid').reduce((sum, reservation) => sum + (Number(reservation.price) || 0), 0));
  const occupancySeries = days.map((date, index) => {
    const window = getPlanningWindow(date);
    const open = window.closed ? 0 : Math.max(window.close - window.open, 0);
    const capacity = laneCount * open;
    if (!capacity) return 0;
    const usedLaneHours = dayRows[index]
      .flatMap(reservation => getBowlingWindowsFromReservation(reservation))
      .reduce((sum, win) => sum + ((Number(win.duration) || 0) * Math.max((win.lanes || []).length, 1)), 0);
    return Math.min(100, Math.round((usedLaneHours / capacity) * 100));
  });
  // La serie SERVEUR remplace la lecture du cache local pour les jours passes
  // (voir staffDaySeriesCache). Le jour affiche garde la donnee locale : elle
  // est temps reel (poll + mises a jour optimistes), le serveur a 60 s de
  // retard dessus.
  const serverDays = (typeof getStaffDaySeries === 'function' ? getStaffDaySeries() : []).slice(-7);
  if (serverDays.length === days.length) {
    serverDays.forEach((day, index) => {
      if (index === days.length - 1 || !day || day.date !== days[index]) return;
      revenueSeries[index] = Number(day.revenue) || 0;
      reservationSeries[index] = Number(day.reservations) || 0;
      playerSeries[index] = Number(day.players) || 0;
      collectedSeries[index] = Number(day.collected) || 0;
      const window = getPlanningWindow(days[index]);
      const open = window.closed ? 0 : Math.max(window.close - window.open, 0);
      const capacity = laneCount * open;
      occupancySeries[index] = capacity ? Math.min(100, Math.round(((Number(day.laneHours) || 0) / capacity) * 100)) : 0;
    });
  }
  // LA VEILLE VIENT DU SERVEUR OU NE VIENT PAS. Elle se lisait dans le cache
  // du poste (state.reservations) : un poste qui n avait jamais ouvert la
  // veille lisait « hier : 0 » sur les quatre tuiles d un lendemain de
  // samedi plein. Tant que la serie n est pas la, la reference est INCONNUE
  // (null) et les tuiles ne comparent a rien. Meme regle pour la courbe.
  const seriesFromServer = serverDays.length === days.length
    && serverDays.slice(0, -1).every((day, index) => day && day.date === days[index]);
  // LA REFERENCE EST LE MEME JOUR LA SEMAINE D AVANT, PAS LA VEILLE. Un
  // centre de loisirs vit a la semaine : un samedi contre un vendredi
  // affichait « +167 % » sur les quatre tuiles, un lundi ferme « hier : 0 ».
  // Le serveur sert 14 jours ; le point d il y a 7 jours est le 8e depuis la
  // fin, et il doit porter la bonne date, sinon on ne compare a rien.
  // Une date FUTURE ne se compare pas : ses reservations sont celles prises a
  // ce jour, la semaine d avant est finie. « -50 % » en rouge sur un mercredi
  // a venir disait une baisse qui n existe pas.
  const weekAgoDate = addDays(state.currentDate, -7);
  const fullSeries = typeof getStaffDaySeries === 'function' ? getStaffDaySeries() : [];
  const weekAgo = state.currentDate <= todayStr() && fullSeries.length >= 8 && fullSeries[fullSeries.length - 8] && fullSeries[fullSeries.length - 8].date === weekAgoDate
    ? fullSeries[fullSeries.length - 8]
    : null;
  const weekAgoOccupancy = (() => {
    if (!weekAgo) return null;
    const window = getPlanningWindow(weekAgoDate);
    const open = window.closed ? 0 : Math.max(window.close - window.open, 0);
    const capacity = laneCount * open;
    return capacity ? Math.min(100, Math.round(((Number(weekAgo.laneHours) || 0) / capacity) * 100)) : 0;
  })();
  const referencePoint = (field) => (weekAgo ? Number(weekAgo[field]) || 0 : null);
  return {
    activeReservations,
    bowlingWindows,
    laserWindows,
    revenue,
    collected,
    players,
    occupancy,
    upcoming,
    activeNow,
    activityMix,
    activityOccurrences,
    liveNow,
    revenueSeries,
    reservationSeries,
    playerSeries,
    collectedSeries,
    occupancySeries,
    seriesFromServer,
    seriesDays: days,
    referenceDate: weekAgoDate,
    referenceReservations: referencePoint('reservations'),
    referenceRevenue: referencePoint('revenue'),
    referencePlayers: referencePoint('players'),
    referenceOccupancy: weekAgoOccupancy,
    planningWindow,
    laneCount
  };
}

// EN CE MOMENT, sur la file de la page Terrain (getStaffTerrainBoard) : le
// jour meme seulement, une autre date n a pas de « maintenant ». La colonne
// « Sur place » de Terrain melange deux choses que l accueil separe : les
// groupes POINTES (ils sont la) et ceux dont l heure est passee sans que
// personne ne clique Arrivé (ils sont en retard, ou deja la sans pointage).
//   late    : l heure est passee, pas pointe, la partie n est pas finie ;
//   onsite  : pointe arrive (ou paye) et pas fini ;
//   closing : fini et pas paye (pointe ou non, comme Terrain « À clôturer ») ;
//   next    : attendu dans l heure qui vient.
//   due     : l heure est passee depuis MOINS que le seuil de retard du
//             centre (Etablissement, 5 min par defaut) : attendu, pas encore
//             en retard, et pas « sur place » non plus.
function splitStaffTerrainOnsite(board) {
  const late = [];
  const present = [];
  const due = [];
  const seuil = getStaffLateThresholdMinutes() / 60;
  board.onsite.forEach(item => {
    // Une activite cochee prouve que le groupe est la, meme sans « Arrivé » :
    // ses etapes disaient « En cours » pendant que sa tete criait au retard
    // et proposait encore « Arrivé » (2026-10-08).
    if (!isUpcomingReservationStatus(item.reservation.status || 'pending') || item.start > board.now || groupeAJoue(item.reservation)) present.push(item);
    else if (board.now - item.start >= seuil - 1e-9) late.push(item);
    else due.push(item);
  });
  late.sort((left, right) => left.start - right.start);
  due.sort((left, right) => left.start - right.start);
  return { late, present, due };
}

// LE SEUIL DE RETARD, EN MINUTES. La configuration du centre fait foi : celle
// que l ecran Etablissement vient d enregistrer d abord (le poll de la journee
// peut repondre 304 tant qu aucune reservation n a bouge), puis celle que le
// poll sert a toute l equipe, puis 5 min.
const STAFF_LATE_THRESHOLD_DEFAUT = 5;
function getStaffLateThresholdMinutes() {
  const lire = (valeur) => {
    const n = Number(valeur);
    return Number.isFinite(n) && n >= 0 ? Math.min(60, Math.trunc(n)) : null;
  };
  const centre = typeof staffCenterConfigCache !== 'undefined' && staffCenterConfigCache && Array.isArray(staffCenterConfigCache.centers)
    ? staffCenterConfigCache.centers.find(center => center.id === getCurrentStaffCenterId())
    : null;
  const configure = lire(centre && centre.accueil && centre.accueil.lateThresholdMinutes);
  if (configure !== null) return configure;
  const servi = lire(state.staffAccueil && state.staffAccueil.lateThresholdMinutes);
  return servi !== null ? servi : STAFF_LATE_THRESHOLD_DEFAUT;
}

function getStaffDashNow(activeReservations) {
  const board = getStaffTerrainBoard(activeReservations);
  if (board.when !== 'today') return null;
  const { late, present, due } = splitStaffTerrainOnsite(board);
  const horizon = board.now + 1;
  return {
    now: board.now,
    horizon,
    late,
    onsite: present,
    closing: board.closing,
    next: [...due, ...board.upcoming.filter(item => item.start <= horizon)],
    later: board.upcoming.filter(item => item.start > horizon)
  };
}

// LA REFERENCE SE DIT UNE FOIS, au-dessus des tuiles : « comparée au samedi
// 26 septembre ». Quatre « vs sam. dernier » coupaient les libelles des
// tuiles (« Chiffre d affair... ») pour repeter la meme chose.
function getDashReferenceLabel(metrics) {
  return parseLocalDate(metrics.referenceDate).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' });
}

// EN CE MOMENT (le jour meme) : quatre chiffres tires de la file de la page
// Terrain, dans son ordre (qui arrive, qui manque, qui est la, qui a fini).
// Aucune liste de dossiers ici (Movsar, 2026-08-14) : chaque case mene a
// Terrain, et le retard ou l argent a son panneau (Pointer, Encaisser).
function renderStaffDashNow(live) {
  const count = (n, one, many) => `${n} ${n > 1 ? many : one}`;
  const players = items => items.reduce((sum, item) => sum + (Number(item.reservation.pax) || 0), 0);
  const clock = hours => formatClockDisplay(hours);
  const toTerrain = "openStaffMenuPage('arrivals')";
  const closingAmount = live.closing.reduce((sum, item) => sum + (Number(item.reservation.price) || 0), 0);
  const firstEnd = live.onsite.length ? Math.min(...live.onsite.map(item => item.end)) : null;
  const cells = [
    {
      key: 'next',
      label: `D'ici ${clock(live.horizon)}`,
      value: live.next.length ? count(live.next.length, 'groupe', 'groupes') : 'Personne',
      sub: live.next.length
        ? `${count(players(live.next), 'joueur', 'joueurs')} · premier à ${clock(live.next[0].start)}`
        : (live.later.length ? `prochain à ${clock(live.later[0].start)}` : 'plus d’arrivée aujourd’hui'),
      tone: 'neutral',
      open: toTerrain,
      hint: 'Voir les arrivées sur la page Terrain'
    },
    {
      key: 'late',
      label: 'En retard',
      value: live.late.length ? count(live.late.length, 'groupe', 'groupes') : 'Aucun',
      sub: live.late.length
        ? `pas pointé${live.late.length > 1 ? 's' : ''} · depuis ${formatStaffTerrainDelay(live.now - live.late[0].start)}`
        : 'les groupes attendus sont pointés',
      tone: live.late.length ? 'important' : 'ok',
      open: live.late.length ? "openStaffDashboardDetail('alerts', 'noshow')" : toTerrain,
      hint: live.late.length ? 'Pointer ou appeler les groupes en retard' : 'Voir la page Terrain'
    },
    {
      key: 'onsite',
      label: 'Sur place',
      value: live.onsite.length ? count(live.onsite.length, 'groupe', 'groupes') : 'Personne',
      sub: live.onsite.length
        ? `${count(players(live.onsite), 'joueur', 'joueurs')} · prochaine fin ${clock(firstEnd)}`
        : 'aucun groupe pointé en ce moment',
      tone: 'neutral',
      open: toTerrain,
      hint: 'Voir les groupes sur place sur la page Terrain'
    },
    {
      key: 'closing',
      label: 'À clôturer',
      value: live.closing.length ? moneyForRole(closingAmount) : 'Rien',
      sub: live.closing.length
        ? `${count(live.closing.length, 'groupe a', 'groupes ont')} fini sans payer`
        : 'les groupes finis ont payé',
      tone: live.closing.length ? 'critical' : 'ok',
      open: live.closing.length ? "openStaffDashboardDetail('alerts', 'overdue')" : toTerrain,
      hint: live.closing.length ? 'Encaisser les groupes qui ont fini' : 'Voir la page Terrain'
    }
  ];
  return `<section class="dash-now" aria-labelledby="dashNowTitle">
    <div class="dash-now-head">
      <div class="dash-card-titles"><h2 id="dashNowTitle">En ce moment</h2><span class="dash-card-meta">${escapeHtml(clock(live.now))}</span></div>
      <button type="button" class="dash-now-link" onclick="${toTerrain}">Ouvrir le Terrain</button>
    </div>
    <div class="dash-now-grid">
      ${cells.map(cell => `<button type="button" class="dash-now-cell tone-${cell.tone}" data-now="${cell.key}" onclick="${escapeHtml(cell.open)}" title="${escapeHtml(cell.hint)}">
        <span class="dash-now-label"><span class="dash-now-dot" aria-hidden="true"></span>${escapeHtml(cell.label)}</span>
        <strong class="dash-now-value">${escapeHtml(cell.value)}</strong>
        <small class="dash-now-sub">${escapeHtml(cell.sub)}</small>
      </button>`).join('')}
    </div>
  </section>`;
}

// La carte du dashboard GROUPE par gravite (Prioritaire / A traiter / A
// suivre) : le comptoir lit l'ordre d'attaque d'un coup d'oeil au lieu d'une
// liste plate. Chaque ligne s'ouvre sur SA surface de resolution (le detail
// pre-filtre, ou tout se repare sur place).
//
// « À FAIRE » (2026-09-25) : la meme carte recoit aussi ce qui attend dans la
// boite mail (getDashInboxTodos). Une ligne mail porte sa propre destination
// (`open`) : la page Emails, a la bonne section, jamais le detail des alertes
// de la journee qui ne la connait pas. `inboxKnown` faux (lecture en cours,
// refusee ou en panne) interdit de dire « tout est a jour » : un compte
// absent n'est pas un zero.
const DASH_TODO_ICONS = {
  payment: 'euro', overdue: 'clock', noshow: 'userCheck', review: 'shield', warning: 'alert',
  maintenance: 'wrench', lead: 'users', inbox: 'mail', agent: 'bulb', bounce: 'mailOff'
};

function renderDashTodoRow(alert) {
  const meta = getStaffAlertPriorityMeta(alert);
  const action = alert.open
    ? alert.open
    : `openStaffDashboardDetail('alerts', '${escapeJsString(alert.kind)}')`;
  const label = alert.cta || getStaffAlertCtaLabel(alert.kind);
  return `<div class="dash-alert-row ${escapeHtml(alert.kind)}" data-todo="${escapeHtml(alert.kind)}">
        <span class="dash-todo-icon pr-${escapeHtml(meta.tone)}" aria-hidden="true">${renderDashboardIcon(DASH_TODO_ICONS[alert.kind] || 'check')}</span>
        <div class="dash-alert-copy"><strong>${escapeHtml(alert.title)}</strong><p>${escapeHtml(alert.text)}</p></div>
        <div class="dash-alert-actions">
          <button type="button" class="dash-alert-cta" onclick="${escapeHtml(action)}">${escapeHtml(label)}</button>
        </div>
      </div>`;
}

function renderStaffDashboardAlerts(metrics, extra = [], inboxKnown = true) {
  const definitions = getStaffDashboardAlertDefinitions(metrics);
  const alerts = [...extra, ...definitions.filter(alert => !alert.band)];
  if (!alerts.length) {
    // Le retard et l argent des groupes finis vivent dans « En ce moment » :
    // une liste vide ne dit « Tout est à jour » que si le bandeau est calme.
    if (definitions.some(alert => alert.band)) {
      return `<div class="dash-todo-empty">
        <div class="dash-alert-copy"><strong>Rien d’autre à traiter</strong><p>Demandes, mails et vérifications sont à jour.</p></div>
      </div>`;
    }
    if (!inboxKnown) {
      return `<div class="dash-todo-empty">
        <div class="dash-alert-copy"><strong>Aucune alerte sur la journée</strong><p>Paiements, séances, demandes et pistes sont sous contrôle. La boîte mail n'a pas pu être lue.</p></div>
      </div>`;
    }
    return `<div class="dash-todo-empty is-clear">
      <span class="dash-todo-icon pr-ok" aria-hidden="true">${renderDashboardIcon('check')}</span>
      <div class="dash-alert-copy"><strong>Tout est à jour</strong><p>Rien ne vous attend : paiements, séances, demandes, pistes et mails sont traités.</p></div>
    </div>`;
  }
  const ordered = [...alerts].sort((left, right) => getStaffAlertPriorityMeta(left).rank - getStaffAlertPriorityMeta(right).rank);
  const groups = [];
  ordered.forEach(alert => {
    const meta = getStaffAlertPriorityMeta(alert);
    let group = groups.find(entry => entry.meta.tone === meta.tone);
    if (!group) { group = { meta, items: [] }; groups.push(group); }
    group.items.push(alert);
  });
  // Le plafond ne vise que les alertes de la journee : « Voir toutes » ouvre
  // leur detail, qui ne connait pas les lignes mail. Ces dernieres (trois au
  // plus) restent donc toujours visibles, sinon le compteur promettrait de les
  // montrer ailleurs.
  const shown = { count: 0 };
  const MAX_ROWS = 6;
  const rendered = groups.map(group => {
    const items = group.items.filter(alert => alert.open || (shown.count += 1) <= MAX_ROWS);
    if (!items.length) return '';
    return `<div class="dash-alert-group">
      <div class="dash-alert-group-head pr-${escapeHtml(group.meta.tone)}"><span class="priority-dot" aria-hidden="true"></span>${escapeHtml(group.meta.label)}<em>${group.items.length}</em></div>
      <div class="dash-alert-rows">${items.map(renderDashTodoRow).join('')}</div>
    </div>`;
  }).join('');
  const dayAlerts = ordered.filter(alert => !alert.open).length;
  const hidden = dayAlerts - Math.min(dayAlerts, MAX_ROWS);
  return rendered + (hidden > 0
    ? `<button type="button" class="dash-alert-more" onclick="openStaffDashboardAlerts()">+ ${hidden} autre${hidden > 1 ? 's' : ''} signal${hidden > 1 ? 'aux' : ''} · Voir toutes</button>`
    : '');
}

// Libellé du bouton d'action rapide inline selon le type d'alerte : mène
// directement à la surface de résolution (détail « Voir toutes ») pré-filtrée.
function getStaffAlertCtaLabel(kind) {
  return {
    payment: 'Encaisser',
    overdue: 'Clôturer',
    noshow: 'Pointer',
    review: 'Vérifier',
    warning: 'Traiter',
    maintenance: 'Libérer',
    lead: 'Traiter les demandes'
  }[kind] || 'Résoudre';
}

function niceRevenueScale(rawMax) {
  const value = Math.max(Number(rawMax) || 0, 100);
  const target = 4;
  const rough = value / target;
  const pow = Math.pow(10, Math.floor(Math.log10(rough)));
  const candidates = [1, 2, 2.5, 5, 10];
  let step = 10 * pow;
  for (const candidate of candidates) {
    if (candidate * pow >= rough) { step = candidate * pow; break; }
  }
  const max = Math.max(step, Math.ceil(value / step) * step);
  return { max, step };
}

function formatMoneyShort(value) {
  if (montantsMasques()) return '···';
  const amount = Math.round(Number(value) || 0);
  if (Math.abs(amount) >= 1000) {
    const k = amount / 1000;
    const text = Number.isInteger(k) ? String(k) : k.toFixed(1).replace('.', ',');
    return `${text}k €`;
  }
  return `${amount} €`;
}

function openStaffDashboardSection(section) {
  if (section === 'planning') {
    state.staffMenuPage = 'planning';
    save();
    renderStaff();
    syncOpsSidebar();
    return;
  }
  if (section === 'clients') {
    state.staffMenuPage = 'clients';
    save();
    renderStaff();
    syncOpsSidebar();
    return;
  }
  if (section === 'reservations') {
    state.staffMenuPage = 'reservations';
    state.staffStatusFilter = 'all';
    save();
    renderStaff();
    syncOpsSidebar();
    return;
  }
  if (section === 'direction') {
    setView('admin');
    openAdminTab('overview');
  }
}

// CE QUI ATTEND, ET SEULEMENT CE QUI ATTEND. Un groupe de ce soir qui n a pas
// encore paye n est pas une tache : « 19 réservations non payées » comptait
// les groupes pas encore venus, et les memes groupes finis revenaient une
// seconde fois sous « Séances terminées ». Le jour meme, le retard et
// l argent des groupes finis se lisent dans le bandeau « En ce moment »
// (band: true, hors de la liste), sur la regle de la page Terrain ; leurs
// panneaux restent ouverts d un clic. Une date passee garde les dossiers
// jamais soldes ; une date future n a rien a encaisser.
function getStaffDashboardAlertDefinitions(metrics) {
  const alerts = [];
  const live = metrics.liveNow;
  if (live) {
    if (live.closing.length) {
      const rows = live.closing.map(item => item.reservation);
      alerts.push({
        kind: 'overdue',
        band: true,
        priority: 'critical',
        title: 'À clôturer',
        text: `${rows.length} groupe${rows.length > 1 ? 's ont' : ' a'} fini sans être encaissé${rows.length > 1 ? 's' : ''} · ${formatMoney(sumStaffRowsAmount(rows))}`,
        rows,
        action: 'Encaisser chaque dossier avant que le groupe ne quitte le centre, ou clôturer si c\'est déjà réglé.'
      });
    }
    if (live.late.length) {
      const rows = live.late.map(item => item.reservation);
      alerts.push({
        kind: 'noshow',
        band: true,
        priority: 'important',
        title: 'En retard',
        text: `${rows.length} groupe${rows.length > 1 ? 's' : ''} attendu${rows.length > 1 ? 's' : ''}, pas encore pointé${rows.length > 1 ? 's' : ''}`,
        rows,
        action: 'Pointer « Arrivé » si le groupe est là ; sinon appeler le client avant de libérer la piste.'
      });
    }
  } else if (state.currentDate < todayStr()) {
    const unpaidRows = metrics.activeReservations.filter(reservation => reservation.status !== 'paid');
    if (unpaidRows.length) {
      alerts.push({
        kind: 'payment',
        priority: 'important',
        title: 'Paiements non soldés',
        text: `${unpaidRows.length} réservation${unpaidRows.length > 1 ? 's' : ''} jamais marquée${unpaidRows.length > 1 ? 's' : ''} payée${unpaidRows.length > 1 ? 's' : ''} · ${formatMoney(sumStaffRowsAmount(unpaidRows))}`,
        rows: unpaidRows,
        action: 'Marquer payé ce qui a été encaissé ; le reste se clôture depuis la fiche.'
      });
    }
  }
  const reviewRows = metrics.activeReservations.filter(reservation =>
    reservation.status !== 'cancelled'
    && reservation.validationStatus !== 'confirmed'
    && (reservation.validationStatus === 'staff_review'
      || reservation.riskLevel === 'high'
      || reservation.riskLevel === 'critical'));
  if (reviewRows.length) {
    alerts.push({
      kind: 'review',
      priority: 'important',
      title: 'Réservations à vérifier',
      text: `${reviewRows.length > 1 ? `${reviewRows.length} réservations attendent` : '1 réservation attend'} la validation de l’équipe`,
      rows: reviewRows,
      action: 'Valider, ouvrir la fiche ou contacter le client pour lever le doute sur chaque réservation.'
    });
  }
  const lateLaserWindows = metrics.laserWindows.filter(window => window.end > metrics.planningWindow.close);
  if (lateLaserWindows.length) {
    const rows = [...new Map(lateLaserWindows.map(window => [window.reservation.id, window.reservation])).values()];
    const closeLabel = formatClockDisplay(metrics.planningWindow.close);
    alerts.push({
      kind: 'warning',
      priority: 'critical',
      title: 'Laser après fermeture',
      text: `${rows.length} réservation${rows.length > 1 ? 's' : ''} laser se termine${rows.length > 1 ? 'nt' : ''} après ${closeLabel}`,
      rows,
      windows: lateLaserWindows,
      action: `Ces sessions dépassent l'heure de fermeture (${closeLabel}) : vérifier le lancement laser ou décaler le créneau.`
    });
  }
  const maintenanceLanes = Object.entries(state.laneStatuses || {})
    .filter(([, status]) => status === 'maintenance')
    .map(([lane]) => Number(lane))
    .sort((a, b) => a - b);
  if (maintenanceLanes.length) {
    alerts.push({
      kind: 'maintenance',
      priority: 'info',
      title: 'Pistes en maintenance',
      text: `Piste${maintenanceLanes.length > 1 ? 's' : ''} ${maintenanceLanes.map(lane => {
        const window = state.laneMaintenance?.[lane];
        return window && window.until ? `${lane} (jusqu'au ${window.until})` : String(lane);
      }).join(', ')} bloquée${maintenanceLanes.length > 1 ? 's' : ''}`,
      lanes: maintenanceLanes,
      rows: [],
      action: 'Libérer chaque piste dès que le responsable terrain confirme qu\'elle est de nouveau exploitable.'
    });
  }
  // « Formules à enchaîner, à cadencer » est parti le 2026-09-30 : ce n etait
  // pas une tache (rien a cliquer, rien a finir), et le deroule de chaque
  // formule se lit sur Terrain et Formules.
  // Un lead sur mesure est de l'argent qui attend une réponse : il passe EN
  // TÊTE. Le compte est celui des demandes ACTIVES (ni traitées ni archivées,
  // regle du 2026-08-14). L'alerte NOMME la demande puis MENE a la page dediee
  // « Demandes sur mesure » (Movsar 2026-08-19 : « c est mal relié, faut que ça
  // emmene a notre categorie dediee pour gerer ça »). Elle ne duplique plus les
  // actions : la page les porte toutes, et mieux (repondre dans la carte,
  // convertir en reservation, segments). Ce qui avait ete refusé le 2026-08-18,
  // c'etait d'expedier vers Clients > A venir, une page qui ne parlait pas du
  // sujet ; cette page-la, elle, EST le sujet.
  const activeLeads = typeof getStaffActiveCustomRequestCount === 'function' ? getStaffActiveCustomRequestCount() : 0;
  if (activeLeads > 0) {
    alerts.unshift({
      kind: 'lead',
      priority: 'critical',
      title: `${activeLeads} demande${activeLeads > 1 ? 's' : ''} sur mesure à traiter`,
      text: 'Anniversaires, groupes et entreprises qui attendent la réponse de l’équipe.',
      rows: [],
      action: 'Tout se traite dans la page Demandes sur mesure : répondre par email, prendre en charge, convertir en réservation.'
    });
  }
  return alerts;
}

function closeStaffDashboardDetail() {
  const overlay = document.getElementById('staffDashboardDetailOverlay');
  if (overlay) overlay.remove();
  document.body.classList.remove('dashboard-detail-open');
}

function dashboardDetailSetStatus(id, status, ev, paymentMethod = '') {
  if (ev) ev.stopPropagation();
  setReservationStatusDirect(id, status, ev, paymentMethod ? { paymentMethod } : {});
  refreshStaffDashboardDetailSoon();
}

// Recalcule les metrics + alertes et re-render : le panneau dashboard en
// arrière-plan ET la modale « Voir toutes » ouverte décrémentent tout seuls
// après une résolution (paiement, validation, libération de piste…).
function refreshStaffDashboardDetailSoon(delay = 160) {
  const type = state.dashboardDetailType || 'alerts';
  const kind = state.dashboardDetailKind || '';
  window.setTimeout(() => {
    if (typeof renderStaffData === 'function' && state.view === 'staff' && state.staffMenuPage === 'dashboard') {
      try { renderStaffData(); } catch (error) { /* le dashboard peut ne plus être monté */ }
    }
    if (document.getElementById('staffDashboardDetailOverlay')) openStaffDashboardDetail(type, kind);
  }, delay);
}

// Ouvre la fiche réservation pré-sélectionnée depuis une alerte.
function dashboardDetailOpenReservation(id) {
  closeStaffDashboardDetail();
  openPos(id);
}

// Ouvre le centre de communication (mail + SMS) pour contacter le client
// concerné par l'alerte, en réutilisant le module existant.
function dashboardDetailContact(id) {
  closeStaffDashboardDetail();
  openCommCenter(id);
}

// Valide une réservation en attente (staff_review / risque élevé) puis
// re-render : l'item quitte la file de validation.
function dashboardDetailValidate(id, ev) {
  if (ev) ev.stopPropagation();
  validateReservationDirect(id, ev);
  refreshStaffDashboardDetailSoon(200);
}

// PATCH minimal (validationStatus='confirmed', skipReplan) : confirme la résa
// sans re-planifier. Optimiste + rollback, cohérent avec setReservationStatusDirect.
function validateReservationDirect(id, ev) {
  if (ev) ev.stopPropagation();
  if (!canUseStaffPermission('reservations.edit')) {
    toast('Validation réservée à un rôle autorisé.');
    return;
  }
  const key = String(id);
  const current = state.reservations.find(r => String(r.id) === key) || findStaffReservationById(id);
  if (current && !requirePastDatePermission(current.date)) return;
  if (!current) {
    toast('Réservation introuvable.');
    return;
  }
  if (current.validationStatus === 'confirmed') {
    toast('Réservation déjà validée.');
    return;
  }
  const nextReservation = { ...current, validationStatus: 'confirmed' };
  markReservationMutation(id, nextReservation, ['validationStatus']);
  applyOptimisticReservation(nextReservation, { preserveEditState: true });
  // PATCH PARTIEL : le serveur complete avec ce qui est en base au moment de
  // l ecriture (relu sous verrou, updateReservation), pistes comprises. Il
  // passe dans la file du dossier comme les autres ecritures de ce poste.
  enchainerEcritureReservation(id, () => apiRequest(API_ENDPOINTS.staffReservations, {
    method: 'PATCH',
    body: JSON.stringify({
      id: Number(id),
      centerId: current.centerId || current.center_id || getCurrentStaffCenterId(),
      validationStatus: 'confirmed',
      skipReplan: true
    })
  })).then(payload => {
    applyOptimisticReservation(payload.reservation, { preserveEditState: true });
    markReservationMutation(id, payload.reservation, ['validationStatus']);
    toast('Réservation validée');
  }).catch(error => {
    applyOptimisticReservation(current, { preserveEditState: true });
    clearReservationMutation(id);
    toast(error.message || 'Impossible de valider la réservation.');
  });
}

// Libère une piste en maintenance (retour à 'active') via l'endpoint pistes
// existant, avec mise à jour optimiste + rollback.
async function releaseMaintenanceLane(lane, ev) {
  if (ev) ev.stopPropagation();
  const i = Number(lane);
  if (state.laneStatuses[i] !== 'maintenance') return;
  const previousStatus = state.laneStatuses[i];
  state.laneStatuses[i] = 'active';
  save();
  try {
    const payload = await apiRequest(API_ENDPOINTS.staffLanes, {
      method: 'PATCH',
      body: JSON.stringify({ lane: i, status: 'active', centerId: getCurrentStaffCenterId() })
    });
    state.laneStatuses[i] = payload.lane?.status || 'active';
    save();
    toast(`Piste ${i} réactivée`);
  } catch (error) {
    state.laneStatuses[i] = previousStatus;
    save();
    toast(error.message || 'Impossible de libérer la piste.');
  }
}

function dashboardDetailReleaseLane(lane, ev) {
  if (ev) ev.stopPropagation();
  releaseMaintenanceLane(lane, ev);
  refreshStaffDashboardDetailSoon(220);
}

// Actions groupées (footer détail) : encaisse ou libère en un clic.
// « TOUT ENCAISSER » ENCAISSE CE QUE LE PANNEAU MONTRE, RIEN D AUTRE. Il
// marquait payees TOUTES les reservations non payees du jour, y compris les
// groupes de ce soir pas encore venus, depuis un panneau qui n en listait que
// deux (les seances finies). Les lignes viennent de l alerte ouverte.
async function dashboardDetailPayAllUnpaid(ev) {
  if (ev) ev.stopPropagation();
  const metrics = getStaffDashboardMetrics(todaysReservations());
  const kind = state.dashboardDetailKind || '';
  const alert = getStaffDashboardAlertDefinitions(metrics).find(entry => entry.kind === kind);
  const rows = (alert && alert.rows ? alert.rows : []).filter(r => r.status !== 'paid' && r.status !== 'cancelled');
  if (!rows.length) { toast('Aucune réservation à encaisser.'); return; }
  if (!(await staffConfirm({ title: `Marquer ${rows.length} réservation${rows.length > 1 ? 's' : ''} comme payée${rows.length > 1 ? 's' : ''} ?`, confirmLabel: 'Encaisser' }))) return;
  // Un encaissement en lot ne se rattrape pas d un toast : le dernier
  // dossier seul serait annulable.
  rows.forEach(r => setReservationStatusDirect(r.id, 'paid', null, { sansAnnulation: true }));
  refreshStaffDashboardDetailSoon(240);
}

async function dashboardDetailReleaseAllLanes(ev) {
  if (ev) ev.stopPropagation();
  const lanes = Object.entries(state.laneStatuses || {})
    .filter(([, status]) => status === 'maintenance')
    .map(([l]) => Number(l));
  if (!lanes.length) { toast('Aucune piste en maintenance.'); return; }
  if (!(await staffConfirm({ title: `Réactiver ${lanes.length} piste${lanes.length > 1 ? 's' : ''} ?`, confirmLabel: 'Réactiver' }))) return;
  lanes.forEach(lane => releaseMaintenanceLane(lane));
  refreshStaffDashboardDetailSoon(260);
}

function openStaffDashboardDetail(type = 'alerts', kind = '') {
  const metrics = getStaffDashboardMetrics(todaysReservations());
  state.dashboardDetailType = type;
  state.dashboardDetailKind = kind || '';
  let overlay = document.getElementById('staffDashboardDetailOverlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'staffDashboardDetailOverlay';
    document.body.appendChild(overlay);
  }
  const d = parseLocalDate(state.currentDate);
  const dateLong = d.toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const config = getStaffDashboardDetailConfig(type, kind, metrics);
  overlay.className = 'staff-dashboard-detail-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.onclick = event => {
    if (event.target === overlay) closeStaffDashboardDetail();
  };
  overlay.innerHTML = `
    <section class="dashboard-detail-modal" aria-labelledby="dashboardDetailTitle">
      <div class="dashboard-detail-head">
        <div>
          <span>${escapeHtml(config.eyebrow)}</span>
          <h2 id="dashboardDetailTitle">${escapeHtml(config.title)}</h2>
          <p>${escapeHtml(dateLong)} · ${escapeHtml(config.subtitle)}</p>
        </div>
        <button type="button" class="dashboard-detail-close" onclick="closeStaffDashboardDetail()" aria-label="Fermer">×</button>
      </div>
      <div class="dashboard-detail-summary">
        ${config.stats.map(stat => `<article><span>${escapeHtml(stat.label)}</span><strong>${escapeHtml(stat.value)}</strong><small>${escapeHtml(stat.note || '')}</small></article>`).join('')}
      </div>
      <div class="dashboard-detail-body">
        ${config.body}
      </div>
      <footer class="dashboard-detail-actions">
        ${config.actions.map(action => `<button type="button" class="${escapeHtml(action.className || 'secondary')}" onclick="${action.onclick}">${escapeHtml(action.label)}</button>`).join('')}
      </footer>
    </section>
  `;
  document.body.classList.add('dashboard-detail-open');
  overlay.querySelector('.dashboard-detail-close')?.focus({ preventScroll: true });
}

function getStaffDashboardDetailConfig(type, kind, metrics) {
  const unpaidCount = metrics.activeReservations.filter(reservation => reservation.status !== 'paid').length;
  const baseStats = [
    { label: 'Réservations', value: String(metrics.activeReservations.length), note: `${metrics.players} joueurs` },
    { label: 'À encaisser', value: moneyForRole(metrics.revenue - metrics.collected), note: `${unpaidCount} ouvertes` },
    { label: 'Occupation', value: `${metrics.occupancy}%`, note: `${metrics.laneCount} piste${metrics.laneCount > 1 ? 's' : ''}` }
  ];
  // Un bouton du pied mene a une page : il ne se montre qu a qui l ouvre
  // (2026-11-07). Sans le droit, l action vaut '' et ne se dessine pas.
  // (le planning du jour s ouvre en fenetre : on reste sur le tableau de bord, comme depuis une demande)
  const openPlanning = canUseStaffPage('planning') ? "closeStaffDashboardDetail(); openStaffRequestDay(state.currentDate);" : '';
  const openReservations = canUseStaffPage('reservations') ? "closeStaffDashboardDetail(); openStaffDashboardSection('reservations');" : '';
  const openDirection = canUseStaffPermission('direction.view') ? "closeStaffDashboardDetail(); setView('admin'); openAdminTab('overview');" : '';
  if (type === 'alerts') {
    const alerts = getStaffDashboardAlertDefinitions(metrics);
    const visibleAlerts = kind ? alerts.filter(alert => alert.kind === kind) : alerts;
    const outstanding = Math.max(0, metrics.revenue - metrics.collected);
    return {
      eyebrow: 'Pilotage terrain',
      title: kind ? (visibleAlerts[0]?.title || 'Signal dashboard') : 'Alertes et notifications',
      // LE SOUS-TITRE DIT LE PERIMETRE DU PANNEAU OUVERT, ET NE COMPTE QUE CE
      // QUI EXISTE. Sur un signal precis, il comptait les signaux VISIBLES (1)
      // pendant que la tuile juste en dessous comptait tous les signaux actifs
      // (2) : deux chiffres contradictoires a 80 px d ecart. Il compte donc les
      // dossiers concernes - MAIS deux alertes n en portent aucun par
      // construction (« Pistes en maintenance », et « N demandes sur mesure en
      // attente » qui passe en tete par unshift) : leur perimetre n est pas un
      // lot de reservations. Compter les dossiers y ecrivait « Aucune
      // reservation concernee » sous un titre qui annonce justement de l argent
      // qui attend une reponse. Sans dossier, on retombe donc sur le langage
      // des signaux : l alerte porte deja son perimetre en toutes lettres dans
      // son texte, juste en dessous.
      subtitle: (() => {
        const concernes = kind ? (visibleAlerts[0]?.rows || []).length : 0;
        if (concernes) return `${concernes} réservation${concernes > 1 ? 's' : ''} concernée${concernes > 1 ? 's' : ''}`;
        if (!visibleAlerts.length) return 'Tout est à jour, rien à traiter';
        // Le pluriel de « signal » est « signaux », pas « signalaux ».
        return `${visibleAlerts.length} ${visibleAlerts.length > 1 ? 'signaux' : 'signal'} à traiter`;
      })(),
      // Le jour meme, les trois chiffres de tete sont ceux du bandeau « En ce
      // moment » : le panneau et l accueil ne se contredisent pas (le panneau
      // « À clôturer » affichait « À encaisser 2 659 € », les groupes de ce
      // soir compris, au-dessus de deux dossiers a 262 €).
      stats: metrics.liveNow ? [
        { label: 'En retard', value: String(metrics.liveNow.late.length), note: metrics.liveNow.late.length ? 'à pointer ou appeler' : 'aucun groupe attendu' },
        { label: 'Sur place', value: String(metrics.liveNow.onsite.length), note: `groupe${metrics.liveNow.onsite.length > 1 ? 's' : ''} pointé${metrics.liveNow.onsite.length > 1 ? 's' : ''}` },
        { label: 'À clôturer', value: moneyForRole(sumStaffRowsAmount(metrics.liveNow.closing.map(item => item.reservation))), note: `${metrics.liveNow.closing.length} groupe${metrics.liveNow.closing.length > 1 ? 's' : ''} fini${metrics.liveNow.closing.length > 1 ? 's' : ''} sans payer` }
      ] : [
        { label: 'Alertes actives', value: String(alerts.length), note: alerts.length ? 'à traiter' : 'rien à signaler' },
        state.currentDate < todayStr()
          ? { label: 'Non soldé', value: moneyForRole(outstanding), note: `${unpaidCount} réservation${unpaidCount > 1 ? 's' : ''} jamais marquée${unpaidCount > 1 ? 's' : ''} payée${unpaidCount > 1 ? 's' : ''}` }
          : { label: 'Prévu', value: moneyForRole(metrics.revenue), note: `${metrics.activeReservations.length} réservation${metrics.activeReservations.length > 1 ? 's' : ''}` },
        { label: 'Joueurs', value: String(metrics.players), note: 'sur la journée' }
      ],
      body: renderStaffDashboardAlertsDetail(visibleAlerts),
      actions: getStaffDashboardAlertActions(kind, visibleAlerts, { openReservations, openPlanning })
    };
  }
  if (type === 'revenue') {
    return {
      eyebrow: 'Caisse',
      title: 'Revenus des 7 derniers jours',
      subtitle: `${formatMoney(metrics.revenue)} prévu sur la date affichée`,
      stats: [
        { label: 'Total période', value: formatMoney(metrics.revenueSeries.reduce((sum, value) => sum + value, 0)), note: '7 jours' },
        { label: 'Validé ce jour', value: formatMoney(metrics.collected), note: 'marqué payé' },
        { label: 'Reste à encaisser', value: formatMoney(Math.max(0, metrics.revenue - metrics.collected)), note: `${unpaidCount} réservation(s)` }
      ],
      body: renderStaffDashboardRevenueDetail(metrics),
      actions: [
        { label: 'Copier le résumé', onclick: "copyStaffDashboardSummary()" },
        openDirection && { label: 'Ouvrir direction', onclick: openDirection, className: 'secondary' }
      ].filter(Boolean)
    };
  }
  if (type === 'occupation') {
    return {
      eyebrow: 'Capacité pistes',
      title: 'Occupation par heure',
      subtitle: 'lecture détaillée des créneaux piste',
      stats: baseStats,
      body: renderStaffDashboardOccupationDetail(metrics),
      actions: [
        openPlanning && { label: 'Ouvrir le planning', onclick: openPlanning },
        peutGeste('reserver') && { label: 'Nouvelle réservation', onclick: "closeStaffDashboardDetail(); openQuickBook({ date: state.currentDate, type: 'bowling' });", className: 'secondary' }
      ].filter(Boolean)
    };
  }
  if (type === 'activity') {
    // Les trois compteurs de tete suivent le mix REEL du jour (les trois plus
    // gros buckets), plus jamais un triptyque bowling / laser / complet fige.
    const topBuckets = metrics.activityMix.slice(0, 3);
    return {
      eyebrow: 'Mix activité',
      title: 'Réservations par activité',
      subtitle: 'toutes les activités du catalogue vendues sur la date affichée',
      stats: topBuckets.length
        ? topBuckets.map(bucket => ({ label: bucket.label, value: String(bucket.count), note: moneyForRole(bucket.revenue) }))
        : [{ label: 'Réservations', value: '0', note: 'aucune sur cette date' }],
      body: renderStaffDashboardActivityDetail(metrics),
      actions: openReservations ? [
        { label: 'Voir réservations', onclick: openReservations },
        { label: 'Voir toutes les réservations', onclick: "closeStaffDashboardDetail(); setStaffResourceView('all');", className: 'secondary' }
      ] : []
    };
  }
  // Le panneau par defaut etait « Prochaines arrivees », ouvert par la carte du
  // meme nom. La carte partie, plus rien n'ouvrait ce panneau : le defaut
  // devient donc les alertes, la seule surface du dashboard qui appelle une
  // action. Un type inconnu (etat sauvegarde d'une ancienne session, par
  // exemple) retombe ici, donc sur un ecran qui existe.
  return getStaffDashboardDetailConfig('alerts', kind, metrics);
}

// LE MOT D UN DOSSIER EST CELUI DE LA LISTE (2026-10-08). La fiche et les
// lignes de la Vue d ensemble lisaient le STATUT enregistre : « Confirmé »
// sur un groupe que la liste montrait « En retard » ou « À clôturer »,
// « Arrivé » sur un groupe parti depuis une heure. Elles disent maintenant sa
// section (getStaffListeSection), calculee sur le jour du dossier.
function getStaffDashboardStatusMeta(reservation) {
  if (reservation.status === 'cancelled') return { label: 'Annulé', className: 'cancelled' };
  const moments = getStaffReservationMoments([reservation], reservation.date || state.currentDate);
  const section = getStaffListeSection(moments, reservation);
  // Une demande qui attend sa validation le dit d abord, meme en retard ou
  // finie : c est le geste qui reste a faire (« Valider »).
  if (section !== 'paid' && section !== 'absent' && isReservationAwaitingReview(reservation)) return { label: 'À vérifier', className: 'review' };
  return {
    late: { label: 'En retard', className: 'late' },
    upcoming: { label: 'À venir', className: 'pending' },
    onsite: { label: 'Sur place', className: 'arrived' },
    closing: { label: 'À clôturer', className: 'closing' },
    paid: { label: 'Payé', className: 'paid' },
    absent: { label: 'Pas venu', className: 'absent' },
  }[section];
}

function getStaffDashboardReservationOffer(reservation) {
  if (reservation.type === 'formule' || reservation.formuleId) return reservation.formuleName || `Formule ${String(reservation.formuleId || '').replace(/\D/g, '') || ''}`.trim();
  if (getLaserWindowsFromReservation(reservation).length && !getBowlingWindowsFromReservation(reservation).length) return `${getLaserGameCountForReservation(reservation)} partie${getLaserGameCountForReservation(reservation) > 1 ? 's' : ''} Laser Game`;
  const duration = Number(reservation.duration || 1);
  return `Bowling ${duration === 1 ? '1h' : `${String(duration).replace('.', 'h')}`}`;
}

function getStaffDashboardReservationResources(reservation) {
  const bowling = getBowlingWindowsFromReservation(reservation).map(window => {
    const lanes = (window.lanes || []).length ? `piste${window.lanes.length > 1 ? 's' : ''} ${window.lanes.join(', ')}` : 'piste à confirmer';
    return `Bowling ${formatClockDisplay(window.start)}-${formatClockDisplay(window.end)} · ${lanes}`;
  });
  const laser = getLaserWindowsFromReservation(reservation).map(window => {
    const part = window.countIndex ? ` partie ${window.countIndex}/${getLaserGameCountForReservation(reservation)}` : '';
    return `Laser ${formatClockDisplay(window.start)}-${formatClockDisplay(window.end)}${part}`;
  });
  return [...bowling, ...laser].join(' · ') || 'Hors piste';
}

function renderStaffDashboardReservationRows(rows = [], emptyText = 'Aucune donnée à afficher.', kind = '') {
  if (!rows.length) return `<div class="dashboard-detail-empty">${escapeHtml(emptyText)}</div>`;
  return rows.map(reservation => {
    const status = getStaffDashboardStatusMeta(reservation);
    const start = getReservationFirstResourceStart(reservation, 'all');
    return `<article class="dashboard-detail-row ${escapeHtml(status.className)} ${getReservationHighlightClasses(reservation)}">
      <div class="dashboard-detail-time"><strong>${escapeHtml(formatClockDisplay(start))}</strong><span>${escapeHtml(status.label)}</span></div>
      <div class="dashboard-detail-main">
        <strong>${escapeHtml(reservation.name || 'Client')}</strong>
        <span>${escapeHtml(getStaffDashboardReservationOffer(reservation))} · ${Number(reservation.pax || 0)} joueur${Number(reservation.pax || 0) > 1 ? 's' : ''}</span>
        <small>${escapeHtml(getStaffDashboardReservationResources(reservation))}</small>
      </div>
      <div class="dashboard-detail-amount">
        <strong>${canUseStaffPermission('payments.view') ? formatMoneyCentimes(reservation.price || 0) : '···'}</strong>
        ${/* LE PREMIER ECRAN DE LA CONSOLE LISAIT LA REGLE NULLE PART. Ces
             lignes imprimaient le montant nu, donc un geste commercial y
             passait pour un tarif catalogue - sur l ecran d ouverture, et sur
             la surface meme que le constat visait. Le montant reste, la
             pastille s ajoute seulement en cas d ecart, en forme « mot »
             puisque le chiffre est deja la juste au-dessus. */''}
        ${renderReservationPriceMark(reservation, { forme: 'mot' })}
        <span>${escapeHtml(reservation.paymentMethod || (reservation.status === 'paid' ? 'Comptoir' : 'Sur place'))}</span>
      </div>
      <div class="dashboard-detail-row-actions">
        ${renderDashboardRowActions(reservation, kind)}
      </div>
    </article>`;
  }).join('');
}

// Boutons d'action réels par type d'alerte : chacun EXÉCUTE la résolution
// (statut, validation) ou mène à l'endroit exact pré-sélectionné (fiche, comm).
// Chaque bouton est masqué si le rôle courant n'a pas la permission requise.
function renderDashboardRowActions(reservation, kind) {
  const id = Number(reservation.id);
  // Chaque bouton lit la regle du serveur pour son geste (peutGeste) :
  // « Payé » demande l etat ET l encaissement, « Contacter » ouvre un mail a
  // ecrire, « Valider » un jour passe demande « Changer un jour passé ».
  const canPay = peutGeste('encaisser');
  const canStatus = peutGeste('etat');
  const canContact = peutGeste('ecrire');
  const fiche = `<button type="button" onclick="dashboardDetailOpenReservation(${id})">Fiche</button>`;
  const open = `<button type="button" class="primary" onclick="dashboardDetailOpenReservation(${id})">Ouvrir la réservation</button>`;
  const contact = canContact ? `<button type="button" onclick="dashboardDetailContact(${id})">Contacter</button>` : '';
  // Encaisser note le moyen (2026-10-01) : Carte ou Espèces, jamais un « Payé »
  // muet que la Direction ne saurait pas ranger.
  const payer = (classe) => (canPay && reservation.status !== 'paid')
    ? GROUPE_MOYENS.map(m => `<button type="button"${classe ? ` class="${classe}"` : ''} onclick="dashboardDetailSetStatus(${id}, 'paid', event, '${m.valeur}')">Payé · ${m.mot}</button>`).join('') : '';
  const encaisser = payer('primary');
  const arrived = (canStatus && reservation.status !== 'arrived' && reservation.status !== 'paid')
    ? `<button type="button" onclick="dashboardDetailSetStatus(${id}, 'arrived', event)">Arrivé</button>` : '';
  const arrivedPrimary = (canStatus && reservation.status !== 'arrived' && reservation.status !== 'paid')
    ? `<button type="button" class="primary" onclick="dashboardDetailSetStatus(${id}, 'arrived', event)">Arrivé</button>` : '';
  const valider = peutGeste('valider', reservation.date)
    ? `<button type="button" class="primary" onclick="dashboardDetailValidate(${id}, event)">Valider</button>` : '';
  if (kind === 'review') return `${valider}${fiche}${contact}`;
  if (kind === 'payment') return `${encaisser}${arrived}${fiche}`;
  if (kind === 'overdue') return `${encaisser}${fiche}${contact}`;
  if (kind === 'noshow') return `${arrivedPrimary}${contact}${fiche}`;
  if (kind === 'warning') return `${open}${contact}`;
  // Vue par défaut (arrivées, activité…)
  return `${fiche}${arrived}${payer('')}`;
}

// Actions du footer de la modale détail, spécialisées par type d'alerte.
function getStaffDashboardAlertActions(kind, visibleAlerts, nav) {
  const actions = [];
  if (kind === 'payment' && peutGeste('encaisser')) {
    actions.push({ label: 'Tout encaisser', onclick: 'dashboardDetailPayAllUnpaid(event)', className: 'primary' });
  }
  if (kind === 'maintenance' && peutGeste('fermerPiste')) {
    actions.push({ label: 'Libérer toutes les pistes', onclick: 'dashboardDetailReleaseAllLanes(event)', className: 'primary' });
  }
  if (kind === 'overdue' && peutGeste('encaisser')) {
    actions.push({ label: 'Tout encaisser', onclick: 'dashboardDetailPayAllUnpaid(event)', className: 'primary' });
  }
  if (kind === 'lead' && canUseStaffPage('requests')) {
    actions.push({ label: 'Ouvrir les demandes sur mesure', onclick: 'openStaffRequestsPage(null, event)', className: 'primary' });
  }
  if (nav.openReservations) actions.push({ label: 'Voir toutes les réservations', onclick: nav.openReservations, className: actions.length ? 'secondary' : '' });
  if (nav.openPlanning) actions.push({ label: 'Ouvrir le planning', onclick: nav.openPlanning, className: 'secondary' });
  return actions;
}

// Niveaux d'importance des alertes : repère visuel + ordre de tri (rank).
// critical = Prioritaire (rouge) · important = À traiter (orange) · info = À suivre (bleu).
const STAFF_ALERT_PRIORITY = {
  critical: { rank: 0, tone: 'critical', label: 'Prioritaire' },
  important: { rank: 1, tone: 'important', label: 'À traiter' },
  info: { rank: 2, tone: 'info', label: 'À suivre' }
};

// Priorité par défaut si l'alerte n'en porte pas (robustesse).
const STAFF_ALERT_PRIORITY_FALLBACK = {
  payment: 'important', overdue: 'critical', noshow: 'important', review: 'important', warning: 'critical', maintenance: 'info'
};

function getStaffAlertPriorityMeta(alert) {
  const level = alert.priority || STAFF_ALERT_PRIORITY_FALLBACK[alert.kind] || 'info';
  return STAFF_ALERT_PRIORITY[level] || STAFF_ALERT_PRIORITY.info;
}

// Tri lecture rapide : plus tôt en premier, puis plus gros montant en premier.
function sortStaffAlertRows(rows = []) {
  return [...rows].sort((left, right) =>
    (getReservationFirstResourceStart(left, 'all') - getReservationFirstResourceStart(right, 'all'))
    || ((Number(right.price) || 0) - (Number(left.price) || 0)));
}

function sumStaffRowsAmount(rows = []) {
  return rows.reduce((sum, reservation) => sum + (Number(reservation.price) || 0), 0);
}

// Les dossiers d une alerte, du plus tot au plus tard. Le paiement ne vit
// plus que sur une date passee : plus de « sur place » ni d « à venir » a
// separer.
function getStaffAlertSubsections(alert) {
  const rows = alert.rows || [];
  if (!rows.length) return [];
  return [{ key: 'all', tone: '', showTotal: false, label: '', rows: sortStaffAlertRows(rows) }];
}

// LES DEMANDES SUR MESURE SE TRAITENT DANS LE PANNEAU D'ALERTES : chaque
// demande active (nouvelle ou en cours) est listee avec ses actions reelles
// (repondre par email, appeler, prendre en charge, marquer traitee, ouvrir la
// fiche complete). Avant, ce signal expediait vers la page Clients sans
// contexte : la classe d'ecart que Movsar a nommee le 2026-08-18.
// Ce qui attend l EQUIPE, dans l ordre de l heure promise au client : la meme
// liste que l onglet « A traiter », sous un titre qui dit le meme chiffre
// (2026-09-29). La liste montrait aussi les demandes qui attendent le client,
// sous un titre qui ne les comptait pas.
function renderStaffAlertLeadRows() {
  const items = getStaffCustomRequestItems().filter(item => staffRequestStage(item) === 'a-traiter').sort(staffRequestCompare('atraiter'));
  if (!items.length) {
    return '<div class="dashboard-detail-empty">Rien à traiter : chaque demande a sa réponse.</div>';
  }
  return items.map(item => {
    const jid = staffClientJs(item.id);
    const d = crDemande(item);
    const occKey = String(item.occasion || '').toLowerCase();
    const joueurs = d ? Number(d.participants) || 0 : Number(item.pax) || 0;
    const quand = staffRequestWhenShort(item);
    const metaParts = [
      (d && d.groupTypeLabel) || STAFF_OCCASION_LABELS[occKey] || '',
      (d && d.organisation) || item.company || '',
      quand ? `Souhait : ${quand}` : '',
      joueurs ? `${joueurs} pers.` : ''
    ].filter(Boolean).join(' · ');
    const due = staffRequestDue(item);
    return `<article class="dashboard-detail-row lead" data-item-id="${escapeHtml(String(item.id))}">
      <div class="dashboard-detail-main">
        <strong>${escapeHtml(item.contactName || 'Contact')} ${renderStaffRequestStageBadge(item)}${due ? ` <span class="req-due is-${due.tone}" title="${escapeHtml(due.long)}">${escapeHtml(due.court)}</span>` : ''}</strong>
        ${metaParts ? `<span>${escapeHtml(metaParts)}</span>` : ''}
        <small>${escapeHtml(String(item.message || '').slice(0, 220))}</small>
      </div>
      ${canUseStaffPage('requests') ? `<div class="dashboard-detail-row-actions">
        <button type="button" class="primary" onclick="openStaffRequestsPage(${jid}, event)">Gérer cette demande</button>
      </div>` : ''}
    </article>`;
  }).join('');
}

// L'ALERTE MENE A LA PAGE DEDIEE (Movsar, 2026-08-19 : « l alerte pour ça c est
// mal relié, faut que ça emmene a notre categorie dediee pour gerer ça »).
// Elle ouvre « Demandes sur mesure », pose le segment qui CONTIENT la demande
// (une demande traitée vit dans « Traitées » : ouvrir « À traiter » afficherait
// une page vide sur un clic parfaitement valide), puis la designe a l'ecran.
// Le rendu de la page est synchrone mais la carte n'existe qu'apres lui : le
// repere se pose au tour suivant, et se re-tente une fois si le reseau finit
// de charger les demandes entre-temps.
function openStaffRequestsPage(id, ev) {
  if (ev && typeof ev.stopPropagation === 'function') ev.stopPropagation();
  if (typeof closeStaffDashboardDetail === 'function') closeStaffDashboardDetail();
  const item = getStaffCustomRequestItems().find(entry => String(entry.id) === String(id));
  // L onglet ou vit la demande (son etape) : une demande en attente du client
  // s ouvrait dans « A traiter », ou elle n est pas.
  state.staffRequestSegment = item ? staffRequestSegmentOf(item) : 'atraiter';
  // L alerte parle d une demande : c est sa fiche qui s ouvre.
  state.staffRequestSelectedId = id != null ? String(id) : null;
  save();
  openStaffMenuPage('requests');
}
window.openStaffRequestsPage = openStaffRequestsPage;

// Change le statut d'une demande depuis le panneau d'alertes, puis re-rend :
// le compteur et la liste se mettent a jour sans quitter la surface.
function dashboardDetailLeadStatus(id, status, ev) {
  if (ev) ev.stopPropagation();
  setStaffCustomRequestStatus(id, status);
  refreshStaffDashboardDetailSoon(350);
}

function renderStaffAlertSubsection(sub, kind) {
  const total = sumStaffRowsAmount(sub.rows);
  const metaText = `${sub.rows.length} résa${sub.rows.length > 1 ? 's' : ''}${sub.showTotal && total > 0 ? ` · ${formatMoney(total)}` : ''}`;
  const head = sub.label
    ? `<div class="alert-subsection-head tone-${escapeHtml(sub.tone || 'neutral')}">
        <span class="alert-subsection-title">${sub.icon ? `<span class="alert-subsection-icon" aria-hidden="true">${escapeHtml(sub.icon)}</span>` : ''}${escapeHtml(sub.label)}</span>
        <span class="alert-subsection-meta">${escapeHtml(metaText)}</span>
      </div>`
    : '';
  return `<div class="alert-subsection tone-${escapeHtml(sub.tone || 'neutral')}">
    ${head}
    ${renderStaffDashboardReservationRows(sub.rows, 'Aucun élément à traiter.', kind)}
  </div>`;
}

function renderStaffDashboardAlertsDetail(alerts = []) {
  if (!alerts.length) {
    return `<div class="dashboard-detail-empty">Aucune alerte active. Les réservations restent surveillées en temps réel.</div>`;
  }
  const canRelease = canUseStaffPermission(['planning.drag', 'settings.manage']);
  // Ordonne du plus urgent (Prioritaire) au moins urgent (À suivre). Tri stable :
  // à rang égal, l'ordre métier d'origine (paiement > vérif > laser > …) est conservé.
  const ordered = [...alerts].sort((left, right) => getStaffAlertPriorityMeta(left).rank - getStaffAlertPriorityMeta(right).rank);
  return ordered.map(alert => {
    const meta = getStaffAlertPriorityMeta(alert);
    const rows = alert.rows || [];
    const total = sumStaffRowsAmount(rows);
    // Une demande sur mesure n'est PAS une réservation : elle n'occupe aucun
    // créneau. Le compteur du détail doit dire « demande », jamais « résa »,
    // et compter les ACTIVES (ni traitées ni archivées, règle du 2026-08-14).
    const leadCount = typeof getStaffActiveCustomRequestCount === 'function' ? getStaffActiveCustomRequestCount() : 0;
    const count = alert.kind === 'maintenance' ? (alert.lanes || []).length
      : alert.kind === 'lead' ? leadCount
        : rows.length;
    const countLabel = alert.kind === 'maintenance'
      ? `${count} piste${count > 1 ? 's' : ''}`
      : alert.kind === 'lead'
        ? `${count} demande${count > 1 ? 's' : ''}`
        : `${count} résa${count > 1 ? 's' : ''}`;
    const laneChips = alert.lanes?.length
      ? `<div class="dashboard-detail-lane-chips">${alert.lanes.map(lane => `<span class="lane-chip">Piste ${Number(lane)}${canRelease ? `<button type="button" class="lane-release" onclick="dashboardDetailReleaseLane(${Number(lane)}, event)">Libérer</button>` : ''}</span>`).join('')}</div>`
      : '';
    const subsections = getStaffAlertSubsections(alert);
    const body = alert.kind === 'lead'
      ? renderStaffAlertLeadRows()
      : subsections.length
        ? subsections.map(sub => renderStaffAlertSubsection(sub, alert.kind)).join('')
        : (laneChips ? '' : `<div class="dashboard-detail-empty">Pas de réservation liée à ce signal.</div>`);
    return `<section class="dashboard-detail-section alert-section pr-${meta.tone} alert-${escapeHtml(alert.kind)}">
      <div class="alert-section-head">
        <div class="alert-section-heading">
          <span class="priority-badge pr-${meta.tone}"><span class="priority-dot" aria-hidden="true"></span>${escapeHtml(meta.label)}</span>
          <h3>${escapeHtml(alert.title)}</h3>
        </div>
        <div class="alert-section-meta">
          <span class="alert-count">${escapeHtml(countLabel)}</span>
          ${total > 0 ? `<span class="alert-total">${formatMoney(total)}</span>` : ''}
        </div>
      </div>
      <p class="alert-section-note">${escapeHtml(alert.action || alert.text)}</p>
      ${laneChips}
      ${body}
    </section>`;
  }).join('');
}

function renderStaffDashboardRevenueDetail(metrics) {
  // Chaque colonne vient des series de metrics : elles portent la verite
  // SERVEUR pour les jours passes (voir staffDaySeriesCache), plus jamais le
  // cache local qui ne connaissait que les dates visitees sur ce poste.
  const days = Array.from({ length: 7 }, (_, index) => addDays(state.currentDate, index - 6));
  const rows = days.map((date, index) => ({
    date,
    count: metrics.reservationSeries[index] || 0,
    revenue: metrics.revenueSeries[index] || 0,
    collected: metrics.collectedSeries[index] || 0
  }));
  const max = Math.max(...rows.map(row => row.revenue), 1);
  return `<div class="dashboard-detail-section">
    <div class="dashboard-detail-section-head"><h3>Détail caisse</h3><p>Prévu, encaissé et reste à suivre sur les 7 derniers jours.</p></div>
    <div class="dashboard-detail-revenue-list">
      ${rows.map(row => `<div class="dashboard-detail-revenue-row">
        <time>${escapeHtml(parseLocalDate(row.date).toLocaleDateString('fr-BE', { weekday: 'short', day: 'numeric', month: 'short' }).replace('.', ''))}</time>
        <span><i style="width:${Math.max(4, Math.round((row.revenue / max) * 100))}%"></i></span>
        <strong>${formatMoney(row.revenue)}</strong>
        <small>${row.count} rés. · ${formatMoney(row.collected)} encaissés</small>
      </div>`).join('')}
    </div>
  </div>`;
}

function renderStaffDashboardOccupationDetail(metrics) {
  const rows = [];
  const { planningWindow, bowlingWindows } = metrics;
  if (!planningWindow.closed) {
    for (let hour = planningWindow.open; hour < planningWindow.close; hour++) {
      const windows = bowlingWindows.filter(window => Math.max(0, Math.min(hour + 1, window.end) - Math.max(hour, window.start)) > 0);
      const laneLoad = windows.reduce((sum, window) => sum + Math.max((window.lanes || []).length, 1), 0);
      rows.push({ hour, windows, laneLoad });
    }
  }
  return `<div class="dashboard-detail-section">
    <div class="dashboard-detail-section-head"><h3>Lecture horaire</h3><p>Charge piste approximative par heure, utile avant de déplacer une réservation.</p></div>
    <div class="dashboard-detail-hour-grid">
      ${rows.map(row => `<article>
        <time>${escapeHtml(formatClockDisplay(row.hour))}</time>
        <strong>${row.laneLoad}/${metrics.laneCount}</strong>
        <span>${row.windows.length} bloc${row.windows.length > 1 ? 's' : ''}</span>
        <small>${row.windows.slice(0, 3).map(window => escapeHtml(window.reservation.name || 'Client')).join(', ') || 'Disponible'}</small>
      </article>`).join('') || `<div class="dashboard-detail-empty">Centre fermé sur cette date.</div>`}
    </div>
  </div>`;
}

// UNE SECTION PAR ACTIVITE DU CATALOGUE presente aujourd'hui (occurrences :
// une visite bowling + billards apparait dans les deux sections, c'est la
// question du comptoir « qu'est-ce qui tourne »). Fini le triptyque fige.
function renderStaffDashboardActivityDetail(metrics) {
  const groups = metrics.activityOccurrences;
  if (!groups.length) {
    return '<div class="dashboard-detail-empty">Aucune réservation sur cette date.</div>';
  }
  return groups.map(group => `<section class="dashboard-detail-section">
    <div class="dashboard-detail-section-head"><h3>${escapeHtml(group.name)}</h3><p>${group.count} réservation${group.count > 1 ? 's' : ''} contien${group.count > 1 ? 'nent' : 't'} cette activité</p></div>
    ${renderStaffDashboardReservationRows(sortStaffAlertRows(group.rows).slice(0, 12), 'Aucune réservation dans cette activité.')}
  </section>`).join('');
}

function copyStaffDashboardSummary() {
  const metrics = getStaffDashboardMetrics(todaysReservations());
  const text = [
    `Dashboard Pinlane - ${state.currentDate}`,
    `Réservations: ${metrics.activeReservations.length}`,
    `Joueurs: ${metrics.players}`,
    `CA prévu: ${formatMoney(metrics.revenue)}`,
    `Validé: ${formatMoney(metrics.collected)}`,
    `Occupation bowling: ${metrics.occupancy}%`,
    `À suivre: ${metrics.activeReservations.filter(reservation => reservation.status !== 'paid').length}`
  ].join('\n');
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(text).then(() => toast('Résumé copié.')).catch(() => toast(text));
  } else {
    toast(text);
  }
}

function openStaffDashboardAlert(kind = 'info') {
  openStaffDashboardDetail('alerts', kind);
}

function openStaffDashboardAlerts() {
  openStaffDashboardDetail('alerts');
}

// L ACCUEIL QUI SALUE (2026-09-25). Movsar, devant l interface d Accountable :
// « plus vivant, plus pro, avec que des choses vraiment reelles », puis, sur
// la mascotte de la premiere version : « pas gadget gamin, c est du B2B ». Le
// haut de la Vue d ensemble dit bonjour a la personne, puis donne en une
// pastille ce qui l attend : le compte de la carte « À faire », a la couleur
// de sa ligne la plus grave, jamais un texte d ambiance.

// LE PRENOM, SEULEMENT S IL EN EST UN. Un compte partage porte souvent le nom
// du centre (« Fun Galaxy Libramont ») ou d un role (« Proprietaire
// plateforme ») : « Bonjour Fun » serait pire que « Bonjour ». Le premier mot
// n est garde que s il ne vient ni du centre, ni du role, ni d un compte de
// service.
function getStaffGreetingFirstName() {
  const session = state.staffAuthSession || {};
  const member = session.member || {};
  if (member.emergency || session.emergency) return '';
  const name = String(member.name || '').trim();
  if (!name || /[\d@]/.test(name)) return '';
  const plain = value => String(value || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase();
  const words = value => plain(value).split(/[^a-z]+/).filter(word => word.length > 2);
  const first = name.split(/\s+/)[0];
  const centerName = typeof window.staffCenterDisplayName === 'function' ? window.staffCenterDisplayName() : '';
  const reserved = new Set([
    ...words(centerName), ...words(session.role && session.role.name),
    'plateforme', 'proprietaire', 'direction', 'admin', 'administrateur', 'compte', 'accueil',
    'equipe', 'centre', 'staff', 'comptoir', 'caisse', 'manager', 'reception', 'test', 'demo'
  ]);
  if (first.length < 2 || first.length > 24 || reserved.has(plain(first))) return '';
  return first;
}

function getStaffGreetingWord(now = new Date()) {
  const hour = now.getHours();
  return hour >= 18 || hour < 5 ? 'Bonsoir' : 'Bonjour';
}

// LA BOITE MAIL SUR L ACCUEIL : les compteurs de la page Emails (emailOverview,
// la lecture de son Apercu), jamais un chiffre recompose ici. Sans le droit
// de lire les mails, rien n est demande et rien ne s affiche. Relue au plus
// toutes les 30 s ; un echec efface l ancienne lecture plutot que de montrer
// un compte perime comme s il etait frais.
const dashInbox = { centre: '', loading: false, done: false, data: null, at: 0 };

function canSeeDashInbox() {
  return typeof canUseStaffPermission !== 'function' || canUseStaffPermission('emails.view');
}

function ensureDashInbox() {
  if (!canSeeDashInbox()) return;
  const centre = getCurrentStaffCenterId();
  if (dashInbox.centre !== centre) Object.assign(dashInbox, { centre, loading: false, done: false, data: null, at: 0 });
  if (dashInbox.loading || (dashInbox.done && Date.now() - dashInbox.at < 30000)) return;
  dashInbox.loading = true;
  apiRequest(`${API_ENDPOINTS.ops}?action=emailOverview&centerId=${encodeURIComponent(centre)}`)
    .then(payload => {
      if (dashInbox.centre === centre) dashInbox.data = payload && typeof payload === 'object' ? payload : null;
    })
    .catch(() => {
      if (dashInbox.centre === centre) dashInbox.data = null;
    })
    .finally(() => {
      if (dashInbox.centre !== centre) return;
      dashInbox.loading = false;
      dashInbox.done = true;
      dashInbox.at = Date.now();
      if (isStaffDashboardActive()) renderStaffDashboard();
    });
}

function isDashInboxKnown() {
  return !canSeeDashInbox() || Boolean(dashInbox.done && dashInbox.data && dashInbox.centre === getCurrentStaffCenterId());
}

function formatDashWaited(ms) {
  const hours = Math.floor(ms / 3600000);
  if (hours < 1) return 'moins d’une heure';
  if (hours < 24) return `${hours} h`;
  const days = Math.floor(hours / 24);
  return `${days} jour${days > 1 ? 's' : ''}`;
}

// Ce que la boite mail demande, en lignes « À faire ». Les libelles et les
// sections sont ceux de la page Emails : on retrouve la meme chose en
// arrivant. Un fil attendu depuis plus d un jour passe en Prioritaire.
function getDashInboxTodos() {
  if (!canSeeDashInbox() || !isDashInboxKnown()) return [];
  const data = dashInbox.data;
  const todos = [];
  const open = Math.max(0, Number(data.aRepondre) || 0);
  if (open) {
    const oldest = Date.parse(data.plusAncienneAttenteAt || '');
    const waited = Number.isFinite(oldest) ? Math.max(0, Date.now() - oldest) : null;
    todos.push({
      kind: 'inbox',
      priority: waited !== null && waited >= 86400000 ? 'critical' : 'important',
      title: `${open} mail${open > 1 ? 's' : ''} à répondre`,
      text: waited !== null ? `Le plus ancien attend depuis ${formatDashWaited(waited)}.` : 'Des clients attendent une réponse.',
      open: "openStaffMenuPage('emails', 'recus')",
      cta: 'Répondre'
    });
  }
  const questions = Math.max(0, Number(data.questions) || 0);
  if (questions) {
    todos.push({
      kind: 'agent',
      priority: 'important',
      title: `${questions} question${questions > 1 ? 's' : ''} de l’agent`,
      text: 'Informations qui lui manquent pour répondre seul aux clients.',
      open: "openStaffMenuPage('emails', 'agent')",
      cta: 'Répondre'
    });
  }
  const failed = Math.max(0, Number(data.echecs7j) || 0);
  if (failed) {
    todos.push({
      kind: 'bounce',
      priority: 'info',
      title: `${failed} envoi${failed > 1 ? 's' : ''} en échec`,
      text: 'Mails non distribués ces 7 derniers jours.',
      open: "openStaffMenuPage('emails', 'envoyes')",
      cta: 'Voir'
    });
  }
  return todos;
}

// LA VUE D ENSEMBLE (refonte du 2026-09-30). Trois questions, dans l ordre ou
// on se les pose en arrivant :
//   1. qu est-ce qui se passe maintenant ? « En ce moment », le jour meme :
//      les groupes de la page Terrain en quatre chiffres ;
//   2. comment va la journee ? quatre tuiles, comparees au meme jour de la
//      semaine d avant (un samedi contre un samedi, jamais contre un vendredi) ;
//   3. qu est-ce qui attend ? « À traiter » (demandes, mails, verifications),
//      puis la semaine (revenus) et les arrivees heure par heure.
// Ni anneau par activite ni classement des formules : ils ne decidaient rien
// pendant la journee (NORTHSTAR, chaque donnee paie sa place). Aucune liste de
// reservations (Movsar, 2026-08-14).
function renderStaffDashboard(dayReservations = todaysReservations()) {
  const root = document.getElementById('staffDashboardPage');
  if (!root) return;
  ensureDashInbox();
  // La file des demandes sur mesure n'était chargée QUE depuis la page Clients :
  // sans cet appel, l'alerte « demandes sur mesure » resterait invisible pour
  // quelqu'un qui n'ouvre jamais le bon filtre. Sans effet de bord de rendu
  // ici : loadStaffCustomRequests repasse par renderStaffGroupHost.
  if (typeof ensureStaffCustomRequests === 'function') ensureStaffCustomRequests();
  // La serie 14 jours vient du serveur (voir staffDaySeriesCache) : declenchee
  // ici, elle re-rend le dashboard a l'arrivee de la reponse.
  ensureStaffDaySeries();
  const metrics = getStaffDashboardMetrics(dayReservations);
  // Sans « Voir les montants », la tuile cache aussi la forme du chiffre :
  // un « +40 % » et une courbe disent ce que le « ··· » tait.
  const seesMoney = typeof canUseStaffPermission !== 'function' || canUseStaffPermission('payments.view');
  const reference = getDashReferenceLabel(metrics);
  // La legende des tuiles : la journee, et a quoi ses ecarts se comparent.
  // Une reference sans aucune reservation (centre ferme ce jour-la) ne
  // compare rien : la legende le dit, les tuiles n ont pas de pastille.
  // Une date a venir n a que les reservations prises a ce jour : la legende
  // le dit, et rien n est « encaissé » d avance (le centre encaisse sur place).
  const future = state.currentDate > todayStr();
  const referenceKnown = metrics.referenceReservations !== null;
  const referenceEmpty = referenceKnown && !(metrics.referenceReservations > 0);
  const dayCaption = future
    ? 'réservations prises à ce jour'
    : !referenceKnown
      ? ''
      : referenceEmpty
        ? `${reference} : aucune réservation`
        : `comparée au ${reference}`;
  const syncIndicator = getRemoteSyncIndicator();
  // CE QUI ATTEND, EN DEUX ENDROITS QUI NE SE RECOUVRENT PAS : le retard et
  // l argent des groupes finis dans « En ce moment » (band), le reste dans
  // « À traiter ». La pastille du haut compte les deux, et les nomme.
  const inboxKnown = isDashInboxKnown();
  const inboxTodos = getDashInboxTodos();
  const dayAlerts = getStaffDashboardAlertDefinitions(metrics);
  const urgent = dayAlerts.filter(alert => alert.band);
  const listed = [...inboxTodos, ...dayAlerts.filter(alert => !alert.band)];
  const pending = [...urgent, ...listed];
  const firstName = getStaffGreetingFirstName();
  const greeting = `${getStaffGreetingWord()}${firstName ? ` ${firstName}` : ''}`;
  const todoLine = pending.length
    ? [urgent.length ? `${urgent.length} urgence${urgent.length > 1 ? 's' : ''}` : '', listed.length ? `${listed.length} à traiter` : ''].filter(Boolean).join(' · ')
    : (inboxKnown ? 'Tout est à jour' : 'Aucune alerte sur la journée');
  // L ETAT SE LIT A LA COULEUR, PAS A UN DESSIN (Movsar, 2026-09-25 : « c est
  // du B2B avec des Sebastien 45 ans »). La pastille prend la gravite la plus
  // haute ; verte seulement quand tout est traite ET que la boite mail a ete
  // lue ; neutre quand on ne sait pas.
  const topRank = pending.length ? Math.min(...pending.map(todo => getStaffAlertPriorityMeta(todo).rank)) : null;
  const todoTone = topRank === null ? (inboxKnown ? 'ok' : 'unknown') : (['critical', 'important', 'info'][topRank] || 'info');
  // Entree de page : une fois par navigation, jamais au poll (DESIGN.md §5).
  const pages = window.PinlaneV2;
  const active = isStaffDashboardActive();
  const arriving = active && (pages ? pages.lastPage !== 'dashboard' : !root.firstElementChild);
  if (pages && active) pages.lastPage = 'dashboard';
  root.classList.toggle('dash-enter', arriving && !prefersReducedMotion());
  const focusAvant = document.activeElement;
  root.innerHTML = `
    <section class="dash-hero dash-hello">
      <div class="dash-hello-copy">
        <h1>${escapeHtml(greeting)}</h1>
        <p class="dash-hello-line">
          ${pending.length
            ? `<button type="button" class="dash-state tone-${todoTone}" data-todo-count="${pending.length}" onclick="focusDashTodo()"><span class="dash-state-dot" aria-hidden="true"></span>${escapeHtml(todoLine)}</button>`
            : `<span class="dash-state tone-${todoTone}" data-todo-count="0"><span class="dash-state-dot" aria-hidden="true"></span>${escapeHtml(todoLine)}</span>`}
          <span class="dash-hello-sync"><span class="dash-live-dot${syncIndicator.tone === 'live' ? '' : ` ${syncIndicator.tone}`}"></span><span>${escapeHtml(syncIndicator.label)}</span></span>
        </p>
      </div>
      <div class="dash-actions">
        ${staffDateNavHtml()}
        ${peutGeste('reserver') ? '<button type="button" class="dash-new-btn" onclick="openQuickBook()">+ Réservation</button>' : ''}
      </div>
    </section>

    ${metrics.liveNow ? renderStaffDashNow(metrics.liveNow) : ''}

    <article class="dash-card dash-todo-card plt-traiter">
      <div class="dash-card-head"><div class="dash-card-titles"><h2>À traiter</h2>${listed.length ? `<span class="dash-todo-count">${listed.length}</span>` : ''}</div><button type="button" onclick="openStaffDashboardAlerts()">Alertes du jour</button></div>
      <div class="dash-alerts">${renderStaffDashboardAlerts(metrics, inboxTodos, inboxKnown)}</div>
    </article>
    <div class="plt-slot-tete" data-plt-slot="tete"></div>
    <div class="plt-slot-panneau" data-plt-slot="panneau"></div>
    <div class="plt-slot-cartes" data-plt-slot="cartes"></div>
  `;
  // LES CHIFFRES (2026-11-08) : un module a part, dont les noeuds survivent a ce innerHTML.
  if (window.PinlanePilotage) {
    const slot = (nom) => root.querySelector(`[data-plt-slot="${nom}"]`);
    window.PinlanePilotage.afficher({
      metrics,
      dayReservations,
      seesMoney,
      legendeDuJour: dayCaption,
      focusAvant,
      slots: { tete: slot('tete'), panneau: slot('panneau'), cartes: slot('cartes') },
    });
  }
}

// La pastille du haut mene a ce qui attend : la premiere case urgente du
// bandeau, sinon le premier bouton de « À traiter ».
function focusDashTodo() {
  const root = document.getElementById('staffDashboardPage');
  if (!root) return;
  const urgentCell = root.querySelector('.dash-now-cell.tone-critical, .dash-now-cell.tone-important');
  const card = root.querySelector('.dash-todo-card');
  const target = urgentCell || (card && card.querySelector('.dash-alert-cta'));
  const scrollTo = urgentCell ? root.querySelector('.dash-now') : card;
  if (scrollTo) scrollTo.scrollIntoView({ behavior: prefersReducedMotion() ? 'auto' : 'smooth', block: 'start' });
  if (target) target.focus({ preventScroll: true });
}

function openStaffMenuPage(page, resource = '') {
  if (typeof recordStaffActivity === 'function') recordStaffActivity('page', page);
  const requestedPage = String(page || 'dashboard').trim();
  // Fusion Clients+Groupes : l'ancienne page « groups » vit dans Clients,
  // segment « À venir ». L'alias est résolu AVANT la normalisation, sinon la
  // comparaison de fin (cleanPage !== requestedPage) prend le remap pour une
  // page inconnue et affiche « Page indisponible » sur un lien parfaitement
  // valide - c'est exactement le chemin qu'emprunte l'alerte « demandes ».
  const aliasedPage = requestedPage === 'groups' ? 'clients' : (STAFF_PAGE_ALIASES[requestedPage] || requestedPage);
  const cleanPage = normalizeStaffMenuPage(aliasedPage);
  if (requestedPage === 'groups' && cleanPage === 'clients') {
    state.staffClientSegment = 'avenir';
    if (typeof ensureStaffCustomRequests === 'function') ensureStaffCustomRequests();
  }
  if (cleanPage !== aliasedPage) {
    if (typeof showPlanningMoveNotice === 'function') {
      showPlanningMoveNotice('Page indisponible', 'Cette section n existe pas encore dans le back-office. Ouverture du planning.', 'warning');
    } else {
      toast('Section indisponible.');
    }
  }
  if (!canUseStaffPage(cleanPage)) {
    toast('Accès non autorisé pour ce rôle.');
    return;
  }
  // Revenir sur une page remet le filtre d etat sur « Tout » : un filtre
  // pose plus tot ne doit jamais accueillir le staff en silence. Le plein
  // ecran de la liste se referme aussi : il n appartient qu au planning, et
  // le laisser vrai ailleurs collait une liste par-dessus la page ouverte.
  if (state.staffMenuPage !== cleanPage) {
    state.staffStatusFilter = 'all';
    state.staffTableExpanded = false;
  }
  state.staffMenuPage = cleanPage;
  // Page Emails : le second argument est une SECTION (#/staff/emails/recus),
  // jamais une ressource du planning. Sans cette branche, « recus » finissait
  // dans state.staffResourceView, que le planning relit ensuite.
  if (cleanPage === 'emails') {
    if (resource) state.staffEmailsSection = normalizeStaffEmailsSection(resource);
    setStaffRouteHash('emails', state.staffEmailsSection);
  } else {
    if (resource) state.staffResourceView = resource;
    setStaffRouteHash(state.staffMenuPage, resource || state.staffResourceView);
  }
  save();
  renderStaff();
  syncOpsSidebar();
}

function openStaffPlanningResource(resource = 'bowling') {
  if (!canUseStaffPage('planning')) {
    toast('Accès planning non autorisé.');
    return;
  }
  state.staffMenuPage = 'planning';
  state.staffStatusFilter = 'all';
  state.staffResourceView = ['all', 'bowling', 'laser'].includes(resource) ? resource : 'bowling';
  setStaffRouteHash('planning', state.staffResourceView);
  save();
  renderStaff();
  syncOpsSidebar();
}

function setStaffRouteHash(page = getStaffMenuPage(), resource = '') {
  if (typeof window === 'undefined') return;
  const cleanPage = String(page || 'dashboard').trim();
  const cleanResource = String(resource || '').trim();
  // La section Emails a sa propre adresse : un lien profond ouvre directement
  // la bonne section, et le bouton Retour du navigateur la retrouve.
  const emailsSection = cleanPage === 'emails'
    ? normalizeStaffEmailsSection(cleanResource || state.staffEmailsSection)
    : '';
  const route = cleanPage === 'planning' && ['all', 'bowling', 'laser'].includes(cleanResource)
    ? `#/staff/planning/${cleanResource}`
    : emailsSection
      ? `#/staff/emails/${emailsSection}`
      : `#/staff/${cleanPage}`;
  writeAppUrl(APP_ROUTE_PATH, route);
}

// ── URL <-> vue ────────────────────────────────────────────────────────────
// Avant, SEULE la partie staff ecrivait dans l'URL. Consequence visible : on
// lisait « mngfunglxy.com/#/staff/users » au-dessus du parcours de reservation
// CLIENT, et le parcours client n'avait aucune adresse a lui. Desormais chaque
// vue a son adresse :
//   client    -> /reserver          (page publique, deja dans le sitemap)
//   staff     -> /#/staff/<page>    (inchange : le hash n'est pas envoye au
//                                    serveur, donc aucun impact sur le Basic
//                                    Auth du middleware)
//   direction -> /#/admin/<onglet>
const CLIENT_ROUTE_PATH = '/reserver';

// UNE SEULE REGLE POUR L ADRESSE CLIENT. detectCustomerMode acceptait deja
// « /reserver » ET « /reserver/<centre> » ; applyInitialRouteFromHash, lui,
// comparait par EGALITE stricte. Ouvrir /reserver/libramont avec une session
// staff ouverte renvoyait donc sur la console, et le centre demande
// disparaissait de l URL (reecrite en /#/staff/...). Deux endroits, deux
// regles, pour la meme adresse : il n y en a plus qu une.
function isClientRoutePath(rawPath) {
  const path = String(rawPath == null ? '' : rawPath).toLowerCase().replace(/\/+$/, '') || '/';
  return path === CLIENT_ROUTE_PATH || path.startsWith(CLIENT_ROUTE_PATH + '/');
}
// LE CHEMIN CLIENT REELLEMENT OUVERT, retenu AU CHARGEMENT. Il est lu une
// seule fois, avant le premier `replaceState` : une fois l adresse reecrite,
// `location.pathname` ne dirait plus quel centre le visiteur a demande.
//
// Mesure en production (2026-09-18) : /reserver/gembloux devenait /reserver,
// et le rechargement servait Libramont, sans que rien ne le signale. Le tarif
// d un centre affiche sous le nom d un autre ne se voit sur aucun ecran.
const CLIENT_ROUTE_OPENED = (() => {
  try {
    const brut = String(window.location.pathname || '').toLowerCase().replace(/\/+$/, '');
    const m = brut.match(/^\/reserver\/([a-z][a-z0-9-]{1,40})$/);
    return m ? `${CLIENT_ROUTE_PATH}/${m[1]}` : CLIENT_ROUTE_PATH;
  } catch (error) {
    return CLIENT_ROUTE_PATH;
  }
})();

const APP_ROUTE_PATH = '/';

// LA DEMONSTRATION PUBLIQUE A SON CHEMIN, ET IL DOIT SURVIVRE (2026-08-08).
// `/demo` fait tourner cette meme application sur des donnees fabriquees
// (assets/demo-mode.js). Or les deux chemins canoniques ci-dessus etaient
// ecrits dans l'URL a CHAQUE changement de vue : des le premier rendu,
// `history.replaceState` remplacait `/demo` par `/`. Consequences en chaine,
// toutes constatees : l'adresse n'etait plus partageable, un rechargement
// servait la console REELLE (le faux reseau ne se posait plus), la session de
// demonstration etait rejetee par le vrai serveur, et le prospect tombait sur
// l'ecran de code d'acces. C'est pour ca que la vitrine ne liait pas la demo.
// La regle est donc : sur `/demo`, l'application ecrit `/demo` - le fragment
// continue de porter la page, la query string reste preservee. Sur tout autre
// chemin, comportement STRICTEMENT inchange.
const DEMO_ROUTE_PATH = '/demo';
function isDemoRoute() {
  try { return /^\/demo\/?$/i.test(window.location.pathname || ''); } catch (error) { return false; }
}

function getCurrentPathname() {
  try { return String(window.location.pathname || '/').replace(/\/+$/, '') || '/'; } catch (error) { return '/'; }
}

function writeAppUrl(pathname, hash = '', { push = false } = {}) {
  if (typeof window === 'undefined' || !window.history) return;
  if (isDemoRoute()) pathname = DEMO_ROUTE_PATH;
  // La query string est PRESERVEE : elle peut porter un parametre de campagne ou
  // de centre, et la perdre en changeant d'onglet casserait le suivi.
  let search = '';
  try { search = String(window.location.search || ''); } catch (error) { search = ''; }
  const target = `${pathname}${search}${hash || ''}`;
  const current = `${getCurrentPathname()}${search}${window.location.hash || ''}`;
  if (current === target) return;
  try {
    if (push) window.history.pushState(null, '', target);
    else window.history.replaceState(null, '', target);
  } catch (error) {
    // Un contexte sans History API (fichier local, bac a sable) ne doit jamais
    // empecher la bascule de vue.
  }
}

function syncViewUrl(view = state.view, { push = false } = {}) {
  if (view === 'client') {
    // Le centre reste dans l adresse : elle doit pouvoir se recharger, se
    // partager et se mettre en favori sans changer de centre.
    writeAppUrl(CLIENT_ROUTE_OPENED, '', { push });
    return;
  }
  if (view === 'admin') {
    const tab = String(state.adminTab || 'overview').trim() || 'overview';
    writeAppUrl(APP_ROUTE_PATH, `#/admin/${tab}`, { push });
    return;
  }
  const page = String(getStaffMenuPage() || 'dashboard').trim();
  const resource = page === 'planning' && ['all', 'bowling', 'laser'].includes(state.staffResourceView)
    ? `/${state.staffResourceView}`
    : page === 'emails'
      ? `/${normalizeStaffEmailsSection(state.staffEmailsSection)}`
      : '';
  writeAppUrl(APP_ROUTE_PATH, `#/staff/${page}${resource}`, { push });
}

function getStaffUtilityReservations() {
  return todaysReservations()
    .filter(reservation => reservation.status !== 'cancelled')
    .sort((left, right) => getReservationFirstResourceStart(left, 'all') - getReservationFirstResourceStart(right, 'all'));
}

// Sous-titre des pages staff. Il annoncait la PLOMBERIE : « Données API +
// locales · 12 réservations visibles · lecture locale ». Personne n'a besoin
// de savoir d'ou sortent les octets - et « lecture locale » laissait croire
// que le poste travaillait sur une copie perimee alors que le serveur fait
// autorite des qu'il a repondu.
// Regle : SILENCE quand tout va bien ; on ne parle que si la connexion au
// serveur est perdue, parce que la, ca change ce que le staff doit croire de
// ce qu'il voit.
function getStaffUtilitySyncLabel() {
  const indicator = getRemoteSyncIndicator();
  if (indicator.tone === 'live') return '';
  return indicator.label;
}

function renderStaffUtilityKpi(label, value, detail = '', tone = '') {
  return `<article class="utility-kpi ${escapeHtml(tone)}">
    <span>${escapeHtml(label)}</span>
    <strong>${escapeHtml(String(value))}</strong>
    <small>${escapeHtml(detail)}</small>
  </article>`;
}

// La synthese chiffree ne s affiche plus que sur Equipe & acces (voir
// overviewPages dans renderStaffUtilityPage). Sans phrase d accompagnement :
// les quatre chiffres se lisent seuls, et la phrase d avant (« restent
// contrôlés sans mélanger les permissions... ») ne disait rien.
function renderStaffUtilityOverview(model) {
  const kpis = Array.isArray(model.kpis) ? model.kpis.filter(Boolean) : [];
  if (!kpis.length) return '';
  const [primary, ...rest] = kpis;
  const secondary = rest.slice(0, 3);
  const statusLabel = model.page === 'users' ? 'Accès' : (model.eyebrow || 'Lecture');

  return `<section class="utility-overview utility-overview-${escapeHtml(model.page || 'default')}">
    <div class="utility-overview-main">
      <div class="utility-overview-kicker">${escapeHtml(statusLabel)}</div>
      <div class="utility-overview-value-row">
        <strong>${escapeHtml(String(primary[1] ?? 0))}</strong>
        <span>${escapeHtml(primary[0] || model.title || '')}</span>
      </div>
    </div>
    <div class="utility-overview-signals">
      ${secondary.map(item => `<div class="utility-overview-signal">
        <span>${escapeHtml(item[0] || '')}</span>
        <strong>${escapeHtml(String(item[1] ?? ''))}</strong>
        <small>${escapeHtml(item[2] || '')}</small>
      </div>`).join('')}
    </div>
  </section>`;
}

function renderStaffUtilityAction(label, action, variant = '') {
  if (!action) return '';
  return `<button type="button" class="utility-action ${escapeHtml(variant)}" onclick="${action}">${escapeHtml(label)}</button>`;
}

function getStaffUtilityStartLabel(reservation) {
  const start = getReservationFirstResourceStart(reservation, 'all');
  return start ? formatClockDisplay(start) : formatClockDisplay(timeToNum(reservation.startTime || '00:00'));
}

function renderStaffUtilityClientList(rows = [], emptyTitle = 'Aucun client', emptyDetail = 'Aucun profil réel ne correspond à cette catégorie.') {
  if (!rows.length) {
    return `<div class="utility-empty"><strong>${escapeHtml(emptyTitle)}</strong><span>${escapeHtml(emptyDetail)}</span></div>`;
  }
  return `<div class="utility-contact-ledger">
    ${rows.slice(0, 18).map(row => `<article class="utility-contact-row">
      <span class="utility-avatar">${escapeHtml(row.initials || 'CL')}</span>
      <div class="utility-main"><strong>${escapeHtml(row.name)}</strong><em>${escapeHtml(row.email || row.phone || 'Contact incomplet')}</em></div>
      <div class="utility-resource">${escapeHtml(row.tags.join(' · ') || 'Client')}</div>
      <div class="utility-contact-stats"><span>${Number(row.reservations || 0)} rés.</span><strong>${formatMoney(row.spent || 0)}</strong></div>
      <div class="utility-res-actions">
        ${renderStaffUtilityAction('Fiche', `openStaffMenuPage('clients'); selectStaffClient('${escapeJsString(row.id)}')`)}
        ${renderStaffUtilityAction('Réserver', `openStaffClientBooking('${escapeJsString(row.id)}')`, 'success')}
      </div>
    </article>`).join('')}
  </div>`;
}

// LE TERRAIN, UNE SEULE FILE EN TROIS TEMPS (2026-09-25). Arrivees, En cours
// et Evenements montraient les MEMES reservations sous trois angles : un
// groupe arrive figurait sur les trois pages, compte trois fois, et rien ne
// disait laquelle faisait foi. Une page, trois colonnes EXCLUSIVES tirees des
// vrais horaires et du statut : chaque dossier est a un seul endroit, et il
// passe d une colonne a l autre quand le comptoir clique Arrive puis Paye.
//   upcoming : pas commence et pas pointe arrive ;
//   onsite   : pointe arrive, ou sa fenetre couvre l heure qu il est ;
//   closing  : fenetre finie et pas paye ;
//   done     : fenetre finie et paye (compte dans le sous-titre, pas affiche).
// Une date passee n a plus rien a venir ni en salle ; une date future n a
// encore rien commence.
// REFAITE LE 2026-09-30 (Movsar : « pas facile a comprendre one shot », « pas
// toutes les infos importantes », « mais pas trop d info »). Le groupe dont
// l heure est passee sans arrivee pointee n est pas « sur place » : il est EN
// RETARD, en tete de « À venir », avec son numero. Les arrivees au-dela de
// l heure qui vient tiennent sur une ligne. « Sur place » dit ou en est le
// groupe dans son programme.

// LES ACTIVITES D UNE FORMULE A LEURS HEURES, dans l ordre du programme. Le
// minigolf, les arcades ou les boissons ne prennent ni piste ni arene : sans
// elles, une formule quittait « Sur place » a sa derniere piste alors que le
// groupe etait encore au bar. Un deplacement de formule recalcule ce
// programme cote serveur (api/staff-reservations.js, isFormulaPatch).
function getStaffFormulaTimedItems(reservation) {
  if (typeof reservationHasFormulaActivities !== 'function' || !reservationHasFormulaActivities(reservation)) return [];
  return getFormulaActivityProgressSummary(reservation).items
    .filter(item => item.startTime)
    .map(item => {
      const start = timeToNum(item.startTime);
      let end = item.endTime ? timeToNum(item.endTime) : start;
      // Une activite qui passe minuit (23:40-00:05) finit le lendemain.
      if (end < start) end += 24;
      return { ...item, start, end };
    })
    .sort((left, right) => left.start - right.start || left.end - right.end);
}

// LE TEMPS LIBRE QUI DEPASSE LE PLAN (2026-10-02, Movsar : « l heure de
// sortie affichee sous l heure d arrivee est fausse »). La fin s arretait au
// dernier bloc a heure : un groupe bowling 16:00-17:00 + minigolf 45 min +
// billard 2 h + arcades « sortait » a 17:00. C est la regle du moteur, pas une
// copie inventee (api/public-availability mesureDeVisite) : les activites
// libres (ni a heure, ni a la journee, ni offertes pendant une attente) se
// jouent d abord dans les trous entre les blocs, le reste apres le plan.
// D UN BLOC (2026-10-14, Movsar : « FIN estimé a 17h et le mini golf se joue
// quand du coup ? ») : une activite libre ne prend qu un trou qui la contient
// tout entiere, comme le moteur (lib/ops-engine.js, rangerLeLibre). Deux
// attentes de 35 min ne portent pas un minigolf de 45.
function getEtapeAvant(reservation, item) {
  if (!item || item.avant !== true) return null;
  const pas = reservation && reservation.opsPlan && Array.isArray(reservation.opsPlan.timeline) ? reservation.opsPlan.timeline : [];
  return pas.find(step => step && step.activityId === item.activityId && step.flexible === false && step.startTime && step.endTime) || null;
}
function getVisiteLibreApres(reservation, windows) {
  const items = reservation && reservation.program && Array.isArray(reservation.program.items) ? reservation.program.items : [];
  const posees = reservation && reservation.opsPlan && Array.isArray(reservation.opsPlan.timeline) ? reservation.opsPlan.timeline : [];
  const libres = items.filter(item => item && item.planned === false && !item.waitOffer && !ligneALaJournee(item)
    // « Venir plus tot » : ce que le plan pose avant la premiere activite n allonge pas la fin.
    && !(item.avant === true && posees.some(step => step && step.activityId === item.activityId && step.flexible === false && step.startTime)));
  const durees = libres.map(item => Math.max(0, Math.round(Number(item.minutes) || 0))).filter(duree => duree > 0);
  const minutes = durees.reduce((total, duree) => total + duree, 0);
  if (!minutes) return 0;
  // Les trous entre les PARTIES du groupe (trousDuGroupe du moteur) : les
  // vagues d une meme partie ne font qu un bloc.
  const parPartie = new Map();
  (windows || []).forEach(w => {
    const debut = Math.round(Number(w.start) * 60);
    const fin = Math.round(Number(w.end) * 60);
    if (!Number.isFinite(debut) || !Number.isFinite(fin) || fin <= debut) return;
    const laser = w.activityId === 'laser_game' || w.resourceType === 'laser_arena';
    const cle = `${laser ? 'laser_game' : (w.activityId || w.resourceType || '')}#${Number(w.countIndex) || 1}`;
    const deja = parPartie.get(cle);
    parPartie.set(cle, deja ? { debut: Math.min(deja.debut, debut), fin: Math.max(deja.fin, fin), laser } : { debut, fin, laser });
  });
  const intervalles = [...parPartie.values()].sort((a, b) => a.debut - b.debut);
  const trous = [];
  let finCourante = null;
  intervalles.forEach(i => {
    if (finCourante !== null && i.debut > finCourante) trous.push({ debut: finCourante, capacite: i.debut - finCourante });
    finCourante = finCourante === null ? i.fin : Math.max(finCourante, i.fin);
  });
  // MOINS LES PARTIES DE LASER JOUEES DANS LA FOULEE (2026-10-13, Movsar : « il
  // ne compte pas les activités qui sont dans la foulée »). Elles s enchainent
  // dans ces memes trous quand elles y tiennent : le libre n y prend que le
  // reste. Meme regle que le moteur (trousPourLeLibre) : ce que la fin du plan,
  // sans la marge, depasse le dernier bloc est la foulee jouee apres lui ; le
  // reste prend le debut du trou qui s ouvre a la fin de la derniere partie.
  const plan = reservation && reservation.opsPlan;
  const foulee = Math.max(0, Math.round(Number(plan && plan.laserPassPlan && plan.laserPassPlan.followOnMinutes) || 0));
  if (foulee && trous.length && finCourante !== null) {
    const marge = Math.max(0, Number(plan.bufferMinutes) || 0);
    const finPlan = typeof plan.endTime === 'string' && /^\d{1,2}:\d{2}/.test(plan.endTime) ? Math.round(timeToNum(plan.endTime) * 60) - marge : null;
    const dehors = finPlan !== null ? Math.min(foulee, Math.max(0, finPlan - finCourante)) : 0;
    let dedans = foulee - dehors;
    const finsLaser = intervalles.filter(i => i.laser).map(i => i.fin);
    const depuis = finsLaser.length ? Math.max(...finsLaser) : -Infinity;
    [...trous.filter(trou => trou.debut >= depuis), ...trous.filter(trou => trou.debut < depuis)].forEach(trou => {
      const prise = Math.min(dedans, trou.capacite);
      trou.capacite -= prise;
      dedans -= prise;
    });
  }
  // Les minutes que les trous portent, chaque activite tout entiere dans un
  // seul : le meilleur rangement du moteur (meilleurRangement), exact jusqu a
  // 8 activites, au-dela le meme glouton (chaque trou dans l ordre, les plus
  // longues d abord). La fin ne depend que de ce total.
  function couvertParLesTrous(capacites, longueurs) {
    const n = longueurs.length;
    if (!n || !capacites.length) return 0;
    if (n > 8) {
      const prises = longueurs.map(() => false);
      let total = 0;
      capacites.forEach(capacite => {
        let reste = capacite;
        longueurs.map((duree, rang) => ({ duree, rang })).filter(item => !prises[item.rang])
          .sort((a, b) => b.duree - a.duree || a.rang - b.rang)
          .forEach(item => { if (item.duree <= reste) { prises[item.rang] = true; reste -= item.duree; total += item.duree; } });
      });
      return total;
    }
    const sommes = new Array(1 << n).fill(0);
    for (let masque = 1; masque < (1 << n); masque += 1) {
      const bas = masque & -masque;
      sommes[masque] = sommes[masque ^ bas] + longueurs[Math.log2(bas)];
    }
    const memo = new Map();
    const chercher = (trou, restant) => {
      if (trou === capacites.length || !restant) return 0;
      const cle = trou * (1 << n) + restant;
      if (memo.has(cle)) return memo.get(cle);
      let meilleur = 0;
      for (let sous = restant; ; sous = (sous - 1) & restant) {
        if (sommes[sous] <= capacites[trou]) meilleur = Math.max(meilleur, sommes[sous] + chercher(trou + 1, restant & ~sous));
        if (!sous) break;
      }
      memo.set(cle, meilleur);
      return meilleur;
    };
    return chercher(0, (1 << n) - 1);
  }
  return Math.max(0, minutes - couvertParLesTrous(trous.map(trou => trou.capacite), durees)) / 60;
}

function getStaffTerrainSpan(reservation) {
  const windows = getStaffResourceWindows(reservation, 'all');
  // « Venir plus tot » : le groupe est la des son activite d avant, pas seulement a son bowling.
  const etapesDuPlan = reservation && reservation.opsPlan && Array.isArray(reservation.opsPlan.timeline) ? reservation.opsPlan.timeline : [];
  const avant = etapesDuPlan.filter(step => step && step.avant === true && step.startTime && step.endTime).map(step => ({ start: timeToNum(step.startTime), end: timeToNum(step.endTime) }));
  const items = [...getStaffFormulaTimedItems(reservation), ...getFormulaFreeWindows(reservation), ...avant];
  const starts = [...windows.map(window => Number(window.start)), ...items.map(item => item.start)];
  const ends = [...windows.map(window => Number(window.end)), ...items.map(item => item.end)];
  if (starts.length) {
    // La fin du PLAN porte aussi les parties de laser encore sans heure, jouees
    // a la suite (laserPassPlan.followOnMinutes) ; la marge du staff n est pas
    // du temps de visite.
    const plan = reservation && reservation.opsPlan;
    const marge = Math.max(0, Number(plan && plan.bufferMinutes) || 0) / 60;
    const finPlan = plan && typeof plan.endTime === 'string' && /^\d{1,2}:\d{2}/.test(plan.endTime) ? timeToNum(plan.endTime) - marge : 0;
    const finBlocs = Math.max(...ends, finPlan > Math.max(...ends) && (plan.laserPassPlan?.pendingPasses || []).length ? finPlan : 0);
    return { start: Math.min(...starts), end: finBlocs + getVisiteLibreApres(reservation, windows) };
  }
  const start = timeToNum(reservation.startTime || '00:00');
  // UNE VISITE SANS PISTE DURE LE TEMPS DE SES ACTIVITES (minigolf 45 min +
  // Fun Run 2 × 30 min = 1h45), jamais la demi-heure par defaut du dossier :
  // la carte de la caisse affichait sinon une fin fausse (2026-10-01). Une
  // entree a la journee ne compte pas dans cette duree.
  const programme = dureeProgrammeHeures(reservation);
  return { start, end: start + (programme || readDurationHours(reservation.duration) || 1) };
}

function getStaffTerrainPhase(reservation, span, context) {
  const status = reservation.status || 'pending';
  // « PAS VENU » SORT DU TRAVAIL (2026-10-08). L absence notee dans la fiche
  // (0056) n etait lue par aucun moment : le groupe restait « En retard » ou
  // « Non pointé » sur la liste, l accueil et le Terrain. Il n est plus
  // attendu, plus sur place, plus a cloturer.
  if (reservation.absentAt && status !== 'paid') return 'absent';
  if (context.when === 'future') return 'upcoming';
  if (context.when === 'past' || span.end <= context.now || groupeToutFait(reservation)) return status === 'paid' ? 'done' : 'closing';
  // PAYE = ARRIVE (2026-10-02, Movsar : « s ils ont paye c est qu ils sont
  // arrives aussi, le paiement est que sur place ») : un groupe paye n est
  // jamais « À venir ».
  if (status === 'arrived' || status === 'paid' || span.start <= context.now) return 'onsite';
  return 'upcoming';
}

function getStaffTerrainBoard(reservations = getStaffUtilityReservations(), jour = state.currentDate) {
  const today = todayStr();
  const when = jour < today ? 'past' : jour > today ? 'future' : 'today';
  const context = { when, now: currentTimeDecimal() };
  const board = { when, now: context.now, total: reservations.length, upcoming: [], onsite: [], closing: [], done: [], absent: [] };
  reservations.forEach(reservation => {
    const span = getStaffTerrainSpan(reservation);
    board[getStaffTerrainPhase(reservation, span, context)].push({ reservation, ...span });
  });
  board.upcoming.sort((left, right) => left.start - right.start);
  // Sur place et a cloturer : celui qui finit (ou a fini) le premier d abord,
  // c est lui qui se presente le premier a la caisse.
  board.onsite.sort((left, right) => left.end - right.end);
  board.closing.sort((left, right) => left.end - right.end);
  return board;
}

function formatStaffTerrainDelay(hours) {
  const minutes = Math.max(1, Math.round(Math.abs(hours) * 60));
  if (minutes < 60) return `${minutes} min`;
  const whole = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest ? `${whole} h ${String(rest).padStart(2, '0')}` : `${whole} h`;
}

// Le temps dit par la carte est RELATIF A MAINTENANT, donc seulement le jour
// meme : un « dans 25 min » sur une autre date serait faux. Le tic d une
// minute (voir le setInterval du planning) repeint la page pour qu il reste
// juste. Le groupe en retard n a pas de temps dans son pied : sa pastille dit
// deja depuis quand il est attendu, son pied porte son numero.
function getStaffTerrainTiming(item, phase, board) {
  if (board.when !== 'today') return '';
  // Dans la marge de retard (heure passee de moins que le seuil), le groupe
  // est attendu maintenant : « dans 2 min » serait faux.
  if (phase === 'upcoming') return item.start <= board.now ? 'attendu maintenant' : `dans ${formatStaffTerrainDelay(item.start - board.now)}`;
  if (phase === 'onsite') {
    return item.start > board.now
      ? `commence dans ${formatStaffTerrainDelay(item.start - board.now)}`
      : `fin dans ${formatStaffTerrainDelay(item.end - board.now)}`;
  }
  if (phase === 'closing') return board.now >= item.end ? `fini depuis ${formatStaffTerrainDelay(board.now - item.end)}` : 'tout est fait';
  return '';
}

// UNE PASTILLE SEULEMENT QUAND ELLE DIT QUELQUE CHOSE (2026-09-30). La colonne
// dit deja le moment : « Confirmé » sur treize cartes d « À venir » et
// « Arrivé » sur chaque carte « Sur place » ne faisaient que la repeter. Reste
// ce que la colonne ne dit pas : le retard, l arrivee jamais pointee d un
// groupe qui a fini (« Non pointé » : peut-etre pas venu), la reservation en
// ligne a valider (meme definition que la liste et la fiche), et le groupe
// qui a deja paye (rien a encaisser en fin de partie).
function getStaffTerrainStatus(reservation, phase, item = null, board = null) {
  const upcoming = isUpcomingReservationStatus(reservation.status || 'pending');
  if (phase === 'late') return { label: item && board ? `En retard · ${formatStaffTerrainDelay(board.now - item.start)}` : 'En retard', tone: 'late' };
  if (phase === 'closing' && upcoming && !groupeAJoue(reservation)) return { label: 'Non pointé', tone: 'unmarked' };
  if (isReservationAwaitingReview(reservation)) return { label: 'À vérifier', tone: 'review' };
  if (reservation.status === 'paid') return { label: 'Payé', tone: 'paid' };
  return null;
}

function renderStaffTerrainBadge(badge) {
  return badge ? `<span class="terrain-status tone-${escapeHtml(badge.tone)}">${escapeHtml(badge.label)}</span>` : '';
}

function getStaffTerrainResources(reservation) {
  return getStaffResourceWindows(reservation, 'all').map(window => {
    const hours = `${formatClockDisplay(window.start)}-${formatClockDisplay(window.end)}`;
    if (window.resourceType === 'laser_arena') return `Laser Game · ${hours}`;
    const lanes = window.lanes || reservation.lanes || [];
    const laneLabel = lanes.length > 1 ? `Pistes ${lanes.join(', ')}` : lanes.length ? `Piste ${lanes[0]}` : 'Piste à attribuer';
    return `${laneLabel} · ${hours}`;
  });
}

// Les pistes d une ligne, sans les heures : « Pistes 3, 4 ». Une piste pas
// encore attribuee se dit, c est justement ce qu il faut preparer.
function getStaffTerrainLanesShort(reservation) {
  const bowling = getStaffResourceWindows(reservation, 'all').filter(window => window.resourceType !== 'laser_arena');
  if (!bowling.length) return '';
  const lanes = [...new Set(bowling.flatMap(window => window.lanes || reservation.lanes || []))].sort((left, right) => left - right);
  if (!lanes.length) return 'Piste à attribuer';
  return lanes.length > 1 ? `Pistes ${lanes.join(', ')}` : `Piste ${lanes[0]}`;
}

function formatStaffTerrainCount(count, word) {
  return `${count} ${word}${count > 1 ? 's' : ''}`;
}

const STAFF_TERRAIN_NOTE_ICON = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3v5h5"/><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M9 13h6M9 17h4"/></svg>';
const STAFF_TERRAIN_PHONE_ICON = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.9.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/></svg>';

// LE TERRAIN DIT LE DOSSIER, PAS SEULEMENT LE MOT DU CLIENT (2026-11-03). Sous le mot du
// client (l allergie devant, en rouge), la derniere note de l equipe avec son auteur, le
// sur mesure avec ses heures et le prix revu avec sa raison : les rubriques de la ligne du
// Complet (pgEssentiel), une ligne chacune, aucune quand elle est vide.
function renderStaffTerrainNote(reservation) {
  const e = essentielDuDossier(reservation);
  const mot = getReservationNoteText(reservation);
  const allergie = (oui) => (oui ? '<b class="terrain-allergie">Allergie</b> ' : '');
  const lignes = [];
  if (e ? mot : hasReservationNote(reservation)) lignes.push(`<p class="res-special-request">${STAFF_TERRAIN_NOTE_ICON}${allergie(e && e.allergies.client)}${escapeHtml(mot)}</p>`);
  if (!e) return lignes.join('');
  const rubrique = (cle, nom, html) => `<p class="terrain-rub terrain-rub--${cle}"><span class="terrain-rub__mot">${nom}</span><span class="terrain-rub__t">${html}</span></p>`;
  if (e.derniere) lignes.push(rubrique('equipe', 'Équipe', `${allergie(e.derniere.allergie)}${escapeHtml(e.derniere.t)}${e.derniere.par ? ` <span class="terrain-rub__par">${escapeHtml(e.derniere.par)}</span>` : ''}`));
  if (e.mesure || e.adaptee) lignes.push(rubrique('mesure', 'Sur mesure', escapeHtml([e.adaptee ? 'formule adaptée' : '', e.mesure].filter(Boolean).join(', '))));
  if (e.prix) lignes.push(rubrique('prix', 'Prix', escapeHtml(e.prix)));
  return lignes.join('');
}

// OU EN EST LE GROUPE, d apres son programme : l activite prevue maintenant et
// la suivante. Seulement pour un programme a plusieurs etapes (une formule, un
// bowling suivi d un laser) : pour une seule activite, « fin dans 20 min » dit
// deja tout. Les memes heures que la page Formules et que la fiche.
function getStaffTerrainSteps(reservation) {
  const items = getStaffFormulaTimedItems(reservation);
  const steps = items.length
    ? items.map(item => ({ label: `${item.label} · ${getReservationActivityPlayers(reservation, item.activityId)} joueurs`, start: item.start, end: item.end }))
    : getStaffResourceWindows(reservation, 'all').map(window => ({
      label: `${window.resourceType === 'laser_arena' ? 'Laser Game' : 'Bowling'} · ${Number(window.joueursReels ?? window.players) || getReservationActivityPlayers(reservation, window.resourceType === 'laser_arena' ? 'laser_game' : 'bowling')} joueurs${bowlingCapacityMessage(window.bowlingCapacity) ? ' · ' + bowlingCapacityMessage(window.bowlingCapacity) : ''}`,
      start: Number(window.start),
      end: Number(window.end)
    }));
  const seen = new Set();
  return steps
    .filter(step => {
      const key = `${step.label}|${step.start}|${step.end}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((left, right) => left.start - right.start);
}

// Seulement sur place, donc seulement le jour meme : une date passee ou future
// n a personne en salle.
function renderStaffTerrainProgram(item, board) {
  const steps = getStaffTerrainSteps(item.reservation);
  if (steps.length < 2) return '';
  // Deux activites peuvent se chevaucher (la table d anniversaire et le
  // minigolf) : la plus recemment commencee est celle ou se trouve le groupe.
  const current = steps.filter(step => step.start <= board.now && step.end > board.now)
    .sort((left, right) => right.start - left.start)[0] || null;
  const next = steps.find(step => step.start > board.now) || null;
  if (!current && !next) return '';
  const line = (caption, step, when, extra = '') => `<div class="terrain-program-step${extra}">
      <small>${escapeHtml(caption)}</small>
      <strong>${escapeHtml(step.label)}</strong>
      <span>${escapeHtml(when)}</span>
    </div>`;
  return `<div class="terrain-program">
    ${current ? line('Maintenant', current, `jusqu’à ${formatClockDisplay(current.end)}`, ' is-now') : ''}
    ${next ? line(current ? 'Ensuite' : 'Prochaine', next, `à ${formatClockDisplay(next.start)}`) : ''}
  </div>`;
}

function renderStaffTerrainCard(item, phase, board) {
  const reservation = item.reservation;
  const id = staffClientJs(reservation.id);
  const status = reservation.status || 'pending';
  const badge = getStaffTerrainStatus(reservation, phase, item, board);
  const timing = getStaffTerrainTiming(item, phase, board);
  const occasion = getReservationOccasion(reservation);
  const pax = Number(reservation.pax || 0);
  const resources = getStaffTerrainResources(reservation);
  // Un prix decide a la main se voit AVANT l encaissement, pas au ticket :
  // la pastille remplace le montant nu quand il y a un ecart.
  const price = !canUseStaffPermission('payments.view') ? ''
    : renderReservationPriceMark(reservation, { forme: 'complet' })
      || `<span class="terrain-price">${escapeHtml(formatMoneyCentimes(Number(reservation.price || 0)))}</span>`;
  // Le groupe en retard se rappelle : son numero est le geste utile, a la
  // place du temps relatif que sa pastille dit deja.
  const phone = String(reservation.phone || '').trim();
  const call = phase === 'late' && phone
    ? `<a class="terrain-call" href="tel:${escapeHtml(phone.replace(/[^0-9+]/g, ''))}" title="Appeler ${escapeHtml(reservation.name || 'le client')}">${STAFF_TERRAIN_PHONE_ICON}<span>${escapeHtml(phone)}</span></a>`
    : '';
  const actions = [renderStaffUtilityAction('Détail', `openStaffReservationDetail(${id})`)];
  // Arrivé : jamais sur un dossier deja paye, le statut est un seul champ et
  // pointer l arrivee effacerait le paiement. Une carte a venir n existe que le
  // jour meme : une date future n a que des lignes, sans geste. Chaque geste
  // suit le role (2026-11-07) : la page s ouvre aussi a qui ne fait que lire.
  if ((phase === 'upcoming' || phase === 'late') && status !== 'paid' && peutGeste('etat')) {
    actions.push(renderStaffUtilityAction('Arrivé', `setReservationStatusDirect(${id}, 'arrived', event)`, 'primary'));
  }
  if ((phase === 'onsite' || phase === 'closing') && status !== 'paid' && peutGeste('encaisser')) {
    GROUPE_MOYENS.forEach(m => actions.push(renderStaffUtilityAction(`Payé · ${m.mot}`, `encaisserReservation(${id}, '${m.valeur}', event)`, 'primary')));
  }
  const foot = call || (timing ? `<span class="terrain-when">${escapeHtml(timing)}</span>` : '');
  return `<article class="terrain-card is-${escapeHtml(phase)}" data-terrain-id="${escapeHtml(String(reservation.id))}">
    <div class="terrain-card-top">
      <strong class="terrain-card-time">${escapeHtml(formatClockDisplay(item.start))}</strong>
      <div class="terrain-card-name">
        <strong>${escapeHtml(reservation.name || 'Client')}</strong>
        ${occasion ? `<span class="res-occasion-tag res-occasion-${escapeHtml(occasion)}">${escapeHtml(getReservationOccasionLabel(reservation))}</span>` : ''}
      </div>
      ${renderStaffTerrainBadge(badge)}
    </div>
    <div class="terrain-card-facts">
      <span>${escapeHtml(getReservationLabel(reservation))}</span>
      <span>${escapeHtml(formatStaffTerrainCount(pax, 'joueur'))}</span>
      ${price}
      ${renderActivityProgressPill(reservation)}
    </div>
    ${resources.length ? `<div class="terrain-card-resources">${resources.map(line => `<span>${escapeHtml(line)}</span>`).join('')}</div>` : ''}
    ${phase === 'onsite' ? renderStaffTerrainProgram(item, board) : ''}
    ${renderStaffTerrainNote(reservation)}
    <div class="terrain-card-foot">
      ${foot}
      <div class="terrain-card-actions">${actions.join('')}</div>
    </div>
  </article>`;
}

// UNE ARRIVEE LOINTAINE TIENT SUR UNE LIGNE. Treize cartes de meme poids
// rendaient la file illisible : le groupe de 21 h prenait autant de place que
// celui qui arrive dans dix minutes. Au-dela de l heure qui vient, la ligne
// garde ce qui prepare l arrivee : l heure, le nom, l activite, les joueurs,
// les pistes, la consigne, un prix decide a la main, la validation en
// attente, le deja paye. Le montant et les gestes attendent la carte, qui
// revient quand le groupe entre dans l heure. Toute la ligne ouvre la fiche.
function renderStaffTerrainRow(item) {
  const reservation = item.reservation;
  const facts = [
    getReservationLabel(reservation),
    formatStaffTerrainCount(Number(reservation.pax || 0), 'joueur'),
    getStaffTerrainLanesShort(reservation)
  ].filter(Boolean).join(' · ');
  const marks = `${renderReservationPriceMark(reservation, { forme: 'complet' })}${renderStaffTerrainBadge(getStaffTerrainStatus(reservation, 'upcoming'))}`;
  return `<article class="terrain-row" data-terrain-id="${escapeHtml(String(reservation.id))}">
    <strong class="terrain-row-time">${escapeHtml(formatClockDisplay(item.start))}</strong>
    <button type="button" class="terrain-row-main" onclick="openStaffReservationDetail(${staffClientJs(reservation.id)})" title="Ouvrir la réservation">
      <span class="terrain-row-name">${escapeHtml(reservation.name || 'Client')}</span>
      <span class="terrain-row-facts">${escapeHtml(facts)}</span>
    </button>
    ${marks ? `<div class="terrain-row-marks">${marks}</div>` : ''}
    ${renderStaffTerrainNote(reservation)}
  </article>`;
}

function renderStaffTerrainBoard(board) {
  if (!board.total) {
    return `<div class="utility-empty">
      <strong>Aucune réservation sur cette date.</strong>
      <span>Les réservations apparaissent ici dès qu’elles sont prises, en ligne ou au comptoir.</span>
    </div>`;
  }
  const past = board.when === 'past';
  const future = board.when === 'future';
  const today = board.when === 'today';
  // En retard : l heure est passee, personne n a pointe l arrivee. Meme
  // partage que la bande « En ce moment » de la Vue d ensemble.
  const onsite = splitStaffTerrainOnsite(board);
  const horizon = board.now + 1;
  const soon = today ? [...onsite.due, ...board.upcoming.filter(item => item.start <= horizon)] : [];
  const later = today ? board.upcoming.filter(item => item.start > horizon) : board.upcoming;
  const players = items => items.reduce((sum, item) => sum + Number(item.reservation.pax || 0), 0);
  const expected = [...onsite.late, ...onsite.due, ...board.upcoming];
  // « non encaissés » et pas « à encaisser » : un groupe jamais pointe n est
  // peut-etre pas venu. Le montant dit ce qui n est pas paye, rien de plus.
  const due = board.closing.reduce((sum, item) => sum + Number(item.reservation.price || 0), 0);
  const cards = (items, phase) => items.map(item => renderStaffTerrainCard(item, phase, board)).join('');
  const column = (phase, title, count, detail, body, emptyText) => `<section class="terrain-column is-${phase}${count ? ' has-items' : ''}" aria-labelledby="terrain-${phase}-title">
      <div class="terrain-column-head">
        <h2 id="terrain-${phase}-title">${escapeHtml(title)}</h2>
        <span class="terrain-count">${count}</span>
        ${detail ? `<small>${escapeHtml(detail)}</small>` : ''}
      </div>
      ${count ? body : `<p class="terrain-empty">${escapeHtml(emptyText)}</p>`}
    </section>`;
  const upcomingBody = [
    onsite.late.length || soon.length ? `<div class="terrain-list">${cards(onsite.late, 'late')}${cards(soon, 'upcoming')}</div>` : '',
    later.length ? `${today ? `<h3 class="terrain-subhead">Après ${escapeHtml(formatClockDisplay(horizon))}</h3>` : ''}<div class="terrain-rows">${later.map(renderStaffTerrainRow).join('')}</div>` : ''
  ].join('');
  return `<div class="terrain-board">
    ${column('upcoming', 'À venir', expected.length, expected.length ? formatStaffTerrainCount(players(expected), 'joueur') : '', upcomingBody, past ? 'Journée passée.' : 'Plus personne n’est attendu.')}
    ${column('onsite', 'Sur place', onsite.present.length, onsite.present.length ? formatStaffTerrainCount(players(onsite.present), 'joueur') : '', `<div class="terrain-list">${cards(onsite.present, 'onsite')}</div>`, past ? 'Plus personne sur place.' : future ? 'La journée n’a pas commencé.' : 'Personne sur place pour l’instant.')}
    ${column('closing', 'À clôturer', board.closing.length, board.closing.length ? `${formatMoney(due)} non encaissés` : '', `<div class="terrain-list">${cards(board.closing, 'closing')}</div>`, future ? 'Rien à clôturer avant la fin des parties.' : 'Tout est encaissé.')}
  </div>`;
}

// « Aujourd'hui RÉEL » : la page Groupes est ancrée à la date réelle, jamais à la
// date affichée (state.currentDate). Naviguer dans le calendrier ne change PAS
// l'à-venir des groupes (distinction nette avec Terrain, qui est le jour affiché).
function staffGroupToday() {
  return todayStr();
}

// Libellés d'occasion DÉCLARÉE (source de vérité de la catégorisation staff).
const STAFF_OCCASION_LABELS = {
  anniversaire: 'Anniversaire',
  entreprise: 'Entreprise / team building',
  teambuilding: 'Team building',
  prive: 'Groupe privé',
  groupe: 'Sortie groupe',
  ecole: 'École / jeunesse',
  evg: 'EVG / EVJF',
  // Anciennes valeurs conservées pour l'affichage des réservations historiques.
  amis: 'Entre amis',
  famille: 'Sortie famille',
  autre: 'Autre',
};

function getReservationOccasion(reservation = {}) {
  const raw = String(reservation.occasion || '').toLowerCase();
  return STAFF_OCCASION_LABELS[raw] ? raw : '';
}

function getReservationOccasionLabel(reservation = {}) {
  const occ = getReservationOccasion(reservation);
  return occ ? STAFF_OCCASION_LABELS[occ] : '';
}

// Classification client/groupe SERVIE PAR LE CENTRE (staff-state) : seuils
// groupe + formules anniversaire éditables côté Établissement. Défauts alignés
// sur le serveur (lib/center-config.js DEFAULT_CLASSIFICATION) tant que le poll
// n'a rien renvoyé.
const DEFAULT_STAFF_CLASSIFICATION = {
  groupMinPax: 10,
  groupMinCumulative: 18,
  countFormulaAsGroup: true,
  birthdayFromFormula: true,
  birthdayFormulaIds: ['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7', 'f8'],
  // 0 = seuil automatique (top 20 % des depensiers). Reglable depuis
  // Etablissement > Clients & groupes.
  keyClientMinSpend: 0,
};

function getStaffClassification() {
  const c = state.staffClassification;
  if (!c || typeof c !== 'object') return DEFAULT_STAFF_CLASSIFICATION;
  return {
    groupMinPax: Number(c.groupMinPax) || DEFAULT_STAFF_CLASSIFICATION.groupMinPax,
    groupMinCumulative: Number(c.groupMinCumulative) || DEFAULT_STAFF_CLASSIFICATION.groupMinCumulative,
    countFormulaAsGroup: c.countFormulaAsGroup !== false,
    birthdayFromFormula: c.birthdayFromFormula !== false,
    birthdayFormulaIds: Array.isArray(c.birthdayFormulaIds) ? c.birthdayFormulaIds : DEFAULT_STAFF_CLASSIFICATION.birthdayFormulaIds,
    keyClientMinSpend: Math.max(0, Number(c.keyClientMinSpend) || 0),
  };
}

// Une réservation compte-t-elle comme « anniversaire » via sa formule ?
function isStaffBirthdayFormulaReservation(reservation, classification = getStaffClassification()) {
  if (!classification.birthdayFromFormula) return false;
  const formulaId = reservation && (reservation.formuleId || reservation.formulaId);
  return Boolean(formulaId) && classification.birthdayFormulaIds.includes(formulaId);
}

// ════════════════════════════════════════════════════════════════════════════
//  GROUPES & ANNIVERSAIRES : RADAR DE PRÉPARATION (futur proche, ancré aujourd'hui
//  réel). Unité = LE DOSSIER (événement daté), pas le client. 3 horizons : CRM=passé,
//  Terrain=présent, ici=FUTUR PROCHE « qu'est-ce qui me tombe dessus, est-ce prêt ? ».
// ════════════════════════════════════════════════════════════════════════════

// Le workspace groupes vit dans la page Clients (segment « À venir ») depuis la
// fusion : ses actions re-rendent la page hôte, quelle qu'elle soit.
function renderStaffGroupHost() {
  if (getStaffMenuPage() === 'clients') { renderStaffClientsPage(); return; }
  // Le dashboard affiche désormais l'alerte « demandes sur mesure » : il doit
  // être re-peint quand la file arrive, sinon l'alerte n'apparaît qu'au
  // prochain rendu fortuit. Pas de boucle : ensureStaffCustomRequests sort
  // immédiatement sur `loading` ou sur le TTL.
  if (state.view === 'staff' && getStaffMenuPage() === 'dashboard') { renderStaffDashboard(); return; }
  if (isStaffUtilityActive()) renderStaffUtilityPage();
}

// « À venir » = TOUTES les réservations futures du centre actif, pas seulement
// celles des profils classés « groupe » ou « anniversaire ». Ce filtre était le
// dernier reste de la page « Groupes & anniversaires » supprimée le 2026-07-13 :
// il faisait disparaître de la vue une venue de 4 personnes un mardi soir, qui
// est pourtant une venue à préparer comme les autres. La question à laquelle
// cette vue répond est « qui vient, quand, combien », pas « quels groupes ».
function buildStaffUpcomingVisits() {
  const today = staffGroupToday();
  const rowsByKey = new Map();
  getStaffClientRows().forEach(row => { if (row && row.key) rowsByKey.set(row.key, row); });
  return getStaffClientSourceReservations()
    .filter(reservation => reservation
      && reservation.name
      && reservation.status !== 'cancelled'
      && String(reservation.date || '') >= today)
    .map(reservation => {
      const row = rowsByKey.get(getStaffClientReservationKey(reservation)) || null;
      return {
        id: `r-${reservation.id}`,
        reservation,
        row,
        dateISO: String(reservation.date || ''),
        startTime: String(reservation.startTime || ''),
        pax: Number(reservation.pax || 0),
        name: reservation.name || (row && row.name) || 'Client',
        email: reservation.email || (row && row.email) || '',
        phone: reservation.phone || (row && row.phone) || '',
        initials: (row && row.initials) || getStaffClientInitials(reservation.name || ''),
        clientId: (row && row.id) || '',
      };
    })
    .sort((left, right) => `${left.dateISO} ${left.startTime || '99:99'}`
      .localeCompare(`${right.dateISO} ${right.startTime || '99:99'}`));
}

// CE QUI MANQUE VRAIMENT avant la venue : deux faits, lus dans la donnée, le
// plus urgent gagne (même règle que le badge unique de la liste « Tous »).
// Renvoie null quand rien ne manque : une colonne vide est un signal, une
// rangée de six pastilles à moitié allumées n'en est pas un.
//
// LES QUATRE ITEMS RETIRÉS ET POURQUOI (audit du 2026-08-13) :
// - « Formule » : disait seulement que la réservation n'était PAS une formule
//   alors que le client en avait déjà pris une. Aucune action derrière.
// - « Joueurs » : une réservation porte toujours un nombre de joueurs, l'item
//   était coché sur la totalité des lignes.
// - « Paiement » (clé historique « acompte ») : Pinlane n'encaisse pas et le
//   centre encaisse SUR PLACE. « Pas encore payé » est l'état NORMAL avant une
//   venue, pas un manque : même classe d'erreur que l'acompte de la vitrine.
// - « Activités » : c'est la checklist du JOUR J, elle se coche pendant la
//   visite depuis la réservation, pas trois semaines avant.
// La coche manuelle qui les accompagnait n'était écrite que dans le
// localStorage du navigateur (state.staffGroupPrep → save()) : un « prêt »
// coché au comptoir restait invisible du gérant sur un autre poste.
function getStaffVisitGap(visit) {
  const reservation = (visit && visit.reservation) || {};
  const isFormula = reservation.type === 'formule' || !!reservation.formuleId;
  const needsLanes = reservation.type === 'bowling' || isFormula;
  const hasResource = (Array.isArray(reservation.lanes) && reservation.lanes.length)
    || reservation.type === 'laser'
    || (reservation.opsPlan && Array.isArray(reservation.opsPlan.resourceBlocks) && reservation.opsPlan.resourceBlocks.length);
  if (needsLanes && !hasResource) return { key: 'ressource', label: 'Piste à placer' };
  if (!visit.email || !visit.phone) return { key: 'contact', label: 'Contact incomplet' };
  return null;
}

// Compte à rebours ancré aujourd'hui réel.
function staffGroupCountdown(dateISO) {
  if (!dateISO) return '';
  const days = staffClientDaysBetween(dateISO, staffGroupToday());
  if (days <= 0) return "Aujourd'hui";
  if (days === 1) return 'Demain';
  return `J-${days}`;
}

function renderStaffUtilityContactLedger(rows = []) {
  if (!rows.length) {
    return `<div class="utility-empty"><strong>Aucun contact</strong><span>Les contacts sont construits depuis les réservations réelles.</span></div>`;
  }
  return `<div class="utility-contact-table">
    <div class="utility-contact-table-head"><span>Contact</span><span>Dernière visite</span><span>Statut</span><span>Valeur</span><span>Actions</span></div>
    ${rows.slice(0, 24).map(row => `<article class="utility-contact-line">
      <div class="utility-contact-id"><span class="utility-avatar">${escapeHtml(row.initials || 'CL')}</span><div><strong>${escapeHtml(row.name)}</strong><small>${escapeHtml(row.email || row.phone || 'Coordonnées manquantes')}</small></div></div>
      <span>${escapeHtml(row.lastDate || 'Jamais')}</span>
      <span class="utility-contact-status ${escapeHtml(row.statusClass || '')}">${escapeHtml(row.status || 'Client')}</span>
      <span>${formatMoney(row.spent || 0)}<small>${Number(row.reservations || 0)} rés.</small></span>
      <span class="utility-res-actions">
        ${renderStaffUtilityAction('Fiche', `openStaffMenuPage('clients'); selectStaffClient('${escapeJsString(row.id)}')`)}
        ${renderStaffUtilityAction('Réserver', `openStaffClientBooking('${escapeJsString(row.id)}')`, 'success')}
      </span>
    </article>`).join('')}
  </div>`;
}

// LA PAGE FORMULES DANS L ORDRE DE LA JOURNEE (2026-09-30). Les cartes etaient
// rangees par famille (« Formules anniversaires » pour presque toutes) : la
// famille ne dit rien au comptoir, l heure si. Trois temps, comme le Terrain et
// sur les memes heures (getStaffTerrainSpan) : en cours, a venir, terminees.
// Une formule terminee n a plus rien a cocher en direct : elle tient sur sa
// tete de carte, son compte dit si tout a ete coche, sa liste reste dans la
// fiche (bouton Ouvrir).
function getStaffFormulaPhase(reservation, context) {
  if (context.when === 'past') return 'done';
  if (context.when === 'future') return 'upcoming';
  const span = getStaffTerrainSpan(reservation);
  if (span.end <= context.now) return 'done';
  return span.start <= context.now ? 'live' : 'upcoming';
}

function renderFormuleTrackingCard(reservation, phase = 'upcoming') {
  const summary = getFormulaActivityProgressSummary(reservation);
  const span = getStaffTerrainSpan(reservation);
  const pax = Number(reservation.pax || 0);
  const count = summary.total
    ? `<span class="activity-check-count${summary.allDone ? ' done' : ''}">${summary.done}/${summary.total}${summary.allDone ? ' ✓' : ''}</span>`
    : '';
  const head = `<div class="formules-card-head">
      <div class="formules-card-time" title="De ${escapeHtml(formatClockDisplay(span.start))} à ${escapeHtml(formatClockDisplay(span.end))}">
        <strong>${escapeHtml(formatClockDisplay(span.start))}</strong>
        <span>${escapeHtml(formatClockDisplay(span.end))}</span>
      </div>
      <div class="formules-card-id">
        <strong>${escapeHtml(reservation.name || 'Groupe')}</strong>
        <span>${escapeHtml([getReservationLabel(reservation), formatStaffTerrainCount(pax, 'joueur'), getStaffDashboardStatusMeta(reservation).label].join(' · '))}</span>
      </div>
      ${count}
      <button type="button" class="formules-card-open" onclick="openStaffReservationDetail(${staffClientJs(reservation.id)})">Ouvrir</button>
    </div>`;
  if (phase === 'done') {
    return `<article class="formules-card is-compact${summary.allDone ? ' all-done' : ''}" data-formule-id="${escapeHtml(String(reservation.id))}">${head}</article>`;
  }
  const checklist = renderFormulaActivityChecklist(reservation, { bare: true });
  return `<article class="formules-card${summary.allDone ? ' all-done' : ''}" data-formule-id="${escapeHtml(String(reservation.id))}">
    ${head}
    ${checklist || '<div class="formules-card-empty">Pas de plan d\'activités détaillé pour cette formule.</div>'}
  </article>`;
}

function renderStaffFormulesBoard(rows = []) {
  const formuleRows = [...rows].sort((left, right) => getStaffTerrainSpan(left).start - getStaffTerrainSpan(right).start);
  if (!formuleRows.length) {
    // Pas de bouton ici : « Nouvelle formule » est deja l action principale
    // de l en-tete. La liste d activites citee avant (arcades, minigolf...)
    // n etait pas celle du centre : on decrit sans inventer.
    return `<div class="events-empty-state">
      <strong>Aucune formule sur cette date.</strong>
    </div>`;
  }
  const today = todayStr();
  const context = {
    when: state.currentDate < today ? 'past' : state.currentDate > today ? 'future' : 'today',
    now: currentTimeDecimal()
  };
  const groups = { live: [], upcoming: [], done: [] };
  formuleRows.forEach(reservation => groups[getStaffFormulaPhase(reservation, context)].push(reservation));
  const titles = { live: 'En cours', upcoming: 'À venir', done: 'Terminées' };
  return ['live', 'upcoming', 'done'].filter(key => groups[key].length).map(key => {
    const cards = groups[key];
    const done = cards.reduce((sum, reservation) => sum + getFormulaActivityProgressSummary(reservation).done, 0);
    const total = cards.reduce((sum, reservation) => sum + getFormulaActivityProgressSummary(reservation).total, 0);
    return `<section class="formules-group is-${key}" aria-labelledby="formules-${key}-title">
      <div class="formules-group-head">
        <h3 id="formules-${key}-title">${escapeHtml(titles[key])}</h3>
        <span>${cards.length} formule${cards.length > 1 ? 's' : ''}${total ? ` · ${done}/${total} activité${total > 1 ? 's' : ''} cochée${total > 1 ? 's' : ''}` : ''}</span>
      </div>
      <div class="formules-board${key === 'done' ? ' is-compact' : ''}">${cards.map(reservation => renderFormuleTrackingCard(reservation, key)).join('')}</div>
    </section>`;
  }).join('');
}

// ── Performance 30 jours des ressources (2026-08-25, Movsar : « pistes
// bowling et laser game ne servent a rien tels quels, fais un truc vrm
// utile »). La fenetre = les 30 jours REVOLUS (hier inclus, jamais
// aujourd hui : la journee en cours fausserait les moyennes). Source :
// le cache fusionne du CRM (deja memoise), donc zero cout reseau.
// La borne est une date LOCALE : toISOString() la rendait en UTC, soit la
// veille a Bruxelles (minuit local = 22 h ou 23 h UTC), et la fenetre
// comptait 31 jours.
function getStaffResourceHistoryRows() {
  const end = todayStr();
  const from = (() => { const d = parseLocalDate(end); d.setDate(d.getDate() - 30); return toLocalDateStr(d); })();
  const source = typeof getStaffClientSourceReservations === 'function' ? getStaffClientSourceReservations() : (state.reservations || []);
  return source.filter((r) => r && r.status !== 'cancelled' && String(r.date || '') >= from && String(r.date || '') < end);
}

// CES 30 JOURS NE SONT UN CHIFFRE QU UNE FOIS ARRIVES. Avant la reponse de
// /api/admin-range, getStaffResourceHistoryRows ne voit que les dates ouvertes
// sur ce poste : « 30 j · 0% » s affichait comme un fait le temps du
// chargement, et pour de bon si la lecture echouait. 'ok' | 'charge' | 'erreur'.
function getStaffHistoryState() {
  if (staffClientDataCache.loaded) return 'ok';
  return staffClientDataCache.error ? 'erreur' : 'charge';
}

function getStaffHistoryPendingLabel() {
  return getStaffHistoryState() === 'erreur' ? 'indisponible' : 'chargement…';
}

function computeStaffLaneStats30() {
  const rows = getStaffResourceHistoryRows();
  const lanes = Array.from({ length: getAvailabilityLaneCount() }, (_, index) => ({ lane: index + 1, hours: 0, resas: 0 }));
  rows.forEach((reservation) => {
    getBowlingWindowsFromReservation(reservation).forEach((window) => {
      (window.lanes || []).forEach((lane) => {
        const slot = lanes[lane - 1];
        if (slot) { slot.hours += Number(window.duration || 0); slot.resas += 1; }
      });
    });
  });
  // Heures ouvrees par piste sur la fenetre : le denominateur honnete de
  // l occupation (un jour ferme ne compte pas comme du temps invendu).
  let openHours = 0;
  for (let i = 1; i <= 30; i += 1) {
    const d = parseLocalDate(todayStr()); d.setDate(d.getDate() - i);
    const win = getPlanningWindow(toLocalDateStr(d));
    if (!win.closed) openHours += Math.max(0, Number(win.close) - Number(win.open));
  }
  const totalHours = lanes.reduce((sum, item) => sum + item.hours, 0);
  const average = lanes.length ? totalHours / lanes.length : 0;
  return { lanes, openHours, totalHours, average };
}

// Joueurs que le serveur compte contre les armes pour un lancement : les
// siens et ceux de TOUT lancement qui le chevauche (ops-engine additionne
// les fenetres qui le recouvrent, meme quand elles ne se recouvrent pas entre
// elles). Les armes se partagent entre lancements paralleles (Gembloux en
// fait tourner six sur 20 postes) : compter un lancement seul promettait des
// places que la reservation refuse.
function getLaserSessionArenaPlayers(session, sessions) {
  return sessions
    .filter((other) => other.start < session.end && other.end > session.start)
    .reduce((sum, other) => sum + other.players, 0);
}

// Places restees vides : une grappe de lancements qui se chevauchent partage
// les memes armes, elle laisse vide ce qui reste au plus charge, une fois.
function getLaserEmptySeats(sessions, capacity) {
  const sorted = sessions.slice().sort((a, b) => a.start - b.start);
  let empty = 0;
  let grappe = [];
  let finGrappe = -Infinity;
  const clore = () => {
    if (!grappe.length) return;
    empty += Math.max(0, capacity - Math.max(...grappe.map((session) => getLaserSessionArenaPlayers(session, grappe))));
  };
  sorted.forEach((session) => {
    if (session.start >= finGrappe) { clore(); grappe = []; }
    grappe.push(session);
    finGrappe = Math.max(finGrappe, session.end);
  });
  clore();
  return empty;
}

function computeStaffLaserStats30() {
  const rows = getStaffResourceHistoryRows();
  const sessions = new Map();
  rows.forEach((reservation) => {
    getLaserWindowsFromReservation(reservation).forEach((window) => {
      const key = `${reservation.date}|${Number(window.start).toFixed(3)}`;
      const group = sessions.get(key) || { players: 0, start: Number(window.start), end: Number(window.end), date: reservation.date };
      group.players += Number(window.players || reservation.pax || 0);
      sessions.set(key, group);
    });
  });
  const list = [...sessions.values()];
  const players = list.reduce((sum, group) => sum + group.players, 0);
  const capacity = getAvailabilityLaserCapacity();
  const parJour = new Map();
  list.forEach((group) => parJour.set(group.date, [...(parJour.get(group.date) || []), group]));
  const fill = list.length ? Math.round((list.reduce((sum, group) => sum + Math.min(1, getLaserSessionArenaPlayers(group, parJour.get(group.date)) / capacity), 0) / list.length) * 100) : 0;
  // Places restees vides sur des lancements DEJA payes en energie et en
  // staff : le manque a gagner le plus concret du laser.
  const emptySeats = [...parJour.values()].reduce((sum, jour) => sum + getLaserEmptySeats(jour, capacity), 0);
  const hourCount = new Map();
  list.forEach((group) => { const h = Math.floor(group.start); hourCount.set(h, (hourCount.get(h) || 0) + group.players); });
  const topHours = [...hourCount.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3);
  return { sessions: list.length, players, fill, emptySeats, topHours, capacity };
}

// ── LE MUR DES PISTES (2026-08-25, 2e verdict Movsar : « une page ou on VA
// pour REGLER des choses ou VOIR »). Ce qu on vient y faire :
//   1. REGLER une panne : fermer/rouvrir, et REPLACER les resas posees sur
//      la piste fermee (chaque bouton ouvre LA resa) ;
//   2. VOIR l etat vivant : occupee par qui jusqu a quand, les creux du
//      jour piste par piste (reglette cliquable) ;
//   3. VENDRE un creux : le clic ouvre la resa rapide preremplie (meme
//      geste que le planning : quickFromCell) ;
//   4. DECIDER : l occupation 30 j par piste, en bout de rangee, discrete.
function buildStaffLaneBoardModel() {
  const win = getPlanningWindow(state.currentDate);
  const reservations = getStaffUtilityReservations();
  const allWindows = reservations.flatMap((reservation) => getBowlingWindowsFromReservation(reservation).map((window) => ({ ...window, reservation })));
  const isToday = state.currentDate === todayStr();
  const now = isToday && !win.closed ? currentTimeDecimal() : null;
  const stats30 = computeStaffLaneStats30();
  const lanes = [];
  // Autant de rangees que de pistes REELLES du centre, comme la grille du
  // planning : un centre a 6 pistes n a pas de « Piste 7 » a louer.
  const laneCount = getAvailabilityLaneCount();
  for (let lane = 1; lane <= laneCount; lane += 1) {
    const laneWindows = allWindows.filter((w) => (w.lanes || []).includes(lane)).sort((a, b) => a.start - b.start);
    const maintenance = state.laneStatuses?.[lane] === 'maintenance';
    const maintInfo = maintenance ? (state.laneMaintenance?.[lane] || {}) : null;
    const current = now != null ? laneWindows.find((w) => w.start <= now && w.end > now) : null;
    const next = laneWindows.find((w) => (now == null ? true : w.start > now)) || null;
    // Les creux du jour (>= 1 h) : chacun est un bouton de vente.
    const gaps = [];
    if (!win.closed) {
      let cursor = win.open;
      laneWindows.forEach((w) => {
        if (w.start - cursor >= 1) gaps.push({ start: cursor, end: w.start });
        cursor = Math.max(cursor, w.end);
      });
      if (win.close - cursor >= 1) gaps.push({ start: cursor, end: win.close });
    }
    const st = stats30.lanes[lane - 1] || { hours: 0, resas: 0 };
    lanes.push({
      lane, maintenance, maintInfo, laneWindows, current, next, gaps,
      // Piste fermee = ses resas du jour sont un PROBLEME a regler ici.
      toRelocate: maintenance ? laneWindows : [],
      pct30: stats30.openHours ? Math.round((st.hours / stats30.openHours) * 100) : 0,
      hours30: st.hours,
      weak: stats30.average >= 2 && st.hours < stats30.average * 0.5,
    });
  }
  const active = lanes.filter((item) => !item.maintenance);
  const busyNow = now == null ? 0 : active.filter((item) => item.current).length;
  const busyEnds = active.map((item) => item.current).filter(Boolean).map((w) => w.end);
  const nextFree = now != null && busyEnds.length ? numToTime(Math.min(...busyEnds)) : '';
  let eveningSold = 0;
  allWindows.forEach((w) => { eveningSold += Math.max(0, Math.min(w.end, 22) - Math.max(w.start, 19)); });
  const eveningSpan = win.closed ? 0 : Math.max(0, Math.min(22, win.close) - 19);
  const eveningPct = eveningSpan > 0 && active.length ? Math.min(100, Math.round((eveningSold / (eveningSpan * active.length)) * 100)) : 0;
  const relocateCount = lanes.reduce((sum, item) => sum + item.toRelocate.length, 0);
  const dayHours = allWindows.reduce((sum, w) => sum + Math.max(0, w.end - w.start), 0);
  const kpis = now != null ? [
    ['Maintenant', `${busyNow}/${active.length}`, 'pistes occupées'],
    ['Se libère', nextFree || 'aucune', nextFree ? 'prochaine piste libre' : 'rien d’occupé'],
    ['Soirée 19-22h', eveningSpan > 0 ? `${eveningPct}%` : 'fermé', 'des heures vendues'],
    ['À replacer', relocateCount, relocateCount ? 'résas sur piste fermée' : 'rien en souffrance'],
  ] : [
    ['Résas bowling', allWindows.length, 'sur la date affichée'],
    ['Heures vendues', formatDurationLabel(dayHours), 'toutes pistes'],
    ['Fermées', lanes.length - active.length, 'pistes en maintenance'],
    ['À replacer', relocateCount, 'résas sur piste fermée'],
  ];
  return { win, lanes, isToday, now, kpis };
}

function renderStaffLaneBoard(model = buildStaffLaneBoardModel()) {
  const { win } = model;
  const span = Math.max(1, win.closed ? 12 : win.close - win.open);
  const pos = (value) => Math.max(0, Math.min(100, ((value - win.open) / span) * 100));
  // Un creux se vend avec « Réserver au comptoir », une piste se ferme avec
  // « Fermer une piste » : sans le droit, ni l un ni l autre ne se montre.
  const reserve = peutGeste('reserver');
  const ferme = peutGeste('fermerPiste');
  const rows = model.lanes.map((item) => {
    const gapsHtml = !reserve ? '' : item.gaps.map((gap) => `<button type="button" class="lane-gap" style="left:${pos(gap.start)}%;width:${Math.max(2, pos(gap.end) - pos(gap.start))}%" title="Réserver ${numToTime(gap.start)} - ${numToTime(gap.end)}" onclick="quickFromCell(${item.lane}, ${gap.start})" aria-label="Réserver la piste ${item.lane} de ${numToTime(gap.start)} à ${numToTime(gap.end)}"></button>`).join('');
    const slotsHtml = item.laneWindows.map((w) => `<button type="button" class="lane-slot" style="left:${pos(w.start)}%;width:${Math.max(2, pos(w.end) - pos(w.start))}%" title="${escapeHtml(w.reservation.name || 'Client')} · ${numToTime(w.start)} - ${numToTime(w.end)}" onclick="openStaffReservationDetail(${staffClientJs(w.reservation.id)})"></button>`).join('');
    // Les reperes d ouverture et de fermeture encadrent le ruban au lieu d y
    // flotter : dans le ruban, un creneau qui commence a l ouverture passait
    // par-dessus le « 14:00 » de la piste la plus chargee.
    const strip = win.closed ? '' : `<div class="lane-strip-rail"><span class="lane-strip-open">${numToTime(win.open)}</span><div class="lane-strip">${gapsHtml}${slotsHtml}</div><span class="lane-strip-close">${numToTime(win.close)}</span></div>`;
    let statut;
    if (item.maintenance) {
      const info = item.maintInfo || {};
      statut = `Fermée${info.note ? ` · ${escapeHtml(info.note)}` : ''}${info.until ? ` · jusqu’au ${escapeHtml(info.until)}` : ''}`;
    } else if (item.current) {
      statut = `Occupée · <b>${escapeHtml(item.current.reservation.name || 'Client')}</b> (${formatStaffTerrainCount(Number(item.current.players) || getReservationActivityPlayers(item.current.reservation, 'bowling'), 'joueur')}) jusqu’à ${numToTime(item.current.end)}${item.next ? `, puis ${numToTime(item.next.start)}` : ''}`;
    } else if (model.now != null) {
      statut = item.next ? `Libre jusqu’à ${numToTime(item.next.start)} · <b>${escapeHtml(item.next.reservation.name || 'Client')}</b> ensuite` : 'Libre jusqu’à la fermeture';
    } else {
      statut = item.laneWindows.length ? `${item.laneWindows.length} résa${item.laneWindows.length > 1 ? 's' : ''} sur la date` : 'Libre sur la date';
    }
    const relocate = item.toRelocate.length ? `<div class="lane-relocate" data-role="lane-replace"><span>À replacer :</span>${item.toRelocate.map((w) => `<button type="button" onclick="openStaffReservationDetail(${staffClientJs(w.reservation.id)})">${escapeHtml(w.reservation.name || 'Client')} · ${numToTime(w.start)}</button>`).join('')}</div>` : '';
    const actions = !ferme ? ''
      : item.maintenance
        ? `<button type="button" onclick="toggleMaint(${item.lane}, event)">Rouvrir</button>`
        : `<button type="button" onclick="toggleMaint(${item.lane}, event)">Fermer</button><button type="button" onclick="openLaneMaintForm(${item.lane}, event)">Entretien…</button>`;
    return `<div class="lane-row${item.maintenance ? ' is-maintenance' : ''}${item.current ? ' is-busy' : ''}" data-lane="${item.lane}">
      <div class="lane-row-id"><span class="lane-dot" aria-hidden="true"></span><strong>Piste ${item.lane}</strong></div>
      <div class="lane-row-main">
        <div class="lane-row-status">${statut}</div>
        ${strip}
        ${relocate}
        ${laneMaintFormLane === item.lane ? renderLaneMaintForm(item.lane) : ''}
      </div>
      <div class="lane-row-side">
        ${getStaffHistoryState() === 'ok'
          ? `<span class="lane-pct${item.weak ? ' is-weak' : ''}" data-role="lane-pct" data-pct="${item.pct30}" title="${formatDurationLabel(item.hours30)} réservées sur les 30 derniers jours">30 j · ${item.pct30}%${item.weak ? ' · sous-utilisée' : ''}</span>`
          : `<span class="lane-pct is-pending" data-role="lane-pct" title="Occupation des 30 derniers jours">30 j · ${getStaffHistoryPendingLabel()}</span>`}
        <div class="lane-row-actions">${actions}</div>
      </div>
    </div>`;
  }).join('');
  return `<div class="lane-board">${rows}</div>`;
}

// ── LE TABLEAU LASER : repondre au comptoir (prochain lancement, places
// restantes), COMPLETER les sessions faibles a venir, decider sur 30 jours.
function buildStaffLaserBoardModel() {
  const win = getPlanningWindow(state.currentDate);
  const sessions = getStaffUtilityLaserSessions();
  const isToday = state.currentDate === todayStr();
  const now = isToday && !win.closed ? currentTimeDecimal() : null;
  const cap = getAvailabilityLaserCapacity();
  sessions.forEach((session) => {
    session.arena = getLaserSessionArenaPlayers(session, sessions);
    session.remaining = Math.max(0, cap - session.arena);
    session.parallels = sessions.filter((other) => other !== session && other.start < session.end && other.end > session.start).length;
  });
  const upcoming = now == null ? sessions.slice() : sessions.filter((session) => session.start > now);
  const next = upcoming[0] || null;
  const weakUpcoming = upcoming.filter((session) => session.arena / cap < 0.5);
  const playersToday = sessions.reduce((sum, session) => sum + session.players, 0);
  const stats30 = computeStaffLaserStats30();
  const gaps = [];
  if (!win.closed) {
    let cursor = win.open;
    sessions.forEach((session) => {
      if (session.start - cursor >= 1.5) gaps.push({ start: cursor, end: session.start });
      cursor = Math.max(cursor, session.end);
    });
    if (win.close - cursor >= 1.5) gaps.push({ start: cursor, end: win.close });
  }
  const nextPlaces = next ? next.remaining : 0;
  const kpis = [
    ['Prochain lancement', next ? numToTime(next.start) : 'aucun', next ? `${nextPlaces} places restantes` : (isToday ? 'plus rien aujourd’hui' : 'sur la date affichée')],
    ['Sessions du jour', sessions.length, `${playersToday} joueur${playersToday > 1 ? 's' : ''}`],
    ['À compléter', weakUpcoming.length, 'sessions faibles à venir'],
    getStaffHistoryState() === 'ok'
      ? ['Remplissage 30 j', `${stats30.fill}%`, `${stats30.sessions} lancement${stats30.sessions > 1 ? 's' : ''}`]
      : ['Remplissage 30 j', getStaffHistoryPendingLabel(), 'historique du serveur'],
  ];
  return { win, sessions, next, nextPlaces, weakUpcoming, playersToday, stats30, gaps, isToday, now, kpis, cap };
}

function renderStaffLaserBoard(model = buildStaffLaserBoardModel()) {
  const { cap } = model;
  // LE BANDEAU RESUME, LA CARTE AGIT. Le bandeau portait « Ajouter un groupe »
  // pour le prochain lancement, et la carte de ce meme lancement, juste
  // dessous, « Compléter · 22 places » : deux boutons pour la meme session.
  // Sans aucun lancement, bandeau et etat vide disaient deux fois « rien » :
  // le bandeau se tait alors, l etat vide parle seul, et reserver reste
  // l action principale de l en-tete.
  let bandeau = '';
  if (model.next) {
    bandeau = `Prochain lancement <strong>${numToTime(model.next.start)}</strong> · ${model.nextPlaces ? `${model.nextPlaces} place${model.nextPlaces > 1 ? 's' : ''} restante${model.nextPlaces > 1 ? 's' : ''}` : 'complet'}`;
  } else if (model.sessions.length && model.isToday) {
    bandeau = 'Aucun autre lancement aujourd’hui.';
  } else if (model.sessions.length) {
    bandeau = `${model.sessions.length} lancement${model.sessions.length > 1 ? 's' : ''} sur la date affichée.`;
  }
  const sessionsHtml = model.sessions.map((session) => {
    // Tete, jauge et places parlent de l ARENE pendant ce lancement : un
    // lancement parallele occupe les memes armes.
    const { remaining, arena } = session;
    const enParallele = arena - session.players;
    const fillPct = Math.min(100, Math.round((arena / cap) * 100));
    const weak = arena / cap < 0.5;
    const future = model.now == null || session.start > model.now;
    const groups = session.reservations.map((item) => `<button type="button" onclick="openStaffReservationDetail(${staffClientJs(item.reservation.id)})">${escapeHtml(item.reservation.name || 'Client')} · ${formatStaffTerrainCount(Number(item.window.joueursReels ?? item.window.players) || Number(item.reservation.pax) || 0, 'joueur')}</button>`).join('');
    const partage = enParallele > 0
      ? `<div class="laser-session-shared" data-role="laser-shared">dont ${formatStaffTerrainCount(enParallele, 'joueur')} sur ${session.parallels > 1 ? `${session.parallels} lancements` : 'un lancement'} en parallèle</div>`
      : '';
    const action = future && remaining > 0 && peutGeste('reserver')
      ? `<div class="laser-session-action"><button type="button" onclick="openQuickBookForLaserSession(${Number(session.start)}, ${remaining})">${weak ? 'Compléter' : 'Ajouter un groupe'} · ${remaining} place${remaining > 1 ? 's' : ''}</button></div>`
      : (remaining <= 0 ? `<div class="laser-session-action"><span>${enParallele > 0 ? 'Arène complète.' : 'Session complète.'}</span></div>` : '');
    return `<article class="laser-session">
      <div class="laser-session-head"><strong>${numToTime(session.start)} - ${numToTime(session.end)}</strong><b data-role="laser-count">${arena}/${cap}</b></div>
      <div class="laser-fill${weak ? ' is-weak' : ''}"><i style="width:${fillPct}%"></i></div>
      <div class="laser-session-groups">${groups}</div>
      ${partage}
      ${action}
    </article>`;
  }).join('');
  const top = model.stats30.topHours.map(([hour, players]) => `${String(hour).padStart(2, '0')}h (${formatStaffTerrainCount(players, 'joueur')})`).join(', ');
  const bilan = getStaffHistoryState() === 'ok' && model.stats30.sessions
    ? `<div class="laser-30d">30 jours : <b>${model.stats30.fill}%</b> de remplissage moyen · ${formatStaffTerrainCount(model.stats30.sessions, 'lancement')} · ${formatStaffTerrainCount(model.stats30.players, 'joueur')} · <b>${model.stats30.emptySeats}</b> place${model.stats30.emptySeats > 1 ? 's' : ''} restée${model.stats30.emptySeats > 1 ? 's' : ''} vide${model.stats30.emptySeats > 1 ? 's' : ''} sur des lancements lancés${top ? ` · heures fortes : ${top}` : ''}</div>`
    : '';
  const vide = model.sessions.length ? '' : `<div class="utility-empty"><strong>Aucun lancement sur la date</strong><span>Réservez un laser : le premier groupe crée la session.</span></div>`;
  return `<div class="laser-board">${bandeau ? `<div class="laser-next">${bandeau}</div>` : ''}${sessionsHtml}${vide}${bilan}</div>`;
}
function getStaffUtilityLaserSessions(reservations = getStaffUtilityReservations()) {
  const groups = new Map();
  reservations.forEach(reservation => {
    getLaserWindowsFromReservation(reservation).forEach(window => {
      const key = `${Number(window.start).toFixed(3)}-${Number(window.end).toFixed(3)}`;
      const group = groups.get(key) || {
        start: Number(window.start),
        end: Number(window.end),
        reservations: [],
        players: 0
      };
      group.reservations.push({ reservation, window });
      group.players += Number(window.players || reservation.pax || 0);
      groups.set(key, group);
    });
  });
  return [...groups.values()].sort((left, right) => left.start - right.start);
}

let staffCenterConfigCache = { loaded: false, loading: false, error: '', centers: [], activities: [] };

const ESTABLISHMENT_DAYS = [
  ['1', 'Lundi'], ['2', 'Mardi'], ['3', 'Mercredi'], ['4', 'Jeudi'],
  ['5', 'Vendredi'], ['6', 'Samedi'], ['0', 'Dimanche']
];

async function loadStaffCenterConfig(force = false) {
  if (staffCenterConfigCache.loading) return;
  if (staffCenterConfigCache.loaded && !force) return;
  if (!canUseStaffPermission('settings.manage') && !canUseStaffPermission('direction.view')) return;
  staffCenterConfigCache.loading = true;
  if (force) staffCenterConfigCache.error = '';
  try {
    const response = await apiRequest(`${API_ENDPOINTS.ops}?action=centerConfig&centerId=${encodeURIComponent(getCurrentStaffCenterId())}`);
    staffCenterConfigCache = {
      loaded: true,
      loading: false,
      error: '',
      centers: Array.isArray(response.centers) ? response.centers : [],
      activities: Array.isArray(response.activities) ? response.activities : []
    };
    // Pousse la config fraîche (horaires, vacances/fériés, offres) dans
    // booking-core : planning staff et espace client la reflètent sans délai.
    const currentCenter = staffCenterConfigCache.centers.find(center => center.id === getCurrentStaffCenterId());
    if (currentCenter && typeof setCenterScheduleConfig === 'function') {
      setCenterScheduleConfig(currentCenter);
      if (state.view === 'client') {
        updateSchedHint();
        renderFormules();
      }
    }
  } catch (error) {
    staffCenterConfigCache.loading = false;
    staffCenterConfigCache.loaded = true;
    staffCenterConfigCache.error = error?.message || 'Lecture configuration impossible.';
  }
  if (state.view === 'staff' && ['establishment', 'lanes'].includes(getStaffMenuPage())) renderStaffUtilityPage();
  // Le planning ouvert se redessine avec la configuration arrivee (pistes,
  // horaires, armes laser) : il gardait sinon les valeurs par defaut jusqu a ce
  // qu une autre donnee le fasse repeindre. Son bandeau aussi : il comptait
  // les pistes libres sur le nombre par defaut (8), les pistes 7 et 8 d un
  // centre qui en a 6 s y disaient libres (journee-vraie, 2026-09-30).
  if (state.view === 'staff') {
    if (isStaffPlanningPageActive()) renderKpis();
    const planningBox = document.getElementById('planningBox');
    if (planningBox && !planningBox.classList.contains('hidden')) repaintKeepingScroll(planningBox, () => renderPlanning());
    const laserBox = document.getElementById('laserPlanningBox');
    if (laserBox && !laserBox.classList.contains('hidden')) repaintKeepingScroll(laserBox, () => renderLaserPlanning());
    const globalBox = document.getElementById('globalPlanningBox');
    if (globalBox && !globalBox.classList.contains('hidden')) repaintKeepingScroll(globalBox, () => renderGlobalPlanningSurface());
  }
}

// Aller a une case de la page SANS re-rendre : le rendu relirait la config du serveur et effacerait ce qui vient d etre tape.
function setEstablishmentTab(key) {
  state.establishmentTab = EB_ANCIENS_ONGLETS[key] || key || 'centre';
  save();
  if (document.querySelector('[data-estab-page]')) ebGo(state.establishmentTab);
}

// Un champ invalide peut se trouver dans une case fermee : sans ca, le toast
// "corrigez les champs" pointerait vers un champ que personne ne voit.
function focusEstablishmentField(input) {
  if (!input) return;
  const panneau = input.closest('.eb-pan');
  if (panneau && panneau.hidden) ebOuvrir(panneau.dataset.k);
  // Un champ cache (l etat ferme d un jour, un choix porte par des touches) laisse le clavier a ce qu on touche a cote.
  let cible = input;
  if (input.hidden) {
    const jour = /^(estab-h?day-\d)-closed$/.exec(input.id || '');
    cible = (jour && document.getElementById(`eb-open-${jour[1]}`))
      || document.querySelector(`[data-eb-seg="${CSS.escape(input.id)}"] .eb-seg-btn`)
      || null;
  }
  if (!cible) return;
  if (cible.scrollIntoView) cible.scrollIntoView({ block: 'center' });
  cible.focus({ preventScroll: true });
}

// Le centre de la page est celui du menu : fermer un jour, couper le formulaire du site ou enregistrer partent vers lui.
function getEstablishmentCenter() {
  const centers = staffCenterConfigCache.centers || [];
  if (!centers.length) return null;
  const actif = getCurrentStaffCenterId();
  return centers.find(center => center.id === actif) || centers.find(center => center.id === state.establishmentCenterId) || centers[0];
}

// Le champ demande avant un changement de centre : changer de centre recharge la console, la page le pose des
// qu elle s affiche de l autre cote (15 s au plus, et le premier clic dans la page l oublie).
const EB_CHAMP_VOULU = 'pinlane-etab-champ-voulu';
function ebChampVoulu(centre, champ) {
  try {
    if (centre) sessionStorage.setItem(EB_CHAMP_VOULU, JSON.stringify({ centre, champ, jusqua: Date.now() + 15000 }));
    else sessionStorage.removeItem(EB_CHAMP_VOULU);
  } catch (error) { /* stockage ferme : le curseur reste ou il est */ }
}
function ebChampVouluLu() {
  try { return JSON.parse(sessionStorage.getItem(EB_CHAMP_VOULU) || 'null'); } catch (error) { return null; }
}

// Ajouter une adresse de secours : le chemin direct, depuis la Tour ou la page Secours. La case s ouvre sur le bon centre, le champ pret a ecrire.
function ouvrirReglageSecours(centerId) {
  if (!canUseStaffPermission('settings.manage')) { toast('Édition réservée à la direction.'); return; }
  const cible = centerId || getCurrentStaffCenterId();
  state.establishmentTab = 'accueil';
  state.establishmentEditing = false;
  save();
  if (cible !== getCurrentStaffCenterId()) {
    ebChampVoulu(cible, 'estab-secours-emails');
    if (!(typeof window.pinlaneChoisirCentre === 'function' && window.pinlaneChoisirCentre(cible))) {
      ebChampVoulu(null);
      toast('Ce centre n’est pas dans vos accès.');
      return;
    }
  }
  const entree = document.querySelector('[data-fgx-menu-key="establishment"]');
  if (entree) entree.click();
  let essais = 0;
  const poser = () => {
    const page = document.querySelector('[data-estab-page]');
    const champ = document.getElementById('estab-secours-emails');
    if (state.staffMenuPage !== 'establishment' || !page || page.dataset.ebCenter !== cible || !champ) { if (essais++ < 80) setTimeout(poser, 100); return; }
    focusEstablishmentField(champ);
  };
  setTimeout(poser, 0);
}

// En changer ici, c est le meme geste que dans le menu : toute la console passe a ce centre.
function selectEstablishmentCenter(id) {
  if (!id || id === getCurrentStaffCenterId()) return;
  state.establishmentEditing = false;
  if (typeof window.pinlaneChoisirCentre === 'function' && window.pinlaneChoisirCentre(id)) return;
  toast('Ce centre n’est pas dans vos accès.');
}

// Groupe une liste de centres par client. Sert au groupement de la vue
// PROPRIETAIRE (plusieurs clients) ; pour un client (un seul groupe) le rendu
// reste une liste plate. Trie : clients par nom, orphelins (sans client) en fin.
function groupCentersByClient(centers = []) {
  const groups = new Map();
  centers.forEach(c => {
    const key = c.clientId || '';
    if (!groups.has(key)) groups.set(key, { clientId: c.clientId || null, clientName: c.clientName || null, centers: [] });
    groups.get(key).centers.push(c);
  });
  return [...groups.values()].sort((a, b) => {
    if (!a.clientName && b.clientName) return 1;
    if (a.clientName && !b.clientName) return -1;
    return String(a.clientName || '').localeCompare(String(b.clientName || ''), 'fr');
  });
}

// Brouillon des overrides ponctuels (jour forcé vacances/normal) pendant
// l'édition : manipulé en direct dans le DOM pour ne pas perdre les autres
// champs non sauvegardés à chaque ajout/retrait.
let establishmentHolidayOverridesDraft = [];
let establishmentCustomActivitiesDraft = [];
// Ressources DECLAREES du centre (padel, paintball, salle...) : le moteur les
// compte comme les pistes. Brouillon manipulé en direct, même doctrine que les
// activités personnalisées.
let establishmentDeclaredResourcesDraft = [];

function establishmentUpsellCatalogue() {
  const selectedCenter = getEstablishmentCenter();
  return (staffCenterConfigCache.activities || []).map(activity => ({
    ...activity,
    ...(typeof getCenterActivity === 'function' ? getCenterActivity(activity.id) || {} : {}),
    label: activity.label || activity.name || activity.id,
    ...(activity.id === 'arcade_time' && selectedCenter?.activityOffers?.arcade_time
      ? { arcadeOffers: selectedCenter.activityOffers.arcade_time } : {})
  }));
}

function cancelEstablishmentEdit() {
  window.PinlaneUpsellSettings?.cancel();
  state.establishmentEditing = false;
  establishmentHolidayOverridesDraft = [];
  establishmentCustomActivitiesDraft = [];
  establishmentDeclaredResourcesDraft = [];
  establishmentValidationDraft = null;
  renderStaffUtilityPage();
}

function establishmentSlugify(value) {
  return String(value || '').trim().toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);
}

function renderEstablishmentCustomActivities() {
  if (!establishmentCustomActivitiesDraft.length) {
    return '<p class="estab-overrides-empty">Aucune activité à vous pour l’instant : réalité virtuelle, karaoké, escape game…</p>';
  }
  return establishmentCustomActivitiesDraft.map(item => `<div class="estab-custom-activity">
    <span>${escapeHtml(item.label)}</span>
    <button type="button" class="estab-override-remove" aria-label="Retirer l'activité ${escapeHtml(item.label)}" onclick="removeEstablishmentCustomActivity('${escapeJsString(item.id)}')">
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button>
  </div>`).join('');
}

function refreshEstablishmentCustomActivitiesList() {
  const list = document.getElementById('estabCustomActivitiesList');
  if (list) list.innerHTML = renderEstablishmentCustomActivities();
}

function addEstablishmentCustomActivity() {
  const input = document.getElementById('estab-new-activity');
  const label = String(input?.value || '').trim().slice(0, 60);
  if (!label) { toast('Donnez un nom à l\'activité.'); return; }
  const id = establishmentSlugify(label);
  if (!id) { toast('Nom d\'activité invalide.'); return; }
  if (establishmentCustomActivitiesDraft.some(item => item.id === id)) { toast('Cette activité existe déjà.'); return; }
  if (establishmentCustomActivitiesDraft.length >= 40) { toast('Maximum 40 activités personnalisées.'); return; }
  establishmentCustomActivitiesDraft.push({ id, label });
  if (input) input.value = '';
  refreshEstablishmentCustomActivitiesList();
}

function removeEstablishmentCustomActivity(id) {
  establishmentCustomActivitiesDraft = establishmentCustomActivitiesDraft.filter(item => item.id !== id);
  refreshEstablishmentCustomActivitiesList();
}

// Ids que la donnée ne peut pas revendiquer (familles historiques et
// pseudo-types du moteur) : mêmes réservations que lib/declared-resources.js.
const ESTABLISHMENT_RESERVED_RESOURCE_IDS = ['bowling_lane', 'laser_arena', 'party_table', 'bar_service', 'bar_service_then_autonomous', 'soft_capacity', 'free_activity', 'transition', 'service'];

function renderEstablishmentDeclaredResources() {
  if (!establishmentDeclaredResourcesDraft.length) {
    return '<p class="estab-overrides-empty">Aucune installation en plus : un court de padel, un terrain de paintball, une salle que le planning doit compter.</p>';
  }
  return establishmentDeclaredResourcesDraft.map(item => `<div class="estab-custom-activity">
    <span>${escapeHtml(item.name)} : ${Number(item.units)} de ${Number(item.capacityPerUnit)} joueurs, remise en état ${Number(item.cleanupMinutes)} min${item.allowGroupMixing ? ', deux groupes ensemble' : ''}</span>
    <button type="button" class="estab-override-remove" aria-label="Retirer l'installation ${escapeHtml(item.name)}" onclick="removeEstablishmentDeclaredResource('${escapeJsString(item.id)}')">
      <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
    </button>
  </div>`).join('');
}

function refreshEstablishmentDeclaredResourcesList() {
  const list = document.getElementById('estabDeclaredResourcesList');
  if (list) list.innerHTML = renderEstablishmentDeclaredResources();
}

function addEstablishmentDeclaredResource() {
  const nameInput = document.getElementById('estab-res-name');
  const name = String(nameInput?.value || '').trim().slice(0, 60);
  if (!name) { toast('Donnez un nom à l\'installation.'); return; }
  const id = establishmentSlugify(name).replace(/-/g, '_');
  if (!id) { toast('Nom d\'installation invalide.'); return; }
  if (ESTABLISHMENT_RESERVED_RESOURCE_IDS.includes(id)) { toast('Ce nom est réservé au moteur, choisissez-en un autre.'); return; }
  if (establishmentDeclaredResourcesDraft.some(item => item.id === id)) { toast('Cette installation existe déjà.'); return; }
  if (establishmentDeclaredResourcesDraft.length >= 20) { toast('Maximum 20 installations déclarées.'); return; }
  const units = Number(document.getElementById('estab-res-units')?.value);
  const capacityPerUnit = Number(document.getElementById('estab-res-capacity')?.value);
  const cleanupMinutes = Number(document.getElementById('estab-res-cleanup')?.value || 0);
  if (!Number.isInteger(units) || units < 1 || units > 50) { toast('Installations : entier entre 1 et 50.'); return; }
  if (!Number.isInteger(capacityPerUnit) || capacityPerUnit < 1 || capacityPerUnit > 500) { toast('Joueurs par installation : entier entre 1 et 500.'); return; }
  if (!Number.isInteger(cleanupMinutes) || cleanupMinutes < 0 || cleanupMinutes > 240) { toast('Remise en état : entier entre 0 et 240 minutes.'); return; }
  establishmentDeclaredResourcesDraft.push({
    id,
    name,
    units,
    capacityPerUnit,
    cleanupMinutes,
    allowGroupMixing: !!document.getElementById('estab-res-mixing')?.checked
  });
  if (nameInput) nameInput.value = '';
  refreshEstablishmentDeclaredResourcesList();
}

function removeEstablishmentDeclaredResource(id) {
  establishmentDeclaredResourcesDraft = establishmentDeclaredResourcesDraft.filter(item => item.id !== id);
  refreshEstablishmentDeclaredResourcesList();
}

function renderEstablishmentOverridesList() {
  if (!establishmentHolidayOverridesDraft.length) {
    return '<p class="estab-overrides-empty">Aucun jour à part : les jours fériés belges et les congés scolaires s’appliquent tout seuls.</p>';
  }
  return establishmentHolidayOverridesDraft
    .slice()
    .sort((a, b) => (a.date < b.date ? -1 : 1))
    .map(item => `<div class="estab-override-chip ${item.mode === 'holiday' ? 'is-holiday' : 'is-normal'}">
      <span class="num">${escapeHtml(new Date(`${item.date}T12:00:00`).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }))}</span>
      <span>${item.mode === 'holiday' ? 'Horaires de vacances' : 'Horaires normaux'}</span>
      <button type="button" class="estab-override-remove" aria-label="Retirer le jour à part du ${escapeHtml(item.date)}" onclick="removeEstablishmentHolidayOverride('${escapeJsString(item.date)}')">
        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>`)
    .join('');
}

function refreshEstablishmentOverridesList() {
  const list = document.getElementById('estabHolidayOverridesList');
  if (list) list.innerHTML = renderEstablishmentOverridesList();
}

function addEstablishmentHolidayOverride() {
  const dateInput = document.getElementById('estab-override-date');
  const modeInput = document.getElementById('estab-override-mode');
  const date = String(dateInput?.value || '').trim();
  const mode = modeInput?.value === 'normal' ? 'normal' : 'holiday';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) { toast('Choisissez une date valide.'); return; }
  establishmentHolidayOverridesDraft = establishmentHolidayOverridesDraft.filter(item => item.date !== date);
  establishmentHolidayOverridesDraft.push({ date, mode });
  if (dateInput) dateInput.value = '';
  refreshEstablishmentOverridesList();
}

function removeEstablishmentHolidayOverride(date) {
  establishmentHolidayOverridesDraft = establishmentHolidayOverridesDraft.filter(item => item.date !== date);
  refreshEstablishmentOverridesList();
}

function establishmentInputValue(id, fallback = '') {
  const el = document.getElementById(id);
  return el ? el.value : fallback;
}

function collectEstablishmentArcadeOffers(center) {
  const previous = center.activityOffers || {};
  if (!document.getElementById('estab-arc-enabled')) return previous;
  const read = (id) => document.getElementById(id)?.value;
  const offers = previous.arcade_time || {};
  const rows = (mode,list) => (list || []).map((o,i) => { const result={...o,enabled:!!document.getElementById(`estab-arc-${mode}-${i}-enabled`)?.checked}; ['price',...(mode === 'time' ? ['minutes'] : ['credits','bonusCredits'])].forEach(k => result[k]=Number(read(`estab-arc-${mode}-${i}-${k}`))); return result; });
  return {...previous,arcade_time:{...offers,enabled:!!document.getElementById('estab-arc-enabled').checked,timeOffers:rows('time',offers.timeOffers),creditOffers:rows('credit',offers.creditOffers),creditGameCostMin:Number(read('estab-arc-gameMin')),creditGameCostMax:Number(read('estab-arc-gameMax')),timedDescription:read('estab-arc-timeDescription') || '',creditDescription:read('estab-arc-creditDescription') || ''}};
}

function collectEstablishmentScheduleBlock(prefix) {
  const block = {};
  ESTABLISHMENT_DAYS.forEach(([key]) => {
    const open = establishmentInputValue(`${prefix}-${key}-open`);
    let close = establishmentInputValue(`${prefix}-${key}-close`);
    // Une fermeture avant l ouverture, jusqu a 06:00, est celle du lendemain : 00:00 devient 24:00, 01:30 devient 25:30.
    if (ebApresMinuit(open, close)) close = ebLendemain(close);
    const closed = document.getElementById(`${prefix}-${key}-closed`)?.checked;
    block[key] = closed || !open || !close ? null : { open, close };
  });
  return block;
}

// A3 : bornes alignées sur la validation serveur (lib/center-config.js,
// clampInt) : le front refuse AVANT envoi ce que le serveur re-clamperait en
// silence. Pattern DESIGN.md §6 : bordure danger (aria-invalid) + message
// 12px role="alert" sous le champ.
const ESTABLISHMENT_NUMBER_RULES = [
  ['estab-laneCount', 1, 40, 'Pistes : un nombre entier de 1 à 40.'],
  ['estab-normalCap', 1, 12, 'Joueurs par piste : un nombre entier de 1 à 12.'],
  ['estab-emergencyCap', 1, 15, 'Joueurs par piste si besoin : un nombre entier de 1 à 15.'],
  ['estab-weaponCount', 0, 200, 'Armes : un nombre entier de 0 à 200.'],
  ['estab-launches', 1, 20, 'Parties en même temps : un nombre entier de 1 à 20.'],
  ['estab-tableSoft', 1, 100, 'Tables conseillées : un nombre entier de 1 à 100.'],
  ['estab-tableHard', 1, 120, 'Limite de tables : un nombre entier de 1 à 120.'],
  ['estab-groupMinPax', 2, 200, 'Un groupe dès : un nombre entier de 2 à 200 joueurs.'],
  ['estab-groupMinCumulative', 2, 5000, 'Joueurs cumulés : un nombre entier de 2 à 5000.'],
  ['estab-keyClientMinSpend', 0, 100000, 'Client clé : un nombre entier d’euros, de 0 à 100000.'],
  ['estab-lateThreshold', 0, 60, 'En retard après : un nombre entier de 0 à 60 minutes.']
];

function clearEstablishmentFieldErrors() {
  document.querySelectorAll('[data-estab-page] .field-error-message').forEach(el => el.remove());
  document.querySelectorAll('[data-estab-page] [aria-invalid="true"]').forEach(el => el.removeAttribute('aria-invalid'));
}

function markEstablishmentFieldError(input, message) {
  if (!input) return;
  input.setAttribute('aria-invalid', 'true');
  const note = document.createElement('div');
  note.className = 'field-error-message';
  note.setAttribute('role', 'alert');
  note.textContent = message;
  // Une heure fautive se dit sous la semaine type, pas dans sa case etroite.
  const host = /^estab-h?day-/.test(input.id || '')
    ? document.getElementById('ebSemErreurs')
    : (input.closest('.eb-r') || input.closest('.field') || input.closest('.eb-met') || input.closest('.eb-ch'));
  if (host) host.appendChild(note);
  else input.insertAdjacentElement('afterend', note);
  if (typeof ebMarquerRubriques === 'function') ebMarquerRubriques();
}

// LES INSTALLATIONS D UNE ACTIVITE (2026-09-28), telles que le centre les a
// reglees (config activityCapacity), sinon celles du catalogue : tables de
// billard, pistes de duckpin et leurs joueurs, joueurs par session du Fun Run.
// null pour une activite qui n en compte aucune (minigolf, arcades).
function installationsActivite(activity, center) {
  if (!activity) return null;
  const socleUnits = Number(activity.units);
  const socleCapacite = Number(activity.capacityPerUnit);
  const comptee = Number.isFinite(socleUnits) && socleUnits > 0;
  if (!comptee && activity.priceType !== 'per_unit_hour') return null;
  const reglage = (center && center.activityCapacity && center.activityCapacity[activity.id]) || {};
  const libelle = String(activity.unitLabel || '');
  const mot = (/par ([a-zà-ÿ]+)/i.exec(libelle) || [])[1] || (/session/i.test(libelle) ? 'session' : 'installation');
  return {
    units: Number(reglage.units) > 0 ? Math.trunc(Number(reglage.units)) : (comptee ? Math.trunc(socleUnits) : 1),
    capacityPerUnit: Number(reglage.capacityPerUnit) > 0
      ? Math.trunc(Number(reglage.capacityPerUnit))
      : (Number.isFinite(socleCapacite) && socleCapacite > 0 ? Math.trunc(socleCapacite) : null),
    mot,
    // Le plus grand nombre qu une seule reservation peut prendre : celui du centre, sinon celui du catalogue.
    plafond: Number(reglage.maxPerBooking) > 0 ? Math.trunc(Number(reglage.maxPerBooking)) : (Number(activity.maxPerBooking) > 0 ? Math.trunc(Number(activity.maxPerBooking)) : null),
  };
}

function validateEstablishmentForm() {
  clearEstablishmentFieldErrors();
  const invalid = [];
  document.querySelectorAll('[id^="estab-arc-"][type="number"]').forEach(input => {
    const value=Number(input.value), min=Number(input.min), max=input.max ? Number(input.max) : 100000;
    if (input.value.trim() === '' || !Number.isFinite(value) || value<min || value>max || (input.step === '1' && !Number.isInteger(value))) { markEstablishmentFieldError(input,'Valeur Arcades hors limites.'); invalid.push(input); }
  });
  document.querySelectorAll('[data-arcade-offer="credit"]').forEach(row => {
    const index=row.dataset.arcadeIndex;
    const credits=document.getElementById(`estab-arc-credit-${index}-credits`),bonus=document.getElementById(`estab-arc-credit-${index}-bonusCredits`);
    if (credits && bonus && Number(credits.value)+Number(bonus.value)<=0) { markEstablishmentFieldError(credits,'La carte doit contenir des crédits.'); invalid.push(credits); }
  });
  const gameMin=document.getElementById('estab-arc-gameMin'), gameMax=document.getElementById('estab-arc-gameMax');
  if (gameMin && gameMax && Number(gameMax.value)<Number(gameMin.value)) { markEstablishmentFieldError(gameMax,'Le coût maximal doit être au moins égal au coût minimal.'); invalid.push(gameMax); }
  ESTABLISHMENT_NUMBER_RULES.forEach(([id, min, max, message]) => {
    const input = document.getElementById(id);
    if (!input) return;
    const value = Number(input.value);
    if (!Number.isInteger(value) || value < min || value > max) {
      markEstablishmentFieldError(input, message);
      invalid.push(input);
    }
  });
  // Les installations des activites : un entier, au moins 1. Une saisie
  // refusee revient au gerant avec sa raison, jamais jetee en silence.
  document.querySelectorAll('[data-estab-page] .estab-cap-input').forEach((input) => {
    const max = Number(input.dataset.capMax) || 50;
    const value = Number(input.value);
    if (!Number.isInteger(value) || value < 1 || value > max) {
      const nom = input.dataset.capName || 'Installations';
      const quoi = input.dataset.capWhat || 'installations';
      markEstablishmentFieldError(input, `${nom} : entrez un nombre entier de ${quoi}, de 1 à ${max}.`);
      invalid.push(input);
    }
  });
  // Couleur du tunnel : facultative, mais une saisie qui n'est PAS une couleur
  // ne doit pas partir en silence (le serveur la jetterait sans rien dire, et
  // le gérant croirait sa marque enregistrée). Un contraste faible, lui, ne
  // bloque jamais : c'est un avertissement, affiché sous le champ.
  const accentInput = document.getElementById('estab-accent');
  const accentRaw = accentInput ? String(accentInput.value || '').trim() : '';
  const brandApi = establishmentBrandApi();
  if (accentInput && accentRaw && (!brandApi || !brandApi.isValidHex(accentRaw))) {
    markEstablishmentFieldError(accentInput, 'Couleur du tunnel : un code hexadécimal comme #1f6f43, ou vide pour aucune marque.');
    invalid.push(accentInput);
  }
  // Cohérence : la capacité de secours ne peut pas être sous la capacité
  // confort (le serveur la relèverait en silence).
  const normalCap = Number(document.getElementById('estab-normalCap')?.value);
  const emergencyInput = document.getElementById('estab-emergencyCap');
  if (emergencyInput && !emergencyInput.hasAttribute('aria-invalid')
    && Number.isInteger(normalCap) && Number(emergencyInput.value) < normalCap) {
    markEstablishmentFieldError(emergencyInput, 'Joueurs par piste si besoin : au moins autant que les joueurs par piste.');
    invalid.push(emergencyInput);
  }
  const tablesConseillees = Number(document.getElementById('estab-tableSoft')?.value);
  const limiteTables = document.getElementById('estab-tableHard');
  if (limiteTables && !limiteTables.hasAttribute('aria-invalid')
    && Number.isInteger(tablesConseillees) && Number(limiteTables.value) < tablesConseillees) {
    markEstablishmentFieldError(limiteTables, 'Limite de tables : au moins autant que les tables conseillées.');
    invalid.push(limiteTables);
  }
  // Horaires : fermeture strictement après ouverture pour chaque jour ouvert
  // (00:00 saisi en fermeture = minuit, stocké 24:00).
  const toMinutes = (value) => {
    const [h, m] = String(value).split(':').map(Number);
    return h * 60 + m;
  };
  [['estab-day', 'Horaires normaux'], ['estab-hday', 'Horaires vacances/fériés']].forEach(([prefix, blockLabel]) => {
    ESTABLISHMENT_DAYS.forEach(([key, dayLabel]) => {
      if (document.getElementById(`${prefix}-${key}-closed`)?.checked) return;
      const closeInput = document.getElementById(`${prefix}-${key}-close`);
      const open = establishmentInputValue(`${prefix}-${key}-open`);
      let close = establishmentInputValue(`${prefix}-${key}-close`);
      if (!open || !close) return; // champ vide = jour stocké fermé (comportement existant)
      if (ebApresMinuit(open, close)) close = ebLendemain(close);
      if (toMinutes(close) <= toMinutes(open)) {
        markEstablishmentFieldError(closeInput, `${blockLabel}, ${dayLabel} : la fermeture doit être après l’ouverture. Après minuit, mettez l’heure du lendemain, jusqu’à 06:00.`);
        invalid.push(closeInput);
      }
    });
  });
  // Le logo et le site : le serveur ecarte en silence une adresse qu il ne sait pas servir, la page le dit avant.
  const logo = document.getElementById('estab-logo');
  if (logo && String(logo.value || '').trim() && !/^(?:https:\/\/[^\s"'<>]+|\.?\/?assets\/[a-z0-9_/.-]+)$/i.test(String(logo.value).trim())) {
    markEstablishmentFieldError(logo, 'Logo : l’adresse d’une image, qui commence par https://.');
    invalid.push(logo);
  }
  const site = document.getElementById('estab-site');
  if (site && String(site.value || '').trim() && !/^https:\/\/[^\s"'<>]+$/i.test(String(site.value).trim())) {
    markEstablishmentFieldError(site, 'Site : une adresse qui commence par https://.');
    invalid.push(site);
  }
  const telephone = document.getElementById('estab-phone');
  if (telephone && !/^[0-9+()./\s-]*$/.test(String(telephone.value || '').trim())) {
    markEstablishmentFieldError(telephone, 'Téléphone : uniquement des chiffres, des espaces et + ( ) . / -.');
    invalid.push(telephone);
  }
  const surMesure = document.getElementById('estab-customRequestFromPax');
  if (surMesure && String(surMesure.value).trim() !== '') {
    const seuil = Number(surMesure.value);
    if (!Number.isInteger(seuil) || seuil < 2 || seuil > 240) {
      markEstablishmentFieldError(surMesure, 'Demande sur mesure : un nombre entier de 2 à 240 joueurs, ou vide pour jamais.');
      invalid.push(surMesure);
    }
  }
  return invalid;
}

// A4 : garde de ré-entrance, un double-clic sur « Enregistrer » ne doit
// produire qu'UN seul POST, bouton désactivé pendant l'async.
let submitCenterConfigInFlight = false;

async function submitCenterConfig(centerId) {
  if (!canUseStaffPermission('settings.manage')) { toast('Édition réservée à la direction.'); return; }
  if (submitCenterConfigInFlight) return;
  const invalidFields = validateEstablishmentForm();
  if (invalidFields.length) {
    focusEstablishmentField(invalidFields[0]);
    toast('Corrigez les champs en erreur avant d’enregistrer.');
    return;
  }
  // Prevu ou archive coupe les reservations en ligne : ca se confirme, comme fermer un jour.
  const statutVoulu = establishmentInputValue('estab-status', 'active');
  const statutAvant = ((staffCenterConfigCache.centers || []).find(item => item && item.id === centerId) || {}).status;
  if (statutVoulu !== statutAvant && statutVoulu !== 'active'
    && !window.confirm(statutVoulu === 'closed' ? 'Archiver ce centre ? Ses réservations en ligne seront coupées.' : 'Passer ce centre en « prévu » ? Ses réservations en ligne seront coupées.')) return;
  const regular = collectEstablishmentScheduleBlock('estab-day');
  const holiday = collectEstablishmentScheduleBlock('estab-hday');
  const activityAvailability = {};
  (staffCenterConfigCache.activities || []).forEach(activity => {
    activityAvailability[activity.id] = !!document.getElementById(`estab-act-${activity.id}`)?.checked;
  });
  // Les installations de chaque activite (tables, pistes, joueurs par piste) :
  // le serveur les applique des l enregistrement, le formulaire en ligne les
  // relit sans rechargement.
  const activityCapacity = {};
  (staffCenterConfigCache.activities || []).forEach(activity => {
    const entree = {};
    const units = Number(document.getElementById(`estab-cap-units-${activity.id}`)?.value);
    const joueurs = Number(document.getElementById(`estab-cap-players-${activity.id}`)?.value);
    if (Number.isInteger(units) && units >= 1) entree.units = Math.min(50, units);
    if (Number.isInteger(joueurs) && joueurs >= 1) entree.capacityPerUnit = Math.min(500, joueurs);
    const plafond = Number(document.getElementById(`estab-cap-max-${activity.id}`)?.value);
    if (Number.isInteger(plafond) && plafond >= 1) entree.maxPerBooking = Math.min(50, plafond);
    if (Object.keys(entree).length) activityCapacity[activity.id] = entree;
  });
  // Panneau « Offres & formules » : map générique offerId -> booléen,
  // appliquée aussi côté serveur (une formule décochée n'est plus réservable).
  // Collecte depuis le DOM : ce qui a été RENDU (liste vive du catalogue,
  // customs comprises) est exactement ce qui s'enregistre. Itérer une
  // constante ici perdait le réglage de toute formule qu'elle ignorait.
  const offerAvailability = {};
  document.querySelectorAll('input[data-estab-offer]').forEach(input => {
    offerAvailability[input.getAttribute('data-estab-offer')] = !!input.checked;
  });
  const formulaBlockedPeriods = ['manual'];
  if (document.getElementById('estab-fbp-public')?.checked) formulaBlockedPeriods.push('public');
  if (document.getElementById('estab-fbp-short')?.checked) formulaBlockedPeriods.push('school_short');
  if (document.getElementById('estab-fbp-summer')?.checked) formulaBlockedPeriods.push('school_summer');
  // Classification client/groupe éditée par le staff (seuils + formules annif).
  // Meme collecte DOM que les offres : ce qui a ete rendu est ce qui s'enregistre.
  const birthdayFormulaIds = [...document.querySelectorAll('input[data-estab-bday]')]
    .filter(input => input.checked)
    .map(input => input.getAttribute('data-estab-bday'));
  // « Paliers de taille » n a plus d ecran : son seul lecteur etait la page
  // Groupes, supprimee le 2026-07-13. La valeur deja enregistree repart telle
  // quelle : enregistrer l Etablissement ne la remplace pas par les defauts.
  const storedCenter = (staffCenterConfigCache.centers || []).find(item => item && item.id === centerId) || {};
  const storedSizeTiers = storedCenter.classification && storedCenter.classification.sizeTiers && typeof storedCenter.classification.sizeTiers === 'object'
    ? storedCenter.classification.sizeTiers
    : null;
  const classification = {
    groupMinPax: Number(establishmentInputValue('estab-groupMinPax', 10)),
    groupMinCumulative: Number(establishmentInputValue('estab-groupMinCumulative', 18)),
    countFormulaAsGroup: !!document.getElementById('estab-countFormulaAsGroup')?.checked,
    ...(storedSizeTiers ? { sizeTiers: storedSizeTiers } : {}),
    birthdayFromFormula: !!document.getElementById('estab-birthdayFromFormula')?.checked,
    birthdayFormulaIds,
    keyClientMinSpend: Number(establishmentInputValue('estab-keyClientMinSpend', 0)) || 0,
  };
  const chk = (id) => !!document.getElementById(id)?.checked;
  const config = {
    status: establishmentInputValue('estab-status', 'active'),
    timezone: establishmentInputValue('estab-timezone', 'Europe/Brussels'),
    resources: {
      bowling: {
        laneCount: Number(establishmentInputValue('estab-laneCount', 8)),
        normalCapacityPerLane: Number(establishmentInputValue('estab-normalCap', 6)),
        emergencyCapacityPerLane: Number(establishmentInputValue('estab-emergencyCap', 7)),
        preferAdjacentLanes: chk('estab-preferAdjacent')
      },
      laser: {
        weaponCount: Number(establishmentInputValue('estab-weaponCount', 30)),
        parallelLaunches: Number(establishmentInputValue('estab-launches', 1)),
        riskLevel: establishmentInputValue('estab-laserRisk', 'managed'),
        requiresCompleteGroupBeforeLaunch: chk('estab-requiresComplete'),
        canSplitGroupsCleanly: chk('estab-canSplit')
      },
      partyTables: {
        softCapacity: Number(establishmentInputValue('estab-tableSoft', 6)),
        hardCapacity: Number(establishmentInputValue('estab-tableHard', 8)),
        limitEnabled: chk('estab-tableLimit')
      },
      declared: establishmentDeclaredResourcesDraft.map(item => ({
        id: item.id,
        name: item.name,
        units: item.units,
        capacityPerUnit: item.capacityPerUnit,
        cleanupMinutes: item.cleanupMinutes,
        allowGroupMixing: item.allowGroupMixing
      })),
      barDesk: {
        handlesBooking: chk('estab-bar-booking'),
        handlesBriefing: chk('estab-bar-briefing'),
        handlesFoodAndDrink: chk('estab-bar-food'),
        activityEscort: chk('estab-bar-escort')
      }
    },
    defaultSchedule: { regular, holiday },
    holidaySettings: {
      enabled: !!document.getElementById('estab-holiday-enabled')?.checked,
      overrides: establishmentHolidayOverridesDraft.map(item => ({ date: item.date, mode: item.mode })),
      formulaBlockedPeriods
    },
    offerAvailability,
    activityAvailability,
    activityCapacity,
    activityOffers: collectEstablishmentArcadeOffers(storedCenter),
    // Vide = jamais (null, qui prime sur le reglage du fichier socle).
    customRequest: (() => {
      const brut = document.getElementById('estab-customRequestFromPax')?.value;
      const seuil = Math.trunc(Number(brut));
      return { fromPax: String(brut || '').trim() !== '' && Number.isFinite(seuil) && seuil >= 2 ? Math.min(240, seuil) : null };
    })(),
    classification,
    accueil: { lateThresholdMinutes: Number(establishmentInputValue('estab-lateThreshold', STAFF_LATE_THRESHOLD_DEFAUT)) },
    bookingRules: { minDaysAhead: Number(establishmentInputValue('estab-book-min', 0)) || 0, horizonDays: establishmentInputValue('estab-book-horizon', '') === '' ? null : Number(establishmentInputValue('estab-book-horizon', '')) },
    customActivities: establishmentCustomActivitiesDraft.map(item => ({ id: item.id, label: item.label }))
  };
  // Les coordonnees que lisent les clients : une case videe efface la valeur du fichier socle.
  if (document.getElementById('estab-address')) {
    config.publicInfo = {
      address: establishmentInputValue('estab-address').trim(),
      phone: establishmentInputValue('estab-phone').trim(),
      parking: establishmentInputValue('estab-parking').trim(),
    };
  }
  // Le logo et le site : seules ces cles partent, les liens du site (siteLinks) restent ceux du centre.
  if (document.getElementById('estab-logo')) {
    config.identity = {
      logoUrl: establishmentInputValue('estab-logo').trim(),
      logoOnDark: Boolean(document.getElementById('estab-logoDark') && document.getElementById('estab-logoDark').checked),
      siteUrl: establishmentInputValue('estab-site').trim(),
    };
  }
  const validationEquipe = collectEstablishmentValidation();
  if (validationEquipe) config.validationEquipe = validationEquipe;
  const champSecours = document.getElementById('estab-secours-emails');
  if (champSecours) {
    const emails = String(champSecours.value || '').split(/[,;\s]+/).map(x => x.trim()).filter(Boolean);
    // Le serveur ecarte une adresse mal formee sans bruit : on le dit avant,
    // sinon « Configuration enregistrée » cacherait une copie qui ne part pas.
    const malFormee = emails.find(x => !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(x));
    if (malFormee) { toast(`Boîte de secours : « ${malFormee} » n’est pas une adresse e-mail.`); focusEstablishmentField(champSecours); return; }
    if (emails.length > 5) { toast('Boîte de secours : 5 adresses au plus.'); focusEstablishmentField(champSecours); return; }
    config.secours = { emails };
  }
  // La marque du centre voyage avec le reste de sa config. `undefined` = champ
  // absent ou saisie refusée : on ne l'ajoute pas au payload, donc le serveur
  // conserve la couleur existante au lieu de l'effacer.
  const branding = collectEstablishmentBranding();
  // Validate the local suggestion draft before either centre write starts.
  if (window.PinlaneUpsellSettings) {
    try { config.upsellOffers = window.PinlaneUpsellSettings.collect(storedCenter); }
    catch (error) { toast(error.message || 'Suggestions invalides.'); return; }
  }
  if (branding !== undefined) config.branding = branding;
  const payment = collectEstablishmentPayment();
  if (payment !== undefined) config.payment = payment;
  const name = establishmentInputValue('estab-name').trim();
  submitCenterConfigInFlight = true;
  const saveBtn = document.getElementById('estabSaveBtn');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Enregistrement…'; }
  try {
    if (name) {
      await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'saveCenter', center: { id: centerId, name, status: config.status } }) });
    }
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'saveCenterConfig', centerId, config }) });
    toast('Configuration du centre enregistrée.');
    state.establishmentEditing = false;
    // Ce qui est a l ecran est ce qui vient d etre enregistre. Sans cette photo, le comptage differe
    // du clic (40 ms) recompte contre l ancienne et remet la fiche en cours, et une fiche en cours
    // refuse de se repeindre : elle restait en modification pour de bon.
    ebSnap = ebState();
    establishmentHolidayOverridesDraft = [];
    await loadStaffCenterConfig(true);
    // Le catalogue de la console (tables, pistes, activites proposees) se
    // relit tout de suite : la prochaine reservation compte avec lui.
    if (typeof loadCenterScheduleConfig === 'function') loadCenterScheduleConfig();
  } catch (error) {
    toast(error?.message || 'Enregistrement impossible.');
  } finally {
    submitCenterConfigInFlight = false;
    // Re-query : la page a pu être re-rendue (succès) ou pas (échec réseau).
    const btn = document.getElementById('estabSaveBtn');
    if (btn) { btn.disabled = false; btn.textContent = 'Enregistrer'; }
  }
}

async function submitNewCenter() {
  if (!canUseStaffPermission('settings.manage')) { toast('Ajout réservé à la direction.'); return; }
  const id = establishmentInputValue('estab-new-id').trim().toLowerCase();
  const name = establishmentInputValue('estab-new-name').trim();
  if (!id || !name) { toast('Identifiant et nom requis.'); return; }
  try {
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'saveCenter', center: { id, name, status: 'planned' } }) });
    toast(`Centre « ${name} » ajouté, en prévu. Choisissez-le pour le régler.`);
    await loadStaffCenterConfig(true);
  } catch (error) {
    toast(error?.message || 'Ajout impossible.');
  }
}

// ── LA COULEUR DU TUNNEL, SAISIE ICI ────────────────────────────────────────
//
// Le tunnel public d'un centre porte SA marque depuis que le magenta Fun Galaxy
// a quitté assets/pinlane-client.css. Cette couleur était une donnée de centre
// que seul un appel d'API savait poser : elle se saisit désormais dans l'écran
// qui configure le centre, comme le reste.
//
// UNE couleur, pas huit : assets/brand-color.js dérive le jeu complet de jetons
// (clair + sombre) et l'envoie DÉCLARÉ dans la config. Il MESURE aussi le
// contraste réel contre les fonds où la couleur sert, et l'interface le dit.
// Elle avertit, elle ne bloque pas : la marque appartient au client.
function establishmentBrandApi() {
  return (typeof window !== 'undefined' && window.PinlaneBrand) ? window.PinlaneBrand : null;
}

function establishmentBrandPalette() {
  const api = establishmentBrandApi();
  if (!api) return null;
  try { return api.readPlatformPalette(document); } catch (error) { return null; }
}

function establishmentAccentNoteHtml(raw) {
  const api = establishmentBrandApi();
  const value = String(raw == null ? '' : raw).trim();
  if (!value) return '<span class="estab-brand-note">Aucune couleur : le tunnel de ce centre garde l’accent Pinlane.</span>';
  if (!api || !api.isValidHex(value)) {
    return '<span class="estab-brand-note is-bad">Code couleur invalide : attendu un hexadécimal, par exemple #1f6f43.</span>';
  }
  const palette = establishmentBrandPalette();
  const notice = api.contrastNotice(api.deriveBranding(value, palette), palette);
  if (!notice) return '<span class="estab-brand-note"></span>';
  return `<span class="estab-brand-note ${notice.tone === 'warn' ? 'is-warn' : 'is-ok'}">${escapeHtml(notice.text)}</span>`;
}

// Les axes de style saisissables, avec leurs libelles metier. Le premier choix
// de chaque axe est le DEFAUT plateforme : le choisir n'ecrit rien en config.
const ESTABLISHMENT_STYLE_AXES = [
  { key: 'theme', label: 'Thème du tunnel', options: [['auto', 'Suit l’appareil du client'], ['light', 'Toujours clair'], ['dark', 'Toujours sombre']] },
  { key: 'radius', label: 'Angles', options: [['soft', 'Doux (défaut)'], ['sharp', 'Carrés'], ['round', 'Très arrondis']] },
  { key: 'font', label: 'Police', options: [['geist', 'Geist (défaut)'], ['humanist', 'Humaniste'], ['serif', 'Serif'], ['mono', 'Monospace']] },
  { key: 'backdrop', label: 'Fond de page', options: [['plain', 'Neutre (défaut)'], ['tint', 'Teinté à votre couleur'], ['aurora', 'Halo à votre couleur']] },
  { key: 'cards', label: 'Panneaux', options: [['line', 'Bordure fine (défaut)'], ['flat', 'Aplat sans bordure'], ['shadow', 'Ombre douce'], ['neon', 'Néon (anneau + halo, suit votre 2ᵉ couleur)']] },
  { key: 'buttons', label: 'Boutons', options: [['pill', 'Pilule (défaut)'], ['rounded', 'Rectangle arrondi'], ['neon', 'Pilule néon (contour + halo)']] },
];

function establishmentAccentFieldHtml(center) {
  const api = establishmentBrandApi();
  const branding = (center && center.branding && typeof center.branding === 'object') ? center.branding : {};
  const accent = branding.accent ? String(branding.accent) : '';
  const swatch = (api && api.isValidHex(accent)) ? api.normalizeHex(accent) : '';
  const axisFields = ESTABLISHMENT_STYLE_AXES.map((axis) => {
    const current = String(branding[axis.key] || '').trim().toLowerCase();
    const options = axis.options.map(([value, label], index) => {
      const selected = current === value || (!axis.options.some(([v]) => v === current) && index === 0);
      return `<option value="${escapeHtml(value)}" ${selected ? 'selected' : ''}>${escapeHtml(label)}</option>`;
    }).join('');
    return `<div class="field estab-style-field">
      <label for="estab-style-${escapeHtml(axis.key)}">${escapeHtml(axis.label)}</label>
      <select id="estab-style-${escapeHtml(axis.key)}" class="estab-style-select">${options}</select>
    </div>`;
  }).join('');
  return `<div class="field estab-brand-field">
    <label for="estab-accent">Couleur du tunnel client</label>
    <div class="estab-brand-pick">
      <input type="color" id="estab-accent-picker" aria-label="Choisir la couleur du tunnel"
        value="${escapeHtml(swatch || '#000000')}" ${swatch ? '' : 'data-unset="1"'}
        oninput="setEstablishmentAccent(this.value, 'picker')">
      <input type="text" id="estab-accent" spellcheck="false" autocomplete="off"
        placeholder="#1f6f43 (facultatif)" value="${escapeHtml(accent)}"
        aria-describedby="estab-brand-note" oninput="setEstablishmentAccent(this.value, 'text')">
      <button type="button" class="btn btn-ghost btn-sm" onclick="setEstablishmentAccent('', 'clear')">Retirer</button>
    </div>
    <span id="estab-brand-note">${establishmentAccentNoteHtml(accent)}</span>
    <div class="estab-style-grid">${axisFields}</div>
    <span class="estab-brand-note">Ces réglages habillent le tunnel de réservation public de ce centre : couleurs, thème, angles, police, fond, panneaux et boutons.</span>
  </div>`;
}

// LE MODE D'ENCAISSEMENT DU CENTRE. Un seul mode est activable aujourd'hui :
// « tout se règle sur place », parce que c'est le seul que le produit tient
// (aucun prestataire de paiement dans le dépôt). Les modes en ligne sont
// AFFICHÉS mais désactivés : le gérant voit où ça se règlera le jour où
// l'encaissement existe, sans qu'on lui vende une option fantôme (classe
// d'écart commercial payée le 2026-08-08).
// L INTERRUPTEUR DU FORMULAIRE INSTALLE SUR LE SITE DU CLIENT.
//
// Il vit ici, dans la fiche du centre, et pas dans un menu de reglages avances :
// c est une sortie de secours, elle doit se trouver sans la chercher.
//
// Il agit TOUT DE SUITE, sans passer par « Enregistrer » : le jour ou on s en
// sert, on ne veut pas d une deuxieme etape entre la decision et l effet. Et il
// dit ce qu il fait AVANT qu on clique, avec le nom du site concerne, parce
// qu il change ce que voient les visiteurs d un autre site que celui-ci.
//
// LA QUESTION SE POSE DANS LE BLOC (13/11) : la fenetre « OK » du navigateur se
// ratait, le premier clic d Ansar n avait rien envoye (journal 553). Elle vit
// dans un etat, pour tenir a travers les repeints de la page, et ne vaut que
// pour le centre ou elle a ete posee.
let embedQuestion = null; // { centerId, actif } tant que la question attend sa reponse
let embedEnCours = false;
let embedDernierCentre = null;

function establishmentEmbedFieldHtml(center) {
  embedDernierCentre = center || null;
  const reglage = (center && center.embed) || {};
  const actif = reglage.actif !== false;
  const quand = reglage.bascule ? new Date(reglage.bascule) : null;
  const trace = !actif && quand
    ? `Coupé le ${quand.toLocaleDateString('fr-BE')} à ${quand.toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit' })}${reglage.basculePar ? ` par ${escapeHtml(reglage.basculePar)}` : ''}.`
    : '';
  const question = embedQuestion && center && embedQuestion.centerId === center.id ? embedQuestion : null;
  const geste = question
    ? establishmentEmbedQuestionHtml(question.actif)
    : `<button type="button" class="estab-embed-bouton" ${embedEnCours ? 'disabled' : ''} onclick="demanderBasculeFormulaire(${actif ? 'false' : 'true'})">
      ${embedEnCours ? 'Un instant…' : (actif ? 'Rendre l’ancien formulaire du site' : 'Remettre le formulaire Pinlane')}
    </button>`;
  return `<div class="field estab-brand-field" id="estab-embed-champ">
    <label>Formulaire sur le site du client</label>
    <div class="estab-embed-etat estab-embed-${actif ? 'on' : 'off'}">
      <strong>${actif ? 'Le formulaire Pinlane est en ligne' : 'Le formulaire d’origine du site est rendu'}</strong>
      <span>${actif
        ? 'Les visiteurs du site réservent par Pinlane. Leur ancien formulaire est toujours dans la page, masqué.'
        : `Les visiteurs réservent par l’ancien formulaire du site. ${trace}`}</span>
    </div>
    ${geste}
    <span class="estab-brand-note">Agit immédiatement, sans passer par Enregistrer. Rien n’est touché sur leur site : leur formulaire d’origine y reste en permanence, ce réglage décide seulement lequel des deux s’affiche.</span>
  </div>`;
}

// Rendre l ancien formulaire coupe la reservation en ligne : pied rouge pale et
// bouton rouge, le focus sur « Retour ». Remettre Pinlane : bouton bleu, le focus dessus.
function establishmentEmbedQuestionHtml(actif) {
  const texte = actif
    ? 'Le formulaire Pinlane reprend la place de l’ancien sur le site, en une minute.'
    : 'En une minute, l’ancien formulaire revient sur le site. Les visiteurs ne réserveront plus par Pinlane tant qu’il n’est pas remis.';
  return `<div class="estab-embed-question${actif ? '' : ' est-risque'}" role="group" aria-labelledby="estab-embed-question-texte" onkeydown="if (event.key === 'Escape') annulerBasculeFormulaire()">
      <p id="estab-embed-question-texte">${texte}</p>
      <div class="estab-embed-question-boutons">
        <button type="button" class="estab-embed-geste est-contour" data-embed-retour onclick="annulerBasculeFormulaire()">Retour</button>
        <button type="button" class="estab-embed-geste ${actif ? 'est-plein' : 'est-danger'}" data-embed-confirmer onclick="basculerFormulaireDuSite(${actif ? 'true' : 'false'})">${actif ? 'Remettre le formulaire Pinlane' : 'Rendre l’ancien formulaire'}</button>
      </div>
    </div>`;
}

function repeindreChampEmbed(focus) {
  const champ = document.getElementById('estab-embed-champ');
  if (!champ || !embedDernierCentre) return;
  champ.outerHTML = establishmentEmbedFieldHtml(embedDernierCentre);
  const cible = focus ? document.querySelector(focus) : null;
  if (cible) cible.focus();
}

function demanderBasculeFormulaire(actif) {
  embedQuestion = { centerId: getCurrentStaffCenterId(), actif: Boolean(actif) };
  repeindreChampEmbed(actif ? '[data-embed-confirmer]' : '[data-embed-retour]');
}

function annulerBasculeFormulaire() {
  embedQuestion = null;
  repeindreChampEmbed('#estab-embed-champ .estab-embed-bouton');
}

async function basculerFormulaireDuSite(actif) {
  if (embedEnCours) return;
  const centerId = getActiveOpsCenterId();
  embedQuestion = null;
  embedEnCours = true;
  repeindreChampEmbed();
  try {
    await apiRequest(API_ENDPOINTS.ops, {
      method: 'POST',
      body: JSON.stringify({ action: 'setEmbedState', centerId, actif: Boolean(actif) }),
    });
    toast(actif ? 'Formulaire Pinlane remis en ligne.' : 'Ancien formulaire du site rendu.');
  } catch (error) {
    toast(error?.message || 'Bascule impossible.');
  }
  embedEnCours = false;
  await loadStaffCenterConfig(true);
  repeindreChampEmbed();
}

function establishmentPaymentFieldHtml(center) {
  const mode = String(center && center.payment && center.payment.mode || 'onsite');
  return `<div class="field estab-brand-field">
    <label for="estab-payment-mode">Encaissement des réservations</label>
    <select id="estab-payment-mode" class="estab-style-select">
      <option value="onsite" ${mode === 'onsite' ? 'selected' : ''}>Tout se règle sur place (au comptoir)</option>
      <option value="deposit" disabled>Acompte en ligne : à venir avec l'encaissement</option>
      <option value="online" disabled>Paiement en ligne : à venir avec l'encaissement</option>
    </select>
    <span class="estab-brand-note">Le tunnel de réservation annonce ce mode au client. Les paiements en ligne s'activeront ici dès que l'encaissement Pinlane sera branché.</span>
  </div>`;
}

function collectEstablishmentPayment() {
  const select = document.getElementById('estab-payment-mode');
  if (!select) return undefined;
  const mode = String(select.value || '').trim().toLowerCase();
  return mode === 'onsite' ? { mode } : undefined;
}

// Les deux contrôles portent LA MÊME valeur ; seul celui qui n'a pas la frappe
// est resynchronisé, sinon le curseur sauterait à chaque caractère.
function setEstablishmentAccent(value, source) {
  const api = establishmentBrandApi();
  const raw = String(value == null ? '' : value).trim();
  const text = document.getElementById('estab-accent');
  const picker = document.getElementById('estab-accent-picker');
  const note = document.getElementById('estab-brand-note');
  if (text && source !== 'text') text.value = raw;
  if (picker && source !== 'picker') {
    if (api && api.isValidHex(raw)) { picker.value = api.normalizeHex(raw); picker.removeAttribute('data-unset'); }
    else picker.setAttribute('data-unset', '1');
  }
  if (picker && source === 'picker') picker.removeAttribute('data-unset');
  if (note) note.innerHTML = establishmentAccentNoteHtml(raw);
}

// Ce qui part au serveur. Champ vide = `null` : mergeCenterConfig remplace la
// valeur, donc EFFACER la couleur est possible et le tunnel revient à l'accent
// plateforme. Champ absent du DOM (panneau jamais rendu) = `undefined` : on ne
// touche à rien plutôt que d'effacer une marque par accident.
function collectEstablishmentStyle() {
  const out = {};
  ESTABLISHMENT_STYLE_AXES.forEach((axis) => {
    const select = document.getElementById(`estab-style-${axis.key}`);
    if (!select) return;
    const value = String(select.value || '').trim().toLowerCase();
    // Le premier choix de l'axe est le defaut plateforme : on n'ecrit QUE les
    // ecarts, la config d'un centre au defaut reste vide.
    if (value && value !== axis.options[0][0]) out[axis.key] = value;
  });
  return out;
}

function collectEstablishmentBranding() {
  const input = document.getElementById('estab-accent');
  if (!input) return undefined;
  const api = establishmentBrandApi();
  const raw = String(input.value || '').trim();
  const style = collectEstablishmentStyle();
  const hasStyle = Object.keys(style).length > 0;
  if (!raw) return hasStyle ? style : null;
  if (!api || !api.isValidHex(raw)) return hasStyle ? style : undefined;
  const colors = api.deriveBranding(raw, establishmentBrandPalette());
  return { ...(colors || {}), ...style };
}

// LA PAGE SECOURS (2026-10-05). Movsar : « si Pinlane crash il faut qu on ait
// acces par mail ou par fichier rempli », « des papiers imprimables exactement
// comme ca ». La page dit ce qui est VRAI (adresses, derniers envois, derniere
// sauvegarde, lus sur le serveur), donne la feuille du jour, la feuille vierge
// et l Excel a imprimer, et la marche a suivre si Pinlane ne repond plus. Rien
// d invente : un envoi jamais fait se dit « jamais », une sauvegarde non
// configuree se dit non configuree.
let secoursEtatCache = { loaded: false, loading: false, error: '', data: null, centerId: '' };
async function loadSecoursEtat(force = false) {
  const centerId = getCurrentStaffCenterId();
  if (secoursEtatCache.loading) return;
  if (secoursEtatCache.loaded && !force && secoursEtatCache.centerId === centerId) return;
  secoursEtatCache = { ...secoursEtatCache, loading: true, error: '' };
  try {
    const data = await apiRequest(`${API_ENDPOINTS.ops}?action=secoursEtat&centerId=${encodeURIComponent(centerId)}`);
    secoursEtatCache = { loaded: true, loading: false, error: '', data, centerId };
  } catch (error) {
    secoursEtatCache = { loaded: true, loading: false, error: error?.message || 'Lecture impossible.', data: null, centerId };
  }
  if (state.view === 'staff' && getStaffMenuPage() === 'secours') renderStaffUtilityPage();
}
function secoursQuand(iso) {
  if (!iso) return 'jamais';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return 'jamais';
  return d.toLocaleString('fr-BE', { timeZone: 'Europe/Brussels', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
}
// Le fichier arrive par la meme session que le reste de la console, puis
// s enregistre sous son vrai nom.
async function telechargerSecours(kind) {
  const champ = document.getElementById('secours-date');
  const date = (champ && champ.value) || state.currentDate || todayStr();
  const centerId = getCurrentStaffCenterId();
  const action = kind === 'tout' ? 'exportComplet' : kind === 'excel' ? 'classeurJour' : 'feuilleSecours';
  const vierge = kind === 'vierge' ? '&vierge=1' : '';
  const bouton = document.querySelector(`[data-secours-dl="${kind}"]`);
  if (bouton) { bouton.disabled = true; bouton.classList.add('is-busy'); }
  try {
    const response = await fetch(`${API_ENDPOINTS.ops}?action=${action}&centerId=${encodeURIComponent(centerId)}&date=${encodeURIComponent(date)}${vierge}`, { headers: staffAuthHeaders({}), credentials: 'include' });
    if (!response.ok) {
      const corps = await response.json().catch(() => ({}));
      throw new Error(corps.message || corps.error || `Erreur ${response.status}`);
    }
    const blob = await response.blob();
    const nom = (/filename="([^"]+)"/.exec(response.headers.get('content-disposition') || '') || [])[1]
      || `${kind === 'excel' ? 'reservations' : 'feuille'}-${centerId}-${date}.${kind === 'excel' ? 'xlsx' : 'pdf'}`;
    const lien = document.createElement('a');
    lien.href = URL.createObjectURL(blob);
    lien.download = nom;
    document.body.appendChild(lien);
    lien.click();
    setTimeout(() => { URL.revokeObjectURL(lien.href); lien.remove(); }, 1000);
  } catch (error) {
    toast(`Téléchargement impossible : ${error.message || 'erreur'}`);
  } finally {
    if (bouton) { bouton.disabled = false; bouton.classList.remove('is-busy'); }
  }
}
function renderStaffUtilitySecours() {
  if (!secoursEtatCache.loaded || secoursEtatCache.centerId !== getCurrentStaffCenterId()) {
    if (!secoursEtatCache.loading) setTimeout(() => loadSecoursEtat(true), 0);
  }
  const d = secoursEtatCache.data || {};
  const emails = Array.isArray(d.emails) ? d.emails : [];
  const envois = d.envois || {};
  const sauvegarde = d.sauvegarde || {};
  const jour = state.currentDate || todayStr();
  const etat = (ok, mot) => `<span class="sec-etat ${ok ? 'is-ok' : 'is-off'}">${escapeHtml(mot)}</span>`;
  const ligne = (label, valeur, sous = '') => `<div class="sec-ligne"><span>${escapeHtml(label)}${sous ? `<small>${escapeHtml(sous)}</small>` : ''}</span><b>${valeur}</b></div>`;
  const erreur = secoursEtatCache.error ? `<p class="sec-erreur">${escapeHtml(secoursEtatCache.error)} <button type="button" class="btn btn-secondary btn-sm" onclick="loadSecoursEtat(true)">Réessayer</button></p>` : '';
  return `<div class="secours-page">
    ${erreur}
    <section class="sec-carte sec-imprimer">
      <div class="sec-tete"><h3>Imprimer</h3><p>La feuille papier de la journée, déjà remplie comme vos feuilles : une croix par piste, une par partie de laser, le détail de chaque réservation en annexe.</p></div>
      <div class="sec-imprimer-ligne">
        <label class="sec-date"><span>Journée</span><input type="date" id="secours-date" value="${escapeHtml(jour)}"></label>
        <div class="sec-boutons">
          <button type="button" class="btn btn-primary" data-secours-dl="feuille" onclick="telechargerSecours('feuille')">Feuille du jour (PDF)</button>
          ${canUseStaffPermission('payments.view') ? '<button type="button" class="btn btn-secondary" data-secours-dl="excel" onclick="telechargerSecours(\'excel\')">Excel du jour</button>' : ''}
          <button type="button" class="btn btn-secondary" data-secours-dl="vierge" onclick="telechargerSecours('vierge')">Feuille vierge</button>
          ${canUseStaffPermission('exports.download') && canUseStaffPermission('payments.view') ? '<button type="button" class="btn btn-secondary" data-secours-dl="tout" onclick="telechargerSecours(\'tout\')" title="Toute la base du centre, lue à la seconde">Tout exporter</button>' : ''}
        </div>
      </div>
    </section>
    <div class="sec-grille">
      <section class="sec-carte">
        <div class="sec-tete"><h3>Boîte de secours</h3>${etat(emails.length > 0, emails.length ? 'En place' : 'Aucune adresse')}</div>
        ${emails.length
          ? `<div class="sec-adresses">${emails.map(e => `<span class="estab-tag">${escapeHtml(e)}</span>`).join('')}</div>`
          : `<p class="sec-vide">Rien ne part encore en dehors de Pinlane.${canUseStaffPermission('settings.manage') ? '' : ' La direction peut ajouter une adresse dans Établissement.'}</p>${canUseStaffPermission('settings.manage') ? '<button type="button" class="btn btn-secondary" data-secours-ajouter onclick="ouvrirReglageSecours()">Ajouter une adresse</button>' : ''}`}
        <div class="sec-lignes">
          ${ligne('Copie de chaque réservation', emails.length ? 'à chaque création' : 'pas d’adresse')}
          ${ligne('Feuille du jour', envois.derniere ? escapeHtml(secoursQuand(envois.derniere)) : 'jamais', '8 h, 13 h, 17 h et à chaque changement')}
          ${ligne('Classeur du soir', envois.soir ? escapeHtml(secoursQuand(envois.soir)) : 'jamais', 'après 23 h 30, avec la feuille de demain')}
        </div>
      </section>
      <section class="sec-carte">
        <div class="sec-tete"><h3>Sauvegarde de la nuit</h3>${etat(Boolean(sauvegarde.configuree) && sauvegarde.statut === 'ok', !sauvegarde.configuree ? 'Pas configurée' : sauvegarde.statut === 'ok' ? 'Faite' : sauvegarde.statut === 'failed' ? 'Échouée' : 'Pas encore faite')}</div>
        <p class="sec-vide">Toute la base, chiffrée, envoyée chaque nuit vers une boîte à part. Elle se relit en Excel ou se remet en place avec le script de restauration.</p>
        <div class="sec-lignes">
          ${ligne('Dernier passage', escapeHtml(secoursQuand(sauvegarde.le)))}
          ${sauvegarde.detail ? ligne('Contenu', escapeHtml(sauvegarde.detail)) : ''}
        </div>
      </section>
    </div>
    <section class="sec-carte sec-consignes">
      <div class="sec-tete"><h3>Si Pinlane ne répond plus</h3><p>À afficher à l’accueil.</p></div>
      <ol>
        <li><b>Ouvrez le dernier mail « [Secours] Feuille du … »</b><span>Il est dans la boîte de secours. La feuille PDF jointe est la journée telle qu’elle était à l’heure du mail : imprimez-la.</span></li>
        <li><b>Accueillez sur papier</b><span>Cochez les arrivées, notez chaque nouvelle réservation ou chaque changement sur la feuille, avec l’heure.</span></li>
        <li><b>Les demandes du site ne se perdent pas</b><span>Chaque réservation et chaque demande sur mesure a aussi sa copie complète dans la boîte de secours.</span></li>
        <li><b>Au retour de Pinlane</b><span>Saisissez ce qui a été noté sur papier, puis vérifiez la journée dans le planning avant de jeter la feuille.</span></li>
      </ol>
    </section>
  </div>`;
}

// ── LA PAGE DU CENTRE (2026-11-10) ───────────────────────────────────────────
//
// Ansar, devant la page « salles » en ligne : « pas assez complet », « ça fait site vitrine », réglages cachés, place
// perdue, mots pas clairs. Il a choisi un logiciel pro : les rubriques à gauche, tous les champs de la rubrique à
// droite, chacun avec ce qu il change en une ligne. Une rubrique s affiche à la fois ; les autres restent dans la page
// (attribut hidden) parce que submitCenterConfig lit chaque champ par son id. Rien n est re-rendu quand on change
// quelque chose (le rendu relirait la config du serveur et effacerait la saisie) ; la barre du bas dit ce qui change et
// la rubrique qui attend un enregistrement porte un point.
const EB_RUBRIQUES = [
  ['centre', 'Le centre', 'Son nom, son état et ce que les clients lisent.'],
  ['horaires', 'Horaires', 'Quand les clients peuvent réserver, et les jours qui font exception.'],
  ['activites', 'Activités', 'Ce que le centre propose, et ce que le planning sait de chaque activité.'],
  ['formules', 'Formules', 'Ce que le client peut choisir sur le formulaire.'],
  ['reservations', 'Réservations', 'Quand un client peut réserver en ligne, comment la console classe les réservations, et ce que l’équipe valide.'],
  ['accueil', 'Accueil et secours', 'Quand un groupe passe en retard, et où part une copie de chaque réservation si Pinlane ne répond plus.'],
  ['formulaire', 'Formulaire en ligne', 'Le lien de réservation, son apparence et l’encaissement.'],
];
// Les pages d avant parlaient d onglets ou de cases : ils menent a la bonne rubrique.
const EB_ANCIENS_ONGLETS = { offres: 'formules', regles: 'reservations', clients: 'reservations', fiche: 'centre', plus: 'activites', comptoir: 'accueil' };
// Ce que le catalogue range parmi les activites sans que le client les choisisse comme telles : la table, la boisson,
// le credit d arcade. Leur case reste dans la page, cachee, pour repartir telle quelle a l enregistrement.
const EB_PAS_DES_SALLES = ['party_table', 'service_drinks', 'arcade_credit'];
const EB_MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
const EB_MOIS_COURTS = ['Janv', 'Fév', 'Mars', 'Avr', 'Mai', 'Juin', 'Juil', 'Août', 'Sept', 'Oct', 'Nov', 'Déc'];
const EB_JOURS_MINUSCULES = { 1: 'lundi', 2: 'mardi', 3: 'mercredi', 4: 'jeudi', 5: 'vendredi', 6: 'samedi', 0: 'dimanche' };
const EB_ICO_MOINS = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="square" aria-hidden="true"><path d="M5 12h14"/></svg>';
const EB_ICO_PLUS = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="square" aria-hidden="true"><path d="M5 12h14M12 5v14"/></svg>';
let ebSnap = null;
let ebOuverte = 'horaires';
let ebJourChoisi = '';
let ebJourHtml = '';
let ebEnvoiEnCours = false;

function ebE(v) { return escapeHtml(String(v == null ? '' : v)); }
// Une valeur posee dans un onclick : l attribut se decode avant que JavaScript ne la lise.
function ebJs(v) { return ebE(escapeJsString(String(v == null ? '' : v))); }
function ebIso(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
function ebHeure(valeur, fermeture) {
  const v = String(valeur || '');
  if (!v) return '';
  if (v === '24:00' || (fermeture && v === '00:00')) return 'minuit';
  const m = /^(\d{2}):(\d{2})$/.exec(v);
  if (m && Number(m[1]) > 24) return `${String(Number(m[1]) - 24).padStart(2, '0')}:${m[2]}`;
  return v;
}
function ebDateDite(iso) { return new Date(`${iso}T12:00:00`).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' }); }
// Un nombre : il se tape, et les touches moins et plus sont a cote.
function ebNum(id, label, o) {
  const value = o.value === '' || o.value == null ? '' : Number(o.value);
  const decimal = Boolean(o.htmlStep && String(o.htmlStep).includes('.'));
  const chiffres = Math.max(2, String(o.max).length + (decimal ? 3 : 0));
  const attrs = [
    `min="${o.min}"`, `max="${o.max}"`, `value="${ebE(value)}"`,
    o.step ? `data-eb-step="${o.step}"` : '',
    o.htmlStep ? `step="${o.htmlStep}"` : '',
    o.vide ? `data-eb-vide="${ebE(o.vide)}" placeholder="${ebE(o.vide)}"` : '',
    o.start ? `data-eb-start="${o.start}"` : '',
    o.minFrom ? `data-eb-min-from="${o.minFrom}"` : '',
    o.capName ? `data-cap-max="${o.max}" data-cap-name="${ebE(o.capName)}" data-cap-what="${ebE(o.capWhat || '')}"` : '',
  ].filter(Boolean).join(' ');
  return `<span class="eb-n" role="group" aria-label="${ebE(label)}" style="--n:${chiffres}"><button type="button" class="eb-n-b" aria-label="Moins, ${ebE(label)}" onclick="ebStep('${ebJs(id)}',-1)">${EB_ICO_MOINS}</button><input type="number" inputmode="${decimal ? 'decimal' : 'numeric'}" id="${ebE(id)}" class="eb-n-i ${o.cls || ''}" aria-label="${ebE(label)}" ${attrs}><button type="button" class="eb-n-b" aria-label="Plus, ${ebE(label)}" onclick="ebStep('${ebJs(id)}',1)">${EB_ICO_PLUS}</button></span>`;
}
// Une case : carree, pleine quand c est oui, comme sur une fiche papier.
function ebCase(id, titre, o = {}) {
  return `<label class="eb-k${o.cls ? ` ${o.cls}` : ''}"><input type="checkbox" id="${ebE(id)}" ${o.attrs || ''} ${o.on ? 'checked' : ''}><span class="eb-k-b" aria-hidden="true"></span><span class="eb-k-t"><b>${titre}</b>${o.aide ? `<small>${o.aide}</small>` : ''}</span></label>`;
}
// Un choix parmi quelques mots : des touches, le select reste dans la page pour l enregistrement.
function ebSeg(id, label, options, current) {
  return `<div class="eb-seg" role="radiogroup" aria-label="${ebE(label)}" data-eb-seg="${id}">${options.map(([value, text]) => `<button type="button" role="radio" class="eb-seg-btn${value === current ? ' is-on' : ''}" aria-checked="${value === current ? 'true' : 'false'}" data-eb-v="${value}" onclick="ebPick('${id}','${value}')">${ebE(text)}</button>`).join('')}</div><select id="${id}" hidden>${options.map(([value, text]) => `<option value="${value}" ${value === current ? 'selected' : ''}>${ebE(text)}</option>`).join('')}</select>`;
}
function ebMet(nom, controle, cls = '') { return `<div class="eb-met${cls ? ` ${cls}` : ''}"><small>${nom}</small>${controle}</div>`; }
// Les cartes Arcades du centre : au temps (une par joueur) et en credits.
function ebArcadesHtml(center) {
  const offers = center.activityOffers?.arcade_time;
  if (!offers) return '';
  const carte = (mode, o, i) => {
    const base = `estab-arc-${mode}-${i}`;
    const titre = mode === 'time' ? `${ebE(o.minutes)} min` : `${ebE(o.credits)} crédits`;
    const prix = ebMet('Prix (€)', ebNum(`${base}-price`, `Prix de la carte ${mode === 'time' ? `${o.minutes} minutes` : `${o.credits} crédits`}`, { min: 0, max: 10000, value: Number(o.price), step: 1, htmlStep: '0.01' }));
    const reste = mode === 'time'
      ? ebMet('Minutes', ebNum(`${base}-minutes`, 'Minutes à volonté', { min: 1, max: 1440, value: Number(o.minutes), step: 5, htmlStep: 1 }))
      : `${ebMet('Crédits', ebNum(`${base}-credits`, 'Crédits', { min: 0, max: 100000, value: Number(o.credits), step: 5 }))}${ebMet('Offerts', ebNum(`${base}-bonusCredits`, 'Crédits offerts', { min: 0, max: 100000, value: Number(o.bonusCredits), step: 5 }))}`;
    return `<div class="eb-arc" data-arcade-offer="${mode}" data-arcade-id="${ebE(o.id)}" data-arcade-index="${i}"><label class="eb-k eb-k-seule"><input type="checkbox" id="${base}-enabled" ${o.enabled !== false ? 'checked' : ''} aria-label="Proposer la carte ${titre}"><span class="eb-k-b" aria-hidden="true"></span></label><b class="eb-arc-t">${titre}</b>${prix}${reste}</div>`;
  };
  return `${ebCase('estab-arc-enabled', 'Proposer les cartes dans ce centre', { on: offers.enabled !== false })}
    <h4>Au temps, une carte par joueur</h4><div class="eb-arcs">${(offers.timeOffers || []).map((o, i) => carte('time', o, i)).join('')}</div>
    <h4>En crédits, le nombre de cartes se choisit à part</h4><div class="eb-arcs">${(offers.creditOffers || []).map((o, i) => carte('credit', o, i)).join('')}</div>
    <div class="eb-ligne"><label class="eb-ch"><span>Un jeu coûte au moins (crédits)</span><input class="eb-f" id="estab-arc-gameMin" type="number" min="0.01" step="0.01" value="${ebE(offers.creditGameCostMin)}"></label><label class="eb-ch"><span>et au plus</span><input class="eb-f" id="estab-arc-gameMax" type="number" min="0.01" step="0.01" value="${ebE(offers.creditGameCostMax)}"></label></div>
    <div class="eb-ligne"><label class="eb-ch eb-ch-m"><span>Ce que lit le client, cartes au temps</span><input class="eb-f" id="estab-arc-timeDescription" maxlength="1000" value="${ebE(offers.timedDescription)}"></label><label class="eb-ch eb-ch-m"><span>Cartes en crédits</span><input class="eb-f" id="estab-arc-creditDescription" maxlength="1000" value="${ebE(offers.creditDescription)}"></label></div>`;
}

function ebInitDrafts(center) {
  window.PinlaneUpsellSettings?.start(center, establishmentUpsellCatalogue());
  establishmentHolidayOverridesDraft = (center?.holidaySettings?.overrides || [])
    .filter(item => item && item.date && (item.mode === 'holiday' || item.mode === 'normal'))
    .map(item => ({ date: item.date, mode: item.mode }));
  establishmentCustomActivitiesDraft = (Array.isArray(center?.customActivities) ? center.customActivities : [])
    .filter(item => item && item.id && item.label)
    .map(item => ({ id: item.id, label: item.label }));
  establishmentDeclaredResourcesDraft = (Array.isArray(center?.resources?.declared) ? center.resources.declared : [])
    .filter(item => item && item.id && item.name)
    .map(item => ({
      id: item.id, name: item.name,
      units: Math.max(1, Number(item.units) || 1),
      capacityPerUnit: Math.max(1, Number(item.capacityPerUnit) || 1),
      cleanupMinutes: Math.max(0, Number(item.cleanupMinutes) || 0),
      allowGroupMixing: item.allowGroupMixing === true,
    }));
  establishmentValidationDraft = validationReglageDe(center);
}

function ebContexte(center, canEdit) {
  const res = center.resources || {};
  const holidaySettings = center.holidaySettings && typeof center.holidaySettings === 'object'
    ? center.holidaySettings
    : { enabled: true, overrides: [], formulaBlockedPeriods: ['public', 'school_short', 'manual'] };
  return {
    center, canEdit,
    bowling: res.bowling || {}, laser: res.laser || {},
    party: res.partyTables && typeof res.partyTables === 'object' ? res.partyTables : {},
    barDesk: res.barDesk && typeof res.barDesk === 'object' ? res.barDesk : {},
    classification: center.classification && typeof center.classification === 'object' ? center.classification : {},
    holidaySettings,
    bloquees: Array.isArray(holidaySettings.formulaBlockedPeriods) ? holidaySettings.formulaBlockedPeriods : ['public', 'school_short', 'manual'],
    formules: getConsoleFormuleCatalog(),
    activites: staffCenterConfigCache.activities || [],
    retard: Number.isFinite(Number(center.accueil && center.accueil.lateThresholdMinutes)) ? Math.trunc(Number(center.accueil.lateThresholdMinutes)) : STAFF_LATE_THRESHOLD_DEFAUT,
    horaires: center.defaultSchedule && typeof center.defaultSchedule === 'object' ? center.defaultSchedule : {},
  };
}

// ── Le choix du centre ───────────────────────────────────────────────────────
// Le centre de cette page est celui du menu : un geste ici (fermer un jour, couper le formulaire du site) part vers
// lui. Les touches ne montrent que les centres ou cette personne peut aller.
function ebCentresHtml(c) {
  const permis = typeof window.pinlaneCentresPermis === 'function' ? new Set(window.pinlaneCentresPermis()) : null;
  const centres = (staffCenterConfigCache.centers || []).filter(x => x.id === c.center.id || !permis || permis.has(x.id));
  const statuts = { planned: 'prévu', closed: 'archivé' };
  const nomCourt = x => String(x.name).replace(/^Fun Galaxy\s+/i, '');
  if (centres.length < 2) return '';
  if (centres.length > 6) {
    return `<div class="eb-centres"><select class="eb-f eb-centres-liste" aria-label="Choisir le centre" onchange="ebSelectCenter(this.value)">${groupCentersByClient(centres).map(g => `<optgroup label="${ebE(g.clientName || 'Sans client')}">${g.centers.map(x => `<option value="${ebE(x.id)}" ${x.id === c.center.id ? 'selected' : ''}>${ebE(x.name)}${statuts[x.status] ? ` (${statuts[x.status]})` : ''}</option>`).join('')}</optgroup>`).join('')}</select></div>`;
  }
  return `<div class="eb-centres" role="group" aria-label="Choisir le centre">${centres.map(x => `<button type="button" class="eb-cb${x.id === c.center.id ? ' is-on' : ''}" aria-pressed="${x.id === c.center.id}" onclick="ebSelectCenter('${ebJs(x.id)}')">${ebE(nomCourt(x))}${statuts[x.status] ? `<small>${ebE(statuts[x.status])}</small>` : ''}</button>`).join('')}</div>`;
}

// ── Horaires ─────────────────────────────────────────────────────────────────
// Ce que le moteur applique ce jour-la : la grille du centre ; pendant les vacances, le jour normal si la grille de
// vacances ne le dit pas ; sinon la grille d origine. Un centre sans grille (Gembloux suit celle de Libramont) n est
// donc pas montre ferme, et enregistrer ne le ferme pas.
function ebCreneauApplique(horaires, bloc, key) {
  const lire = (b) => {
    if (!b || typeof b !== 'object' || Array.isArray(b) || !(String(key) in b)) return undefined;
    const s = b[String(key)];
    return s && s.open && s.close ? s : null;
  };
  const propre = lire(horaires[bloc]);
  if (propre !== undefined) return propre;
  if (bloc === 'holiday') { const normal = lire(horaires.regular); if (normal !== undefined) return normal; }
  const origine = grilleHistorique(Number(key), bloc === 'holiday');
  const heure = n => `${String(Math.floor(n)).padStart(2, '0')}:${String(Math.round((n % 1) * 60)).padStart(2, '0')}`;
  return origine ? { open: heure(origine.open), close: heure(origine.close) } : null;
}
// Une heure de fermeture telle que le champ la montre : 24:00 et au-dela redeviennent l heure du lendemain.
function ebHeureDuChamp(v) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(v || ''));
  if (!m) return String(v || '');
  const h = Number(m[1]);
  return `${String(h >= 24 ? h - 24 : h).padStart(2, '0')}:${m[2]}`;
}
// Une fermeture plus tot que l ouverture, jusqu a 06:00, est celle du lendemain.
function ebApresMinuit(open, close) {
  const mn = (v) => { const [h, m] = String(v || '').split(':').map(Number); return h * 60 + m; };
  return Boolean(open && close) && mn(close) <= mn(open) && mn(close) <= 360;
}
// Le moteur ecrit la nuit qui deborde au-dela de 24:00 : 01:30 le lendemain devient 25:30.
function ebLendemain(v) {
  const [h, m] = String(v).split(':').map(Number);
  return `${String(h + 24).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}
function ebFermeDit(open, close) {
  if (!close) return '';
  if (close === '00:00') return 'minuit';
  return ebApresMinuit(open, close) ? `${close} le lendemain` : close;
}
function ebJourHoraire(c, prefix, key, label, bloc) {
  const slot = ebCreneauApplique(c.horaires, bloc, key);
  const closed = !slot;
  const close = slot ? ebHeureDuChamp(slot.close) : '22:00';
  const open = (slot && slot.open) || (bloc === 'holiday' ? '10:00' : '14:00');
  return `<div class="eb-d${closed ? ' is-closed' : ''}" role="cell" data-quand="${bloc === 'holiday' ? 'Vacances' : 'Semaine normale'}">
    <label class="eb-d-o"><input type="checkbox" class="eb-dayopen" id="eb-open-${prefix}-${key}" data-eb-for="${prefix}-${key}" ${closed ? '' : 'checked'} aria-label="${ebE(label)}, ouvert"><span class="eb-k-b" aria-hidden="true"></span></label>
    <span class="eb-d-h"><input type="time" class="eb-heure" id="${prefix}-${key}-open" value="${open}" aria-label="${ebE(label)}, ouvre à"><span class="eb-d-a" aria-hidden="true">à</span><input type="time" class="eb-heure" id="${prefix}-${key}-close" value="${close}" aria-label="${ebE(label)}, ferme à"><small class="eb-d-l" data-eb-lendemain="${prefix}-${key}" hidden>le lendemain</small></span>
    <span class="eb-d-f">Fermé</span>
    <input type="checkbox" id="${prefix}-${key}-closed" ${closed ? 'checked' : ''} hidden>
  </div>`;
}
function ebSemaineHtml(c) {
  const lignes = ESTABLISHMENT_DAYS.map(([k, l]) => `<div class="eb-sem-r" role="row"><span class="eb-sem-j" role="rowheader">${ebE(l)}</span>${ebJourHoraire(c, 'estab-day', k, l, 'regular')}${ebJourHoraire(c, 'estab-hday', k, `${l} en vacances`, 'holiday')}</div>`).join('');
  return `<div class="eb-sem" role="table" aria-label="La semaine type"><div class="eb-sem-r eb-sem-tete" role="row"><span role="columnheader">Jour</span><span role="columnheader">Semaine normale</span><span role="columnheader">Vacances et jours fériés</span></div>${lignes}</div><div id="ebSemErreurs" class="eb-sem-err"></div>`;
}
function ebCalendrierHtml() {
  const auj = new Date();
  const lignes = [];
  for (let m = 0; m < 12; m += 1) {
    const d0 = new Date(auj.getFullYear(), auj.getMonth() + m, 1);
    const decal = (d0.getDay() + 6) % 7;
    const nb = new Date(d0.getFullYear(), d0.getMonth() + 1, 0).getDate();
    let cases = '';
    for (let j = 0; j < decal; j += 1) cases += '<span class="eb-v"></span>';
    for (let j = 1; j <= nb; j += 1) {
      const iso = ebIso(new Date(d0.getFullYear(), d0.getMonth(), j));
      cases += `<button type="button" class="eb-j" data-iso="${iso}" onclick="ebChoisirJour('${iso}')" aria-label="${j} ${EB_MOIS[d0.getMonth()]} ${d0.getFullYear()}">${j}</button>`;
    }
    lignes.push(`<div class="eb-mois" style="--i:${m}"><b>${EB_MOIS_COURTS[d0.getMonth()]}${d0.getMonth() === 0 || m === 0 ? `<small>${d0.getFullYear()}</small>` : ''}</b><div class="eb-cs">${cases}</div></div>`);
  }
  const lettres = 'LMMJVSD'.repeat(6).slice(0, 37).split('').map(x => `<i>${x}</i>`).join('');
  return `<div class="eb-cal"><div class="eb-an"><div class="eb-leg"><span class="k-n">Ouvert</span><span class="k-v">Vacances scolaires</span><span class="k-f">Jour férié</span><span class="k-x">Fermé chaque semaine</span><span class="k-b">Fermeture décidée</span><span class="k-p">Fermé une partie du jour</span><span class="k-a">Piste ou activité fermée</span></div><div class="eb-ent" aria-hidden="true"><b></b><div>${lettres}</div></div>${lignes.join('')}</div><aside class="eb-jour" id="ebJour" aria-live="polite" aria-label="Le jour choisi"></aside></div>`;
}
function ebVacancesHtml(c) {
  return `${ebCase('estab-holiday-enabled', 'Passer tout seul aux horaires de vacances', { on: c.holidaySettings.enabled !== false, aide: 'Pendant les congés scolaires et les jours fériés, la colonne « Vacances » de la semaine s’applique.' })}
    <div class="eb-sous-t">Les formules marquées « pas en vacances »</div>
    ${ebCase('estab-fbp-public', 'Bloquées les jours fériés', { on: c.bloquees.includes('public') })}
    ${ebCase('estab-fbp-short', 'Bloquées aux petits congés', { on: c.bloquees.includes('school_short'), aide: 'Automne, hiver, détente et printemps.' })}
    ${ebCase('estab-fbp-summer', 'Bloquées aux grandes vacances', { on: c.bloquees.includes('school_summer'), aide: 'Juillet et août.' })}`;
}
function ebJoursAPartHtml() {
  return `<div id="estabHolidayOverridesList" class="eb-liste" data-eb-watch="exceptions">${renderEstablishmentOverridesList()}</div>
    <div class="eb-ajout"><label class="eb-ch"><span>Date</span><input type="date" id="estab-override-date" class="eb-f"></label><label class="eb-ch"><span>Ce jour-là</span><select id="estab-override-mode" class="eb-f"><option value="holiday">Horaires de vacances</option><option value="normal">Horaires normaux</option></select></label><button type="button" class="eb-b" onclick="addEstablishmentHolidayOverride()">Ajouter ce jour</button></div>`;
}
// Programmer une fermeture : memes ids que le panneau d origine, que submitAvailabilityBlock lit.
function ebFermetureFormHtml() {
  const pistes = Array.from({ length: getAvailabilityLaneCount() }, (u, i) => `<option value="${i + 1}">Piste ${i + 1}</option>`).join('');
  const activites = getAvailabilityActivities();
  const acts = activites.length ? activites.map(a => `<option value="${ebE(a.id)}">${ebE(a.label)}</option>`).join('') : '<option value="">Aucune activité disponible</option>';
  const forms = getEffectiveCatalogFormules().map(f => `<option value="${ebE(f.id)}">${ebE(f.name)}</option>`).join('');
  const jours = [1, 2, 3, 4, 5, 6, 0].map(d => `<option value="${d}">${ebE(AVAILABILITY_DAY_NAMES[d].charAt(0).toUpperCase() + AVAILABILITY_DAY_NAMES[d].slice(1))}</option>`).join('');
  return `<div class="eb-ferm-form availability-blocks" role="group" aria-label="Programmer une fermeture">
    <label class="eb-ch"><span>Que fermer ?</span><select id="avb-scope" class="eb-f" onchange="updateAvailabilityFormVisibility()"><option value="center">Tout le centre</option><option value="lane">Une piste</option><option value="activity">Une activité</option><option value="formula">Une formule</option></select></label>
    <label class="eb-ch avb-cond-lane" style="display:none"><span>Piste</span><select id="avb-lane" class="eb-f">${pistes}</select></label>
    <label class="eb-ch avb-cond-activity" style="display:none"><span>Activité</span><select id="avb-activity" class="eb-f">${acts}</select></label>
    <label class="eb-ch avb-cond-formula" style="display:none"><span>Formule</span><select id="avb-formula" class="eb-f">${forms}</select></label>
    <label class="eb-ch"><span>Quand ?</span><select id="avb-recurrence" class="eb-f" onchange="updateAvailabilityFormVisibility()"><option value="once">Une date</option><option value="weekly">Chaque semaine</option></select></label>
    <label class="eb-ch avb-cond-once"><span>Date</span><input type="date" id="avb-date" class="eb-f"></label>
    <label class="eb-ch avb-cond-weekly" style="display:none"><span>Jour</span><select id="avb-dow" class="eb-f">${jours}</select></label>
    <label class="eb-ch avb-cond-weekly" style="display:none"><span>À partir du</span><input type="date" id="avb-from" class="eb-f"></label>
    <label class="eb-ch avb-cond-weekly" style="display:none"><span>Jusqu’au</span><input type="date" id="avb-until" class="eb-f"></label>
    <label class="eb-ch eb-ch-h"><span>De (facultatif)</span><input type="time" id="avb-start" class="eb-f"></label>
    <label class="eb-ch eb-ch-h"><span>À</span><input type="time" id="avb-end" class="eb-f"></label>
    <label class="eb-ch eb-ch-m"><span>Motif</span><input type="text" id="avb-reason" class="eb-f" maxlength="200" placeholder="Entretien, soirée privée"></label>
    <button type="button" id="avbSubmit" class="eb-b eb-b-p" onclick="submitAvailabilityBlock()">Programmer</button>
  </div>`;
}

// ── Les briques ──────────────────────────────────────────────────────────────
// Une ligne de reglage : ce que c est et ce que ca change a gauche, le controle a droite.
function ebR(titre, aide, controle, cls = '') {
  return `<div class="eb-r${cls ? ` ${cls}` : ''}"><div class="eb-r-l"><b>${titre}</b>${aide ? `<small>${aide}</small>` : ''}</div><div class="eb-r-c">${controle}</div></div>`;
}
// Un groupe de reglages sous son titre ; « droite » se pose en face du titre (une bascule, un lien).
function ebG(titre, aide, corps, o = {}) {
  return `<section class="eb-g${o.cls ? ` ${o.cls}` : ''}"${o.id ? ` id="${o.id}"` : ''}${o.attrs ? ` ${o.attrs}` : ''}><div class="eb-g-h"><div class="eb-g-t"><h3>${titre}</h3>${aide ? `<p>${aide}</p>` : ''}</div>${o.droite ? `<div class="eb-g-d">${o.droite}</div>` : ''}</div>${corps ? `<div class="eb-g-c">${corps}</div>` : ''}</section>`;
}
function ebTexte(id, valeur, o = {}) {
  return `<input type="${o.type || 'text'}" id="${id}" class="eb-f${o.cls ? ` ${o.cls}` : ''}"${o.max ? ` maxlength="${o.max}"` : ''} autocomplete="off" value="${ebE(valeur)}"${o.ph ? ` placeholder="${ebE(o.ph)}"` : ''}${o.attrs ? ` ${o.attrs}` : ''}>`;
}
// La rubrique d un ancien onglet, d une case ou d une activite.
function ebSectionDe(k, salles) {
  const v = EB_ANCIENS_ONGLETS[k] || k;
  if (EB_RUBRIQUES.some(([id]) => id === v)) return v;
  return v === 'tables' || salles.some(a => a.id === v) ? 'activites' : 'centre';
}

// ── Le centre ────────────────────────────────────────────────────────────────
function ebCentreHtml(c) {
  const center = c.center;
  const ident = center.identity && typeof center.identity === 'object' ? center.identity : {};
  const tz = center.timezone || 'Europe/Brussels';
  const fuseaux = [['Europe/Brussels', 'Belgique'], ['Europe/Paris', 'France'], ['Europe/Luxembourg', 'Luxembourg'], ['Europe/Amsterdam', 'Pays-Bas']];
  const info = center.publicInfo && typeof center.publicInfo === 'object' ? center.publicInfo : {};
  const fuseau = `<select id="estab-timezone" class="eb-f">${fuseaux.map(([z, n]) => `<option value="${z}" ${tz === z ? 'selected' : ''}>${n}</option>`).join('')}${fuseaux.some(([z]) => z === tz) ? '' : `<option value="${ebE(tz)}" selected>${ebE(tz)}</option>`}</select>`;
  return ebG('Nom et état', '', ebR('Nom du centre', 'Il s’affiche sur le formulaire, dans les mails et dans la console.', ebTexte('estab-name', center.name, { max: 80 }))
      + ebR('État', 'Prévu : visible ici, pas encore réservable. Archivé : plus aucune réservation en ligne.', ebSeg('estab-status', 'État du centre', [['active', 'Ouvert à la réservation'], ['planned', 'Prévu'], ['closed', 'Archivé']], center.status))
      + ebR('Fuseau horaire', 'Les heures du planning, du formulaire et des mails suivent ce pays.', fuseau))
    + ebG('Ce que lisent les clients', 'Dans les mails de confirmation, sur le formulaire et chez l’assistant.',
      ebR('Adresse', '', ebTexte('estab-address', info.address || '', { max: 200, ph: 'Rue, numéro, code postal, ville', cls: 'eb-f-l' }))
      + ebR('Téléphone', 'Le numéro que les clients appellent.', ebTexte('estab-phone', info.phone || '', { type: 'tel', max: 40 }))
      + ebR('Parking', 'Une ligne, par exemple « Gratuit, 80 places ».', ebTexte('estab-parking', info.parking || '', { max: 60, ph: 'Gratuit' }))
      + ebR('Logo', 'L’adresse de l’image en ligne. Il s’affiche en haut du formulaire.', ebTexte('estab-logo', ident.logoUrl || '', { max: 300, ph: 'https://…/logo.png' }))
      + ebCase('estab-logoDark', 'Logo clair, pour un fond sombre', { on: ident.logoOnDark === true, aide: 'À cocher si le logo est blanc ou très clair : le formulaire le pose sur un fond foncé.' })
      + ebR('Site du centre', 'Le formulaire, les mails et l’assistant y renvoient.', ebTexte('estab-site', ident.siteUrl || '', { max: 300, ph: 'https://…' }))
      + ebR('Mails aux clients', 'L’expéditeur, les modèles et les relances se règlent dans Emails & relances.', '<button type="button" class="eb-b" onclick="openStaffMenuPage(\'emails\')">Ouvrir</button>')
      + ebR('Mail du centre', 'Les réponses des clients arrivent ici. Il se change avec l’équipe Pinlane.', `<b class="eb-ro-v">${ebE(center.publicEmail || 'Pas encore renseigné')}</b>`))
    + (c.canEdit ? ebG('Ajouter un centre', 'Il arrive en « prévu » : rien ne s’ouvre aux clients avant que vous le décidiez.',
      ebR('Nom du nouveau centre', '', ebTexte('estab-new-name', '', { max: 80, attrs: 'oninput="ebIdentifiantDuNom(this.value)"' }))
      + ebR('Identifiant', 'Sans espace. Il se lit dans le lien de réservation.', ebTexte('estab-new-id', '', { max: 40, ph: 'namur', attrs: 'oninput="this.dataset.touche=\'1\'"' }))
      + '<div class="eb-g-pied"><button type="button" class="eb-b" onclick="submitNewCenter()">Ajouter ce centre</button></div>') : '');
}

// ── Horaires ─────────────────────────────────────────────────────────────────
function ebHorairesHtml(c) {
  return ebG('La semaine', 'Les heures où les clients peuvent réserver. Une fermeture après minuit se met à l’heure du lendemain, jusqu’à 06:00.', ebSemaineHtml(c), { cls: 'eb-g-sem' })
    + ebG('Vacances et jours fériés', 'Les jours fériés belges et les congés scolaires de la Fédération Wallonie-Bruxelles.', ebVacancesHtml(c))
    + ebG('Jours à part', 'Un jour précis qui suit les horaires de vacances ou les horaires normaux. Il part avec Enregistrer.', ebJoursAPartHtml())
    + ebG('Fermetures programmées', 'Tout le centre, une piste, une activité ou une formule. La fermeture part tout de suite, sans Enregistrer.', `${ebFermetureFormHtml()}<div id="avbList" class="eb-liste">${renderAvailabilityBlocksList()}</div>`)
    + ebG('L’année', 'Touchez un jour pour voir ses heures, le fermer ou le rouvrir.', ebCalendrierHtml(), { cls: 'eb-g-an' });
}

// ── Activités ────────────────────────────────────────────────────────────────
function ebFermerSalleHtml(a) {
  const idA = ebE(a.id);
  const pistes = a.id === 'bowling' ? `<select class="eb-f" id="eb-f-piste-${idA}" aria-label="Quoi fermer"><option value="">Tout le bowling</option>${Array.from({ length: getAvailabilityLaneCount() }, (u, i) => `<option value="${i + 1}">Piste ${i + 1}</option>`).join('')}</select>` : '';
  return `${pistes}<input type="date" class="eb-f eb-f-date" id="eb-f-date-${idA}" min="${ebIso(new Date())}" aria-label="Date à fermer, ${ebE(a.label)}"><button type="button" class="eb-b" onclick="ebFermerSalle('${ebJs(a.id)}')">Fermer</button>`;
}
// ── Les prix (lot 2, 10/11) ──────────────────────────────────────────────────
// La page MONTRE ce que le client paie chez CE centre, lu par les memes accesseurs que le formulaire
// (booking-core). Un seul endroit l ECRIT : la planche de Tarifs, ouverte sur la bonne case, le prix pret
// a taper. Deux editeurs d un meme prix finiraient par dire deux montants.
function ebPeutPrix() { return typeof canUseStaffPermission !== 'function' || canUseStaffPermission('pricing.manage'); }
function ebChangerPrix(type, id) {
  if (typeof window.tarifsOuvrirPrix === 'function') window.tarifsOuvrirPrix(type, id);
  else openStaffMenuPage('prices');
}
function ebEuros(v) { return `${typeof formatPrixCourt === 'function' ? formatPrixCourt(v) : String(v)} €`; }
function ebPrixPuces(items) {
  return `<span class="eb-prix">${items.map(([l, p]) => `<span class="eb-prix-i"><span>${ebE(l)}</span><b>${p == null ? 'sur place' : ebEuros(p)}</b></span>`).join('')}</span>`;
}
// Les prix publies de CE centre, ou null tant que la configuration chargee est celle d un autre centre.
function ebPrixActivite(c, id) {
  const cfg = typeof getCenterScheduleConfig === 'function' ? getCenterScheduleConfig() : null;
  if (!cfg || cfg.id !== c.center.id) return null;
  if (id === 'bowling') {
    const parties = typeof getBowlingPricing === 'function' ? getBowlingPricing() : null;
    if (parties && Array.isArray(parties.tiers) && parties.tiers.length) {
      const jours = (t) => (typeof describePricingDays === 'function' ? `<small>${ebE(describePricingDays(t.days))}</small>` : '');
      return { aide: 'Par joueur, selon le jour et le nombre de parties.', html: parties.tiers.map((t) => `<span class="eb-prix-l">${jours(t)}${ebPrixPuces((t.prices || []).map((p, i) => [`${i + 1} partie${i ? 's' : ''}`, p]))}</span>`).join('') };
    }
    return { aide: 'Par piste, selon la durée.', html: ebPrixPuces(getDurationOptionsCatalog().map((o) => [o.label, o.price])) };
  }
  if (id === 'laser_game') return { aide: 'Par joueur, selon le nombre de parties.', html: ebPrixPuces(getLaserOptionsCatalog().map((o) => [o.label, o.price])) };
  if (id === 'fun_run') return { aide: 'Selon la durée de la session.', html: ebPrixPuces(getFunRunOptionsCatalog().map((o) => [o.label, o.price])) };
  const act = typeof getCenterActivity === 'function' ? getCenterActivity(id) : null;
  if (!act) return null;
  if (act.priceType === 'on_site' || act.priceValue == null) return { aide: 'Le client paie à l’accueil : le formulaire ne chiffre rien.', html: '<span class="eb-prix"><span class="eb-prix-i"><b>Réglé sur place</b></span></span>' };
  const paliers = act.pricing && Array.isArray(act.pricing.tiers) && act.pricing.tiers.length;
  return { aide: paliers ? 'Prix de base : il change selon le jour ou l’heure.' : '', html: ebPrixPuces([[act.unitLabel || 'Prix', act.priceValue]]) };
}
function ebPrixRang(c, id) {
  const p = ebPrixActivite(c, id);
  const bouton = ebPeutPrix() ? `<button type="button" class="eb-b" onclick="ebChangerPrix('activite','${ebJs(id)}')">Changer</button>` : '<small class="eb-prix-qui">Changer un prix demande le droit Tarifs.</small>';
  if (!p) return ebR('Prix', 'Les prix de ce centre se lisent dans Tarifs.', bouton, 'eb-r-prix');
  return ebR('Prix', p.aide, `${p.html}${bouton}`, 'eb-r-prix');
}
// Ajouter une activite, une boisson ou un service : la fenetre du catalogue (celle de Tarifs), ouverte ici.
// Ce qui s y ajoute existe pour tous les centres de l entreprise, et pour eux seuls.
function ebPrixDuCatalogue(a) {
  if (a.priceType === 'on_site' || a.priceValue == null) return 'réglé sur place';
  return `${ebEuros(a.priceValue)}${a.priceUnit ? ` ${a.priceUnit}` : ''}`;
}
function ebAjoutHtml() {
  const peut = typeof canUseStaffPermission !== 'function' || canUseStaffPermission('settings.manage');
  const cat = typeof window.catalogueActivitesAjoutees === 'function' ? window.catalogueActivitesAjoutees() : { etat: 'ok', liste: [] };
  let lignes;
  if (cat.etat === 'ok' && cat.liste.length) {
    lignes = cat.liste.map((a) => `<div class="eb-aj"><span class="eb-aj-n"><b>${ebE(a.name)}</b><small>${ebE(ebPrixDuCatalogue(a))} · ${a.bookable ? 'réservable en ligne' : 'seulement dans les formules'}</small></span>${peut ? `<span class="eb-aj-b"><button type="button" class="eb-lien eb-lien-b" onclick="aevOpenEdit('${ebJs(a.id)}')" aria-label="Modifier ${ebE(a.name)}">Modifier</button><button type="button" class="eb-lien eb-lien-b" onclick="aevDelete('${ebJs(a.id)}')" aria-label="Retirer ${ebE(a.name)}">Retirer</button></span>` : ''}</div>`).join('');
  } else if (cat.etat === 'ok') {
    lignes = '<p class="eb-vide">Rien d’ajouté pour l’instant : une boisson, un goûter, une réalité virtuelle…</p>';
  } else if (cat.etat === 'erreur' || !ebPeutPrix()) {
    lignes = '<p class="eb-vide">La liste se lit avec le droit Tarifs.</p>';
  } else {
    lignes = '<p class="eb-vide">Lecture du catalogue…</p>';
  }
  // Les anciens noms sans prix (« Vos activites ») ne se vendaient nulle part : montres tant qu il en reste.
  const anciens = establishmentCustomActivitiesDraft.length ? `<div id="estabCustomActivitiesList" class="eb-liste" data-eb-watch="activites-perso">${renderEstablishmentCustomActivities()}</div><p class="eb-note">Ces noms n’ont pas de prix : ils ne se vendent nulle part. Ajoutez-les avec leur prix.</p>` : '';
  return ebG('Ajouter une activité, une boisson ou un service', 'Son nom, son prix, et s’il se réserve en ligne. Il existe pour tous vos centres.', `<div class="eb-liste" data-eb-watch="catalogue">${lignes}</div>${anciens}${peut ? '<div class="eb-ajout"><button type="button" class="eb-b" onclick="aevOpenCreate()">Ajouter</button></div>' : ''}`, { id: 'eb-a-ajout' });
}
function ebActiviteHtml(c, a) {
  const id = a.id;
  const propose = Boolean(c.center.activityAvailability && c.center.activityAvailability[id]);
  let lignes = '';
  if (id === 'bowling') {
    lignes = ebR('Pistes', 'Le planning et le formulaire en ligne comptent sur ce nombre.', ebNum('estab-laneCount', 'Pistes de bowling', { min: 1, max: 40, value: Number(c.bowling.laneCount || 8) }))
      + ebR('Joueurs par piste', 'Au-delà, un groupe est réparti sur plusieurs pistes.', ebNum('estab-normalCap', 'Joueurs par piste', { min: 1, max: 12, value: Number(c.bowling.normalCapacityPerLane || 6) }))
      + ebR('Joueurs par piste quand c’est plein', 'Si aucune piste n’est libre, le planning peut monter jusqu’à ce nombre.', ebNum('estab-emergencyCap', 'Joueurs par piste quand c’est plein', { min: 1, max: 15, value: Number(c.bowling.emergencyCapacityPerLane || 7), minFrom: 'estab-normalCap' }))
      + ebCase('estab-preferAdjacent', 'Un groupe sur des pistes voisines', { on: c.bowling.preferAdjacentLanes !== false, aide: 'Un groupe qui prend plusieurs pistes les reçoit côte à côte.' });
  } else if (id === 'laser_game') {
    lignes = ebR('Armes', 'Le nombre de joueurs qui peuvent jouer en même temps.', ebNum('estab-weaponCount', 'Armes de laser', { min: 0, max: 200, value: Number(c.laser.weaponCount || 0) }))
      + ebR('Parties en même temps', 'Au-delà, le créneau est complet.', ebNum('estab-launches', 'Parties en même temps', { min: 1, max: 20, value: Number(c.laser.parallelLaunches || 1) }))
      + ebCase('estab-requiresComplete', 'Lancer une partie avec le groupe complet', { on: c.laser.requiresCompleteGroupBeforeLaunch !== false, aide: 'Les retardataires attendent la partie suivante. Les mails aux clients le disent.' });
  } else {
    const inst = installationsActivite(a, c.center);
    if (inst) {
      const unites = inst.mot === 'session' ? 'installations' : `${inst.mot}s`;
      const titre = unites.charAt(0).toUpperCase() + unites.slice(1);
      lignes = ebR(titre, `Combien de ${unites} le formulaire peut vendre en même temps.`, ebNum(`estab-cap-units-${id}`, `${a.label}, ${unites}`, { min: 1, max: 50, value: inst.units, cls: 'estab-cap-input', capName: a.label, capWhat: unites }))
        + (inst.capacityPerUnit ? ebR(`Joueurs par ${inst.mot}`, `Au-delà, un groupe est réparti sur plusieurs ${unites}.`, ebNum(`estab-cap-players-${id}`, `${a.label}, joueurs par ${inst.mot}`, { min: 1, max: 500, value: inst.capacityPerUnit, cls: 'estab-cap-input', capName: a.label, capWhat: `joueurs par ${inst.mot}` })) : '')
        + (inst.plafond ? ebR('Au plus par réservation', `Une seule réservation ne prend pas plus de ${unites} que ce nombre.`, ebNum(`estab-cap-max-${id}`, `${a.label}, au plus par réservation`, { min: 1, max: 50, value: inst.plafond, cls: 'estab-cap-input', capName: a.label, capWhat: `${unites} au plus par réservation` })) : '');
    }
    if (id === 'arcade_time') lignes += `<div class="eb-arcades">${ebArcadesHtml(c.center)}</div>`;
  }
  if (id !== 'arcade_time') lignes = ebPrixRang(c, id) + lignes;
  lignes += ebR('Fermer un jour', 'La fermeture part tout de suite, sans Enregistrer.', ebFermerSalleHtml(a), 'eb-r-ferm');
  const liens = `${id === 'bowling' ? '<a class="eb-lien" href="#" onclick="openStaffMenuPage(\'lanes\');return false">État des pistes</a>' : ''}`;
  return ebG(ebE(a.label), propose ? '' : 'Pas réservable dans ce centre pour l’instant.', lignes, { id: `eb-a-${ebE(id)}`, cls: `eb-act${propose ? '' : ' est-off'}`, attrs: `data-act="${ebE(id)}"`, droite: `${liens}${ebCase(`estab-act-${id}`, 'Réservable en ligne', { on: propose, cls: 'eb-k-tete' })}` });
}
function ebTablesHtml(c, secoursVide) {
  const soft = Number(c.party.softCapacity || 6);
  const hard = Number(c.party.hardCapacity || Math.max(soft, 8));
  return ebG('Tables d’anniversaire', '', ebR('Tables', 'Le nombre de tables d’anniversaire du centre.', ebNum('estab-tableSoft', 'Tables d’anniversaire', { min: 1, max: 100, value: soft }))
      + ebR('Limite de tables', 'Au-delà de ce nombre en même temps, un mail peut vous prévenir.', ebNum('estab-tableHard', 'Limite de tables', { min: 1, max: 120, value: hard, minFrom: 'estab-tableSoft' }))
      + ebCase('estab-tableLimit', 'Me prévenir par mail au-delà de la limite', { on: c.party.limitEnabled === true, aide: 'Rien n’est refusé au client : la réservation passe, un mail part vers la boîte de secours.' })
      + `<p class="eb-dit" data-eb-phrase="tables">${ebE(ebPhraseTables(soft, hard, c.party.limitEnabled === true))}</p>`
      + (secoursVide ? '<p class="eb-note">La boîte de secours n’a aucune adresse : aucun mail ne partira. Elle se règle dans Accueil et secours.</p>' : ''),
    { id: 'eb-a-tables', cls: 'eb-act', attrs: 'data-act="tables"' });
}
function ebAutresHtml() {
  const entree = (fn) => `onkeydown="if(event.key==='Enter'){event.preventDefault();${fn}();}"`;
  return ebAjoutHtml()
    + ebG('Autres installations', 'Un équipement du centre qui n’est pas dans la liste : un court, une salle, un simulateur.', `<div id="estabDeclaredResourcesList" class="eb-liste estab-custom-activities-list" data-eb-watch="installations">${renderEstablishmentDeclaredResources()}</div><div class="eb-ajout"><label class="eb-ch eb-ch-m"><span>Installation</span><input type="text" id="estab-res-name" class="eb-f" placeholder="Court de padel" maxlength="60" autocomplete="off" ${entree('addEstablishmentDeclaredResource')}></label>${ebMet('Combien', ebNum('estab-res-units', 'Combien', { min: 1, max: 50, value: 1 }))}${ebMet('Joueurs chacune', ebNum('estab-res-capacity', 'Joueurs chacune', { min: 1, max: 500, value: 4 }))}${ebMet('Remise en état (min)', ebNum('estab-res-cleanup', 'Minutes de remise en état', { min: 0, max: 240, value: 0, step: 5 }))}${ebCase('estab-res-mixing', 'Deux groupes ensemble', { on: false, cls: 'eb-k-tete' })}<button type="button" class="eb-b" onclick="addEstablishmentDeclaredResource()">Ajouter</button></div>`);
}

// ── Formules ─────────────────────────────────────────────────────────────────
function ebFormulesHtml(c) {
  const anniv = Array.isArray(c.classification.birthdayFormulaIds) ? c.classification.birthdayFormulaIds : ['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'f7', 'f8'];
  const familles = [];
  c.formules.forEach((f) => {
    const nom = f.family || 'Formules';
    let groupe = familles.find(x => x.nom === nom);
    if (!groupe) { groupe = { nom, items: [] }; familles.push(groupe); }
    groupe.items.push(f);
  });
  const prix = p => `${String(Number(p)).replace('.', ',')} €`;
  const ligne = (f) => {
    const id = ebE(f.id);
    const on = c.center.offerAvailability?.[f.id] !== false;
    const fete = anniv.includes(f.id);
    return `<div class="eb-tr${on ? '' : ' est-off'}" role="row" data-eb-nom="${ebE(f.name)}"><span role="cell" class="eb-f-n"><b>${ebE(f.name)}</b>${Array.isArray(f.desc) ? `<small>${ebE(f.desc.slice(0, 3).join(', '))}</small>` : ''}</span><span role="cell" class="eb-f-p">${f.price != null ? `${prix(f.price)}<small>${f.type === 'per_lane' ? 'la piste' : 'par joueur'}</small>` : ''}${ebPeutPrix() ? `<button type="button" class="eb-lien eb-lien-b" onclick="ebChangerPrix('formule','${ebJs(id)}')" aria-label="Changer le prix de ${ebE(f.name)}">Changer</button>` : ''}</span><span role="cell"><label class="eb-k eb-k-seule"><input type="checkbox" id="estab-offer-${id}" data-estab-offer="${id}" ${on ? 'checked' : ''} aria-label="${ebE(f.name)} réservable en ligne"><span class="eb-k-b" aria-hidden="true"></span></label></span><span role="cell"><label class="eb-k eb-k-seule"><input type="checkbox" id="estab-bday-${id}" data-estab-bday="${id}" ${fete ? 'checked' : ''} aria-label="${ebE(f.name)} compte en anniversaire"><span class="eb-k-b" aria-hidden="true"></span></label></span></div>`;
  };
  return `<div class="eb-tab" role="table" aria-label="Les formules"><div class="eb-tr eb-th" role="row"><span role="columnheader">Formule</span><span role="columnheader">Prix</span><span role="columnheader">Réservable en ligne</span><span role="columnheader">Anniversaire</span></div>${familles.map(g => `<div class="eb-tr eb-fam" role="row"><span role="cell">${ebE(String(g.nom).replace(/speciales/i, 'spéciales'))}</span></div>${g.items.map(ligne).join('')}`).join('')}</div>`;
}
function ebFormulesPanHtml(c) {
  return ebG('Les formules', 'Décochez une formule pour la retirer du formulaire. « Anniversaire » classe la réservation en anniversaire.', ebFormulesHtml(c), { cls: 'eb-g-tab' })
    + ebG('Suggestions avant de confirmer', 'Ce que le formulaire propose en plus, juste avant la confirmation.', `<div class="eb-g-bloc" data-eb-watch="suggestions">${window.PinlaneUpsellSettings?.renderEdit(c.center, establishmentUpsellCatalogue()) || ''}</div>`);
}

// ── Réservations ─────────────────────────────────────────────────────────────
// Les regles de la reservation EN LIGNE (lot 3, 10/11) : jusqu a quand et combien de temps a l avance le formulaire
// accepte une date. Le serveur les pose a ses deux portes publiques ; le comptoir n est jamais concerne.
function ebReglesEnLigneHtml(c) {
  const r = c.center.bookingRules || {};
  const min = Math.max(0, Math.trunc(Number(r.minDaysAhead) || 0));
  const horizon = r.horizonDays == null ? '' : String(Math.trunc(Number(r.horizonDays)));
  const liste = (id, label, choix, valeur, autre) => `<select id="${id}" class="eb-f" aria-label="${ebE(label)}">${choix.map(([v, n]) => `<option value="${v}" ${String(v) === String(valeur) ? 'selected' : ''}>${n}</option>`).join('')}${choix.some(([v]) => String(v) === String(valeur)) ? '' : `<option value="${ebE(valeur)}" selected>${ebE(autre)}</option>`}</select>`;
  return ebG('Réserver en ligne', 'Ces deux règles valent pour le formulaire en ligne. Au comptoir, l’équipe réserve quand elle veut.',
    ebR('Au plus tard', 'Jusqu’à quand un client peut réserver en ligne pour un jour donné. Trop tard, il lit qu’il doit choisir un autre jour ou appeler.', liste('estab-book-min', 'Réserver en ligne au plus tard', [[0, 'Jusqu’au dernier moment'], [1, 'La veille'], [2, 'Deux jours avant'], [3, 'Trois jours avant'], [7, 'Une semaine avant']], min, `${min} jours avant`))
    + ebR('Au plus tôt', 'Combien de temps à l’avance un client peut réserver en ligne.', liste('estab-book-horizon', 'Réserver en ligne au plus tôt', [['', 'Un an à l’avance'], [180, 'Six mois à l’avance'], [90, 'Trois mois à l’avance'], [60, 'Deux mois à l’avance'], [30, 'Un mois à l’avance']], horizon, `${horizon} jours à l’avance`)));
}
function ebReservationsHtml(c) {
  const k = c.classification;
  return ebReglesEnLigneHtml(c) + ebG('Groupes et clients', 'Comment la console classe les réservations et les clients.',
      ebR('Un groupe à partir de', 'Une réservation de ce nombre de joueurs ou plus est un groupe.', ebNum('estab-groupMinPax', 'Un groupe à partir de combien de joueurs', { min: 2, max: 200, value: Number(k.groupMinPax || 10) }))
      + ebR('Ou un client qui cumule', 'Un client qui a réservé pour ce nombre de joueurs au total compte aussi comme groupe.', ebNum('estab-groupMinCumulative', 'Joueurs cumulés par un client', { min: 2, max: 5000, value: Number(k.groupMinCumulative || 18) }))
      + ebR('Client clé à partir de', 'Le montant dépensé au total, en euros. À 0, les 20 % qui dépensent le plus.', ebNum('estab-keyClientMinSpend', 'Client clé à partir de combien d’euros', { min: 0, max: 100000, value: Number(k.keyClientMinSpend || 0), step: 50 }))
      + ebCase('estab-countFormulaAsGroup', 'Une formule compte comme un groupe', { on: k.countFormulaAsGroup !== false, aide: 'Même avec moins de joueurs qu’un groupe.' })
      + ebCase('estab-birthdayFromFormula', 'Anniversaire d’après la formule', { on: k.birthdayFromFormula !== false, aide: 'Une formule marquée « Anniversaire » classe la réservation en anniversaire.' }))
    + ebG('Grands groupes', '', ebR('Demande sur mesure à partir de', 'Au-delà de ce nombre de joueurs, le client envoie une demande au lieu de réserver. Vide : jamais.', ebNum('estab-customRequestFromPax', 'Demande sur mesure dès', { min: 2, max: 240, value: Number(c.center.customRequest && c.center.customRequest.fromPax) || '', start: 30, vide: 'Jamais' })))
    + ebG('Validation par l’équipe', '', `<div class="eb-g-bloc" data-eb-watch="validation">${establishmentValidationHtml(c.center)}</div>`);
}

// ── Accueil et secours ───────────────────────────────────────────────────────
function ebAccueilHtml(c) {
  const emails = c.center.secours && Array.isArray(c.center.secours.emails) ? c.center.secours.emails : [];
  return ebG('Accueil', '', ebR('En retard après', 'Un groupe pas encore arrivé après ce nombre de minutes passe « en retard » dans le planning.', ebNum('estab-lateThreshold', 'En retard après combien de minutes', { min: 0, max: 60, value: c.retard })))
    + ebG('Boîte de secours', 'Une copie complète de chaque réservation, de chaque demande sur mesure et la feuille du jour partent vers ces adresses. C’est ce qui permet d’accueillir les groupes si Pinlane est indisponible.',
      ebR('Adresses', 'Séparées par une virgule, 5 au plus. De préférence une boîte à part, protégée par une double authentification.', `<input type="text" id="estab-secours-emails" class="eb-f eb-f-l" inputmode="email" autocomplete="off" value="${ebE(emails.join(', '))}" placeholder="secours@votrecentre.be" aria-label="Adresses de secours">`));
}

// ── Formulaire en ligne ──────────────────────────────────────────────────────
function ebFormulaireHtml(c) {
  const center = c.center;
  const lien = `/reserver/${encodeURIComponent(center.id)}`;
  return ebG('Lien de réservation', 'Le lien à partager, ou à mettre sur votre site et vos réseaux.', `<div class="eb-lienresa"><a href="${lien}" target="_blank" rel="noopener">${ebE(`${location.host}${lien}`)}</a><button type="button" class="eb-b" onclick="ebCopierLien('${ebJs(lien)}')">Copier</button></div>`)
    + ebG('Apparence', 'La couleur et le style du formulaire de réservation.', `<div class="eb-g-bloc">${establishmentAccentFieldHtml(center)}</div>`)
    + ebG('Encaissement', '', `<div class="eb-g-bloc">${establishmentPaymentFieldHtml(center)}</div>`)
    + ebG('Sur votre site', '', `<div class="eb-g-bloc">${establishmentEmbedFieldHtml(center)}</div>`);
}

// ── La page ──────────────────────────────────────────────────────────────────
function renderStaffUtilityEstablishment() {
  if (!staffCenterConfigCache.loaded && !staffCenterConfigCache.loading) {
    setTimeout(() => loadStaffCenterConfig(false), 0);
  }
  // Les formules consomment la liste VIVE du catalogue : son chargement se declenche d ici aussi.
  if (typeof window.pevEnsureCatalogLoaded === 'function' && canUseStaffPermission('pricing.manage')) window.pevEnsureCatalogLoaded();
  // Le calendrier montre les fermetures decidees : elles se lisent avec le reste.
  if (canUseStaffPermission('settings.manage') && !availabilityBlocksCache.loaded && !availabilityBlocksCache.loading) setTimeout(() => loadAvailabilityBlocks(false), 0);
  if (!staffCenterConfigCache.loaded || staffCenterConfigCache.loading) {
    return '<div class="establishment-page"><div class="establishment-loading">Lecture de la configuration des centres…</div></div>';
  }
  if (staffCenterConfigCache.error) {
    return `<div class="establishment-page"><div class="establishment-error"><strong>Configuration indisponible</strong><span>${ebE(staffCenterConfigCache.error)}</span><button type="button" class="btn btn-secondary btn-sm" onclick="loadStaffCenterConfig(true)">Réessayer</button></div></div>`;
  }
  const center = getEstablishmentCenter();
  if (!center) return '<div class="establishment-page"><div class="establishment-loading">Aucun centre.</div></div>';
  const canEdit = canUseStaffPermission('settings.manage');
  // Chaque rendu repart de la config du serveur : rien n est en cours.
  state.establishmentEditing = false;
  ebInitDrafts(center);
  ebJourHtml = '';
  const c = ebContexte(center, canEdit);
  const estProposee = a => Boolean(center.activityAvailability && center.activityAvailability[a.id]);
  const salles = c.activites.filter(a => !EB_PAS_DES_SALLES.includes(a.id));
  const sur = salles.filter(estProposee);
  const off = salles.filter(a => !estProposee(a));
  // La rubrique ouverte tient d un rendu a l autre ; un rendu ne fait jamais defiler la page.
  ebOuverte = ebSectionDe(state.establishmentTab, salles);
  const secoursVide = !(center.secours && Array.isArray(center.secours.emails) && center.secours.emails.length);
  // Des reglages que rien n applique encore (le comptoir, la prudence et le partage du laser) : hors de l ecran,
  // leur valeur repart telle quelle a l enregistrement.
  const risque = ['critical', 'managed', 'low'].includes(c.laser.riskLevel) ? c.laser.riskLevel : 'managed';
  const garde = (id, on) => `<input type="checkbox" id="${id}" ${on ? 'checked' : ''}>`;
  const gardes = `<select id="estab-laserRisk"><option value="${ebE(risque)}" selected>${ebE(risque)}</option></select>${garde('estab-canSplit', c.laser.canSplitGroupsCleanly === true)}${garde('estab-bar-booking', c.barDesk.handlesBooking !== false)}${garde('estab-bar-briefing', c.barDesk.handlesBriefing !== false)}${garde('estab-bar-food', c.barDesk.handlesFoodAndDrink !== false)}${garde('estab-bar-escort', c.barDesk.activityEscort === true)}${(c.activites || []).filter(a => EB_PAS_DES_SALLES.includes(a.id)).map(a => garde(`estab-act-${ebE(a.id)}`, estProposee(a))).join('')}`;
  const sous = [...sur, { id: 'tables', label: 'Tables d’anniversaire' }, { id: 'ajout', label: 'Ajouter' }];
  const nav = EB_RUBRIQUES.map(([k, titre]) => `<button type="button" class="eb-t eb-m${k === ebOuverte ? ' is-on' : ''}" data-k="${k}"${k === ebOuverte ? ' aria-current="true"' : ''} aria-controls="eb-p-${k}" onclick="ebOuvrir('${k}')"><span>${titre}</span><i class="eb-pt" aria-hidden="true"></i></button>${k === 'activites' ? `<div class="eb-sous">${sous.map(a => `<button type="button" class="eb-s" data-k="${ebE(a.id)}" onclick="ebOuvrir('${ebJs(a.id)}')">${ebE(a.label)}</button>`).join('')}</div>` : ''}`).join('');
  const pan = (k, corps) => {
    const [, titre, aide] = EB_RUBRIQUES.find(([id]) => id === k);
    return `<section class="eb-pan" id="eb-p-${k}" data-k="${k}" aria-labelledby="eb-h-${k}" ${ebOuverte === k ? '' : 'hidden'}><div class="eb-pan-h"><h2 id="eb-h-${k}">${titre}</h2><p>${aide}</p></div>${corps}</section>`;
  };
  setTimeout(ebAfterRender, 0);
  return `<div class="establishment-page eb${canEdit ? '' : ' eb-ro'}" data-estab-page data-eb-center="${ebE(center.id)}" oninput="ebOnChange(event)" onchange="ebOnChange(event)" onclick="ebOnClick(event)">
    <div class="eb-haut"><div class="eb-haut-g"><h1 class="eb-name">${ebE(center.name)}</h1><p class="eb-auj" data-eb-auj></p>${canEdit ? '' : '<p class="eb-note">Lecture seule : la direction règle cette page.</p>'}</div><div class="eb-haut-d">${ebCentresHtml(c)}<a class="eb-voir" href="/reserver/${encodeURIComponent(center.id)}" target="_blank" rel="noopener">Voir le formulaire</a></div></div>
    <div class="eb-cadre">
      <nav class="eb-nav" aria-label="Rubriques de l’établissement">${nav}</nav>
      <div class="eb-det">
        ${pan('centre', ebCentreHtml(c))}
        ${pan('horaires', ebHorairesHtml(c))}
        ${pan('activites', `${sur.map(a => ebActiviteHtml(c, a)).join('')}${ebTablesHtml(c, secoursVide)}${off.length ? `<h3 class="eb-pan-sous">Pas encore réservables dans ce centre</h3>${off.map(a => ebActiviteHtml(c, a)).join('')}` : ''}${ebAutresHtml()}`)}
        ${pan('formules', ebFormulesPanHtml(c))}
        ${pan('reservations', ebReservationsHtml(c))}
        ${pan('accueil', ebAccueilHtml(c))}
        ${pan('formulaire', ebFormulaireHtml(c))}
        <div class="eb-gardes" hidden>${gardes}</div>
        <div class="eb-bar" id="ebBar" role="region" aria-label="Changements à enregistrer" hidden><span class="eb-bar-n" id="ebBarN" aria-live="polite"></span><button type="button" class="eb-bar-cancel" onclick="cancelEstablishmentEdit()">Annuler</button><button type="button" id="estabSaveBtn" class="eb-bar-save" onclick="submitCenterConfig('${ebJs(center.id)}')">Enregistrer</button></div>
      </div>
    </div>
  </div>`;
}

function ebAfterRender() {
  const root = document.querySelector('[data-estab-page]');
  if (!root) return;
  ebRefresh();
  if (root.classList.contains('eb-ro')) {
    // Lire reste possible : les cases s ouvrent, un jour se regarde ; rien ne se change.
    root.querySelectorAll('.eb-det input, .eb-det select, .eb-det textarea, .eb-det button:not(.eb-j):not(.eb-jour-x)').forEach((el) => { el.disabled = true; });
    return;
  }
  ebSnap = ebState();
  const bar = document.getElementById('ebBar');
  if (bar) bar.hidden = true;
  const voulu = ebChampVouluLu();
  if (!voulu) return;
  if (!(voulu.jusqua > Date.now())) { ebChampVoulu(null); return; }
  const champ = voulu.centre === root.dataset.ebCenter ? document.getElementById(voulu.champ) : null;
  if (champ) setTimeout(() => { if (champ.isConnected) focusEstablishmentField(champ); }, 0);
}

// Ouvre une rubrique : les autres se cachent, leurs champs restent dans la page. Une activite ouvre la rubrique
// Activites et vient en haut de l ecran.
function ebOuvrir(k) {
  const voulu = EB_ANCIENS_ONGLETS[k] || k || 'centre';
  const bloc = document.getElementById(`eb-a-${voulu}`);
  const cible = document.getElementById(`eb-p-${voulu}`) ? voulu : (bloc ? 'activites' : 'centre');
  ebOuverte = cible;
  state.establishmentTab = bloc ? voulu : cible;
  document.querySelectorAll('[data-estab-page] .eb-m').forEach((t) => {
    const on = t.dataset.k === cible;
    t.classList.toggle('is-on', on);
    if (on) t.setAttribute('aria-current', 'true'); else t.removeAttribute('aria-current');
  });
  document.querySelectorAll('[data-estab-page] .eb-s').forEach((s) => { s.classList.toggle('is-on', Boolean(bloc) && s.dataset.k === voulu); });
  document.querySelectorAll('[data-estab-page] .eb-pan').forEach((p) => { p.hidden = p.dataset.k !== cible; });
  if (cible === 'horaires') ebPeindreCalendrier();
  const haut = bloc || document.getElementById(`eb-p-${cible}`);
  if (haut && haut.scrollIntoView && (bloc || haut.getBoundingClientRect().top < 0)) haut.scrollIntoView({ block: 'start' });
}
function ebGo(key) { ebOuvrir(EB_ANCIENS_ONGLETS[key] || key); }

function ebSelectCenter(id) {
  if (state.establishmentEditing && !window.confirm('Des changements ne sont pas enregistrés. Changer de centre les efface. Continuer ?')) {
    const liste = document.querySelector('[data-estab-page] .eb-centres-liste');
    if (liste) liste.value = getEstablishmentCenter()?.id || '';
    return;
  }
  selectEstablishmentCenter(id);
}

function ebStep(id, dir) {
  const input = document.getElementById(id);
  if (!input || input.disabled) return;
  const step = Number(input.dataset.ebStep) || 1;
  const base = input.dataset.ebMinFrom ? Number(document.getElementById(input.dataset.ebMinFrom)?.value) : NaN;
  const min = Number.isFinite(base) ? Math.max(Number(input.min), base) : Number(input.min);
  const max = Number(input.max);
  const peutEtreVide = Boolean(input.dataset.ebVide);
  let v = input.value === '' ? null : Number(input.value);
  if (v === null || !Number.isFinite(v)) {
    if (dir < 0) return;
    v = Number(input.dataset.ebStart) || min;
  } else {
    v = Math.round((v + dir * step) * 100) / 100;
    if (v < min) v = peutEtreVide ? null : min;
    if (v !== null && v > max) v = max;
  }
  input.value = v === null ? '' : String(v);
  input.dispatchEvent(new Event('input', { bubbles: true }));
}

function ebPick(id, value) {
  const select = document.getElementById(id);
  if (!select || select.disabled) return;
  select.value = value;
  select.dispatchEvent(new Event('change', { bubbles: true }));
}

// L identifiant d un nouveau centre se deduit de son nom, tant qu on ne l a pas tape soi-meme.
function ebIdentifiantDuNom(nom) {
  const champ = document.getElementById('estab-new-id');
  if (champ && !champ.dataset.touche) champ.value = establishmentSlugify(nom);
}

function ebCopierLien(lien) {
  const adresse = `${location.origin}${lien}`;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(adresse).then(() => toast('Lien copié.')).catch(() => toast(adresse));
  } else toast(adresse);
}

// ── Fermer, depuis la page ───────────────────────────────────────────────────
// Un jour, une piste, une activite : la fermeture part tout de suite, sans passer par Enregistrer, comme le panneau
// Programmer une fermeture. Le calendrier se repeint des que la liste revient.
async function ebEnvoyerFermeture(corps, dit) {
  if (!canUseStaffPermission('settings.manage')) { toast('Réservé à la direction.'); return false; }
  if (ebEnvoiEnCours) return false;
  ebEnvoiEnCours = true;
  let ok = false;
  try {
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'saveAvailabilityBlock', centerId: getCurrentStaffCenterId(), recurrence: 'once', ...corps }) });
    toast(dit);
    ok = true;
  } catch (error) {
    toast(error?.message || 'Fermeture impossible.');
  } finally {
    ebEnvoiEnCours = false;
  }
  await loadAvailabilityBlocks(true);
  return ok;
}
function ebFermerSalle(activiteId) {
  const date = document.getElementById(`eb-f-date-${activiteId}`)?.value;
  if (!date) { toast('Choisissez une date.'); return; }
  const piste = document.getElementById(`eb-f-piste-${activiteId}`)?.value || '';
  const corps = piste ? { scopeType: 'lane', scopeRef: piste, date } : { scopeType: 'activity', scopeRef: activiteId, date };
  ebEnvoyerFermeture(corps, piste ? `Piste ${piste} fermée ${ebDateDite(date)}.` : `${availabilityActivityLabel(activiteId)} fermé ${ebDateDite(date)}.`);
}
function ebFermerJour(iso, debut = '', fin = '') {
  if (debut && !/^\d{2}:\d{2}$/.test(debut)) { toast('Choisissez une heure.'); return; }
  ebEnvoyerFermeture({ scopeType: 'center', date: iso, ...(debut ? { startTime: debut, endTime: fin || '24:00' } : {}) }, debut ? `Fermé dès ${debut}, ${ebDateDite(iso)}.` : `Fermé ${ebDateDite(iso)}.`);
}
function ebBloquerJour(iso) {
  const [type, ref] = String(document.getElementById('eb-j-quoi')?.value || '').split(':');
  if (!type || !ref) { toast('Choisissez quoi fermer.'); return; }
  ebEnvoyerFermeture({ scopeType: type, scopeRef: ref, date: iso }, `${type === 'lane' ? `Piste ${ref}` : availabilityActivityLabel(ref)} fermé ${ebDateDite(iso)}.`);
}
// Un jour a part se decide ici aussi : il part avec Enregistrer, comme dans la liste des jours a part.
function ebForcerJour(iso, mode) {
  establishmentHolidayOverridesDraft = establishmentHolidayOverridesDraft.filter(item => item.date !== iso);
  establishmentHolidayOverridesDraft.push({ date: iso, mode });
  const liste = document.getElementById('estabHolidayOverridesList');
  if (liste) liste.innerHTML = renderEstablishmentOverridesList();
  ebRefresh();
  ebTouch();
}
// Plusieurs jours d un coup : une fermeture par date, comme si on les fermait un par un.
async function ebFermerPlage(debut) {
  if (!canUseStaffPermission('settings.manage')) { toast('Réservé à la direction.'); return; }
  if (ebEnvoiEnCours) return;
  const fin = document.getElementById('eb-j-fin')?.value;
  if (!fin || fin <= debut) { toast('Choisissez une date de fin après ce jour.'); return; }
  const dates = [];
  for (let d = new Date(`${debut}T12:00:00`); ebIso(d) <= fin && dates.length <= 31; d.setDate(d.getDate() + 1)) dates.push(ebIso(d));
  if (dates.length > 31) { toast('31 jours au plus d’un coup.'); return; }
  const dire = iso => new Date(`${iso}T12:00:00`).toLocaleDateString('fr-BE', { day: 'numeric', month: 'long' });
  if (!window.confirm(`Fermer le centre ${dates.length} jours, du ${dire(debut)} au ${dire(fin)} ? Les clients ne pourront plus réserver ces jours-là.`)) return;
  ebEnvoiEnCours = true;
  let faits = 0;
  try {
    for (const date of dates) {
      await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'saveAvailabilityBlock', centerId: getCurrentStaffCenterId(), scopeType: 'center', recurrence: 'once', date }) });
      faits += 1;
    }
    toast(`${faits} jours fermés.`);
  } catch (error) {
    toast(`${faits ? `${faits} jours fermés, puis : ` : ''}${error?.message || 'fermeture impossible.'}`);
  } finally {
    ebEnvoiEnCours = false;
  }
  await loadAvailabilityBlocks(true);
}

// ── Le calendrier ────────────────────────────────────────────────────────────
// Ce que le centre fait ce jour-la, lu dans la page vivante : il suit ce qui vient d etre change.
function ebStatutDuJour(iso) {
  const date = new Date(`${iso}T12:00:00`);
  const dow = String(date.getDay());
  const ferie = getBelgianPublicHoliday(iso);
  const conge = getWalloniaSchoolHoliday(iso);
  const force = establishmentHolidayOverridesDraft.find(o => o.date === iso);
  const autoCase = document.getElementById('estab-holiday-enabled');
  const auto = autoCase ? autoCase.checked : true;
  const vacances = force ? force.mode === 'holiday' : Boolean(auto && (ferie || conge));
  const prefixe = vacances ? 'estab-hday' : 'estab-day';
  const q = s => document.getElementById(`${prefixe}-${dow}-${s}`);
  const ferme = q('closed') ? q('closed').checked : true;
  const open = q('open') ? q('open').value : '';
  const closeChamp = q('close') ? q('close').value : '';
  const close = ebApresMinuit(open, closeChamp) ? ebLendemain(closeChamp) : closeChamp;
  const blocs = getAvailabilityBlocksForDate(iso);
  const centre = blocs.filter(b => b.scopeType === 'center');
  const totale = centre.some(b => !b.startTime);
  const partielle = centre.find(b => b.startTime);
  const pv = s => document.getElementById(`estab-hday-${dow}-${s}`);
  const vacOuvert = pv('closed') && !pv('closed').checked ? `${pv('open').value} à ${ebFermeDit(pv('open').value, pv('close').value)}` : '';
  return { date, ferie, conge, force, vacances, ferme, open, close, blocs, centre, totale, partielle, vacOuvert, autres: blocs.filter(b => b.scopeType !== 'center') };
}
function ebBlocPhrase(b) {
  const h = b.startTime ? ` de ${b.startTime} à ${b.endTime === '24:00' ? 'minuit' : b.endTime}` : '';
  if (b.scopeType === 'center') return h ? `Fermé${h}` : 'Fermé toute la journée';
  if (b.scopeType === 'lane') return `Piste ${b.scopeRef} fermée${h}`;
  if (b.scopeType === 'activity') return `${availabilityActivityLabel(b.scopeRef)} fermé${h}`;
  return `${availabilityFormulaLabel(b.scopeRef)} fermée${h}`;
}
// Une fermeture qui court jusqu a la fin du jour avance l heure de fermeture.
function ebFinAvancee(s) {
  return s.partielle && !s.totale && (s.partielle.endTime === '24:00' || s.close === '00:00' || s.partielle.endTime >= s.close) ? s.partielle.startTime : '';
}
function ebPeindreCalendrier() {
  const cases = document.querySelectorAll('[data-estab-page] .eb-j');
  if (!cases.length) return;
  const auj = ebIso(new Date());
  if (!ebJourChoisi) ebJourChoisi = auj;
  cases.forEach((b) => {
    const iso = b.dataset.iso;
    const s = ebStatutDuJour(iso);
    let cl = 'eb-j';
    if (s.totale) cl += ' is-b';
    else if (s.ferme) cl += ' is-x';
    else if (s.ferie) cl += ' is-f';
    else if (s.vacances) cl += ' is-v';
    else cl += ' is-n';
    if (s.partielle && !s.totale) cl += ' is-p';
    if (s.autres.length) cl += ' is-a';
    if (iso === auj) cl += ' is-auj';
    if (iso === ebJourChoisi) cl += ' is-sel';
    if (b.className !== cl) b.className = cl;
    const pressee = iso === ebJourChoisi ? 'true' : 'false';
    if (b.getAttribute('aria-pressed') !== pressee) b.setAttribute('aria-pressed', pressee);
  });
  ebDessinerJour();
}
function ebDessinerJour() {
  const hote = document.getElementById('ebJour');
  if (!hote || !ebJourChoisi) return;
  const iso = ebJourChoisi;
  const s = ebStatutDuJour(iso);
  const titre = s.date.toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' });
  const finAvancee = ebFinAvancee(s);
  const heures = s.totale || s.ferme ? 'Fermé' : `${s.open} à ${finAvancee || ebHeure(s.close, true)}`;
  const dit = s.totale ? (s.centre.find(b => !b.startTime).reason || 'Fermeture décidée')
    : s.ferme ? (s.force ? 'Jour à part, fermé ce jour-là' : 'Jour de fermeture habituel')
      : s.force ? `Jour à part, horaires ${s.force.mode === 'holiday' ? 'de vacances' : 'normaux'}`
        : s.ferie ? `${s.ferie}, horaires de vacances`
          : s.conge ? `${s.conge.label}, horaires de vacances`
            : 'Horaires normaux';
  const peutChanger = canUseStaffPermission('settings.manage') && iso >= ebIso(new Date());
  const activites = (getAvailabilityActivities() || []).map(a => `<option value="activity:${ebE(a.id)}">${ebE(a.label)}</option>`).join('');
  const pistes = Array.from({ length: getAvailabilityLaneCount() }, (u, i) => `<option value="lane:${i + 1}">Piste ${i + 1}</option>`).join('');
  let geste = '';
  if (peutChanger) {
    if (s.totale) geste = `<button type="button" class="eb-b eb-b-p eb-grand" onclick="deleteAvailabilityBlockUi(${Number(s.centre.find(b => !b.startTime).id)})">Rouvrir ce jour</button>`;
    else if (s.ferme) geste = s.vacOuvert && !s.vacances ? `<button type="button" class="eb-b eb-b-p eb-grand" onclick="ebForcerJour('${iso}','holiday')">Ouvrir ce jour, ${ebE(s.vacOuvert)}</button><p class="eb-note">Il part avec Enregistrer, comme un jour à part.</p>` : '';
    else {
      geste = `<button type="button" class="eb-b eb-b-p eb-grand" onclick="ebFermerJour('${iso}')">Fermer ce jour</button>
        <div class="eb-jl"><label class="eb-ch"><span>Fermer jusqu’au</span><input type="date" id="eb-j-fin" class="eb-f" min="${iso}"></label><button type="button" class="eb-b" onclick="ebFermerPlage('${iso}')">Fermer ces jours</button></div>
        <div class="eb-jl"><label class="eb-ch eb-ch-h"><span>Fermer plus tôt, dès</span><input type="time" id="eb-j-des" class="eb-f" value="18:00"></label><button type="button" class="eb-b" onclick="ebFermerJour('${iso}',document.getElementById('eb-j-des').value,'24:00')">Fermer dès cette heure</button></div>
        <div class="eb-jl"><label class="eb-ch eb-ch-m"><span>Fermer seulement</span><select id="eb-j-quoi" class="eb-f">${pistes}${activites}</select></label><button type="button" class="eb-b" onclick="ebBloquerJour('${iso}')">Fermer</button></div>
        <div class="eb-jl eb-force"><button type="button" class="eb-b" onclick="ebForcerJour('${iso}','${s.vacances ? 'normal' : 'holiday'}')">${s.vacances ? 'Mettre les horaires normaux ce jour' : 'Mettre les horaires de vacances ce jour'}</button></div>`;
    }
  }
  const deja = s.blocs.length ? `<div class="eb-deja">${s.blocs.map(b => `<div><span>${ebE(ebBlocPhrase(b))}${b.reason ? `, ${ebE(b.reason)}` : ''}</span>${peutChanger ? `<button type="button" onclick="deleteAvailabilityBlockUi(${Number(b.id)})">Retirer</button>` : ''}</div>`).join('')}</div>` : '';
  const html = `<button type="button" class="eb-jour-x" aria-label="Refermer le jour" onclick="ebFermerFicheJour()">×</button><h3 class="eb-jt">${ebE(titre)}</h3><p class="eb-jd">${ebE(dit)}</p><div class="eb-jh${s.totale || s.ferme ? ' is-ferme' : ''}">${ebE(heures)}</div>${deja}${geste}`;
  // Le panneau suit chaque changement de la page : le meme contenu ne se reecrit pas, une heure en cours de saisie y reste.
  if (html === ebJourHtml) return;
  ebJourHtml = html;
  hote.innerHTML = html;
}
function ebChoisirJour(iso) {
  ebJourChoisi = iso;
  ebPeindreCalendrier();
  document.getElementById('ebJour')?.classList.add('is-ouvert');
}
function ebFermerFicheJour() { document.getElementById('ebJour')?.classList.remove('is-ouvert'); }

// ── Ce qui suit les valeurs ──────────────────────────────────────────────────
function ebAnimer(el, images, duree) {
  if (el.animate && !prefersReducedMotion()) el.animate(images, { duration: duree, easing: 'cubic-bezier(.23,1,.32,1)' });
}
function ebDessinerPistes(root) {
  const hote = root.querySelector('[data-eb-pistes]');
  const champ = document.getElementById('estab-laneCount');
  if (!hote || !champ) return;
  const voulu = Math.max(1, Math.min(40, Number(champ.value) || 1));
  while (hote.children.length < voulu) {
    const piste = document.createElement('span');
    piste.className = 'eb-piste';
    piste.innerHTML = `<b>${hote.children.length + 1}</b><i></i>`;
    hote.appendChild(piste);
    if (hote.dataset.pret) ebAnimer(piste, [{ opacity: 0, transform: 'translateX(-22px) scaleY(.5)' }, { opacity: 1, transform: 'none' }], 340);
  }
  while (hote.children.length > voulu) hote.lastChild.remove();
  hote.dataset.pret = '1';
}
function ebDessinerPoints(root) {
  const val = id => Number(document.getElementById(id)?.value) || 0;
  root.querySelectorAll('[data-eb-points]').forEach((h) => {
    const [plein, creux] = h.dataset.ebPoints.split(',');
    const nPlein = Math.min(240, val(plein));
    const nTotal = Math.min(240, Math.max(nPlein, creux ? val(creux) : nPlein));
    if (h.children.length === nTotal && Number(h.dataset.plein) === nPlein) return;
    h.dataset.plein = String(nPlein);
    const avant = h.children.length;
    while (h.children.length < nTotal) h.appendChild(document.createElement('i'));
    while (h.children.length > nTotal) h.lastChild.remove();
    [...h.children].forEach((n, i) => { n.className = i < nPlein ? 'p' : 'c'; });
    if (h.dataset.pret && avant && h.children.length > avant) ebAnimer(h.lastChild, [{ transform: 'scale(.2)', opacity: 0 }, { transform: 'none', opacity: 1 }], 260);
    h.dataset.pret = '1';
  });
}
// Ce que les tables font vraiment : le mail part au-dela de la limite, jamais un refus.
function ebPhraseTables(conseillees, limite, mail) {
  return `${conseillees} table${conseillees > 1 ? 's' : ''} d’anniversaire, ${mail ? `un mail vous prévient au-delà de ${limite} en même temps` : 'sans mail au-delà de la limite'}.`;
}
// Ce qui se lit sur les cases et sous le nom du centre.
function ebResumes(root) {
  const q = id => document.getElementById(id);
  const pose = (k, t) => { const e = root.querySelector(`[data-eb-dit="${k}"]`); if (e && e.textContent !== t) e.textContent = t; };
  const ouverts = [1, 2, 3, 4, 5, 6, 0].filter(j => q(`estab-day-${j}-closed`) && !q(`estab-day-${j}-closed`).checked).length;
  pose('horaires', ouverts === 7 ? 'Ouvert tous les jours' : `Ouvert ${ouverts} jour${ouverts > 1 ? 's' : ''} sur 7`);
  const formules = [...root.querySelectorAll('[data-estab-offer]')];
  pose('formules', `${formules.filter(x => x.checked).length} sur ${formules.length} au formulaire`);
  pose('clients', `Un groupe dès ${q('estab-groupMinPax')?.value || '?'} joueurs`);
  pose('fiche', String(q('estab-address')?.value || '').trim() || 'Adresse à renseigner');
  const phraseTables = root.querySelector('[data-eb-phrase="tables"]');
  if (phraseTables) {
    const t = ebPhraseTables(Number(q('estab-tableSoft')?.value) || 0, q('estab-tableHard')?.value, Boolean(q('estab-tableLimit')?.checked));
    if (phraseTables.textContent !== t) phraseTables.textContent = t;
  }
  const auj = root.querySelector('[data-eb-auj]');
  if (auj) { const t = ebPhraseAujourdhui(); if (auj.textContent !== t) auj.textContent = t; }
}
// Ce que le centre fait aujourd hui, a l heure du centre et avec les memes regles que le calendrier.
function ebPhraseAujourdhui() {
  const center = getEstablishmentCenter();
  if (!center) return '';
  const statut = document.getElementById('estab-status')?.value || center.status;
  if (statut === 'planned') return 'Ce centre est prévu : il n’ouvre pas encore aux réservations en ligne.';
  if (statut === 'closed') return 'Ce centre est archivé : ses réservations en ligne sont coupées.';
  let iso = ebIso(new Date());
  let minutes = new Date().getHours() * 60 + new Date().getMinutes();
  try {
    const parts = new Intl.DateTimeFormat('en-CA', { timeZone: center.timezone || 'Europe/Brussels', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
    const get = type => (parts.find(p => p.type === type) || {}).value;
    iso = `${get('year')}-${get('month')}-${get('day')}`;
    minutes = Number(get('hour')) * 60 + Number(get('minute'));
  } catch (error) { /* l heure du poste suffit */ }
  const enMinutes = (v, fermeture) => { const [h, m] = String(v).split(':').map(Number); const x = h * 60 + m; return fermeture && x === 0 ? 1440 : x; };
  const prochaine = () => {
    const d = new Date(`${iso}T12:00:00`);
    for (let i = 1; i <= 21; i += 1) {
      d.setDate(d.getDate() + 1);
      const s = ebStatutDuJour(ebIso(d));
      if (!s.ferme && !s.totale && s.open) return `${i === 1 ? 'demain' : EB_JOURS_MINUSCULES[d.getDay()]} à ${s.open}`;
    }
    return '';
  };
  const s = ebStatutDuJour(iso);
  if (s.ferme || s.totale || !s.open) { const p = prochaine(); return p ? `Fermé aujourd’hui, réouverture ${p}.` : 'Fermé aujourd’hui.'; }
  const fin = ebFinAvancee(s) || s.close;
  if (minutes < enMinutes(s.open)) return `Ouvre aujourd’hui à ${s.open}, ferme à ${ebHeure(fin, true)}.`;
  if (minutes < enMinutes(fin, true)) return `Ouvert maintenant, jusqu’à ${ebHeure(fin, true)}.`;
  const p = prochaine();
  return p ? `Fermé pour ce soir, réouverture ${p}.` : 'Fermé pour ce soir.';
}

function ebRefresh() {
  const root = document.querySelector('[data-estab-page]');
  if (!root) return;
  // Un minimum qui suit un autre champ : les joueurs « si besoin » jamais sous les joueurs par piste.
  root.querySelectorAll('input[data-eb-min-from]').forEach((input) => {
    const base = Number(document.getElementById(input.dataset.ebMinFrom)?.value);
    if (Number.isFinite(base) && input.value !== '' && Number(input.value) < base) input.value = String(base);
  });
  root.querySelectorAll('input.eb-n-i').forEach((input) => {
    const boutons = input.parentElement.querySelectorAll('.eb-n-b');
    if (boutons.length !== 2 || input.disabled) return;
    const base = input.dataset.ebMinFrom ? Number(document.getElementById(input.dataset.ebMinFrom)?.value) : NaN;
    const min = Number.isFinite(base) ? Math.max(Number(input.min), base) : Number(input.min);
    const v = input.value === '' ? null : Number(input.value);
    boutons[0].disabled = v === null || (v <= min && !input.dataset.ebVide);
    boutons[1].disabled = v !== null && v >= Number(input.max);
  });
  root.querySelectorAll('[data-eb-seg]').forEach((seg) => {
    const valeur = document.getElementById(seg.dataset.ebSeg)?.value;
    seg.querySelectorAll('.eb-seg-btn').forEach((b) => { const on = b.dataset.ebV === valeur; b.classList.toggle('is-on', on); b.setAttribute('aria-checked', on ? 'true' : 'false'); });
  });
  root.querySelectorAll('.eb-dayopen').forEach((sw) => {
    const ferme = document.getElementById(`${sw.dataset.ebFor}-closed`);
    if (ferme) ferme.checked = !sw.checked;
    sw.closest('.eb-d').classList.toggle('is-closed', !sw.checked);
  });
  ebDessinerPistes(root);
  ebDessinerPoints(root);
  root.querySelectorAll('[data-eb-miroir]').forEach((e) => { const champ = document.getElementById(e.dataset.ebMiroir); if (champ && e.textContent !== champ.value) e.textContent = champ.value; });
  root.querySelectorAll('.eb-act[data-act]').forEach((x) => { const champ = document.getElementById(`estab-act-${x.dataset.act}`); if (champ) x.classList.toggle('est-off', !champ.checked); });
  root.querySelectorAll('[data-eb-lendemain]').forEach((n) => {
    const p = n.dataset.ebLendemain;
    const f = document.getElementById(`${p}-close`)?.value;
    const mot = f === '00:00' ? 'minuit' : (ebApresMinuit(document.getElementById(`${p}-open`)?.value, f) ? 'le lendemain' : '');
    if (n.textContent !== mot) n.textContent = mot;
    if (n.hidden !== !mot) n.hidden = !mot;
  });
  root.querySelectorAll('.eb-tr[data-eb-nom]').forEach((l) => { const champ = l.querySelector('[data-estab-offer]'); if (champ) l.classList.toggle('est-off', !champ.checked); });
  ebResumes(root);
  if (ebOuverte === 'horaires') ebPeindreCalendrier();
}

function ebState() {
  const root = document.querySelector('[data-estab-page]');
  const out = {};
  if (!root) return out;
  root.querySelectorAll('input[id],select[id],textarea[id]').forEach((el) => {
    if (/^(eb-|avb-|estab-new-|estab-override-|estab-res-)/.test(el.id) || el.closest('[data-eb-watch]')) return;
    out[el.id] = el.type === 'checkbox' || el.type === 'radio' ? String(el.checked) : el.value;
  });
  root.querySelectorAll('[data-eb-watch]').forEach((el) => {
    out[`w:${el.dataset.ebWatch}`] = `${el.innerHTML.replace(/ style="[^"]*"/g, '')}|${[...el.querySelectorAll('input,select,textarea')].map(x => (x.type === 'checkbox' ? x.checked : x.value)).join(',')}`;
  });
  return out;
}

function ebCountChanges() {
  if (!ebSnap) return 0;
  const now = ebState();
  const cles = new Set();
  new Set([...Object.keys(now), ...Object.keys(ebSnap)]).forEach((k) => {
    if (now[k] !== ebSnap[k]) cles.add(k.replace(/^(estab-h?day-\d)-.*$/, '$1').replace('estab-accent-picker', 'estab-accent'));
  });
  return cles.size;
}

// La barre dit ce qui change, en mots : les nombres avec leur ancienne valeur, les heures, ce qui est retire ou remis.
const EB_NOMBRES_DITS = {
  'estab-laneCount': ['piste', 'pistes'], 'estab-weaponCount': ['arme', 'armes'],
  'estab-normalCap': ['joueur par piste', 'joueurs par piste'], 'estab-emergencyCap': ['joueur par piste si besoin', 'joueurs par piste si besoin'],
  'estab-launches': ['partie laser en même temps', 'parties laser en même temps'], 'estab-tableSoft': ['table conseillée', 'tables conseillées'], 'estab-tableHard': ['table au plus', 'tables au plus'],
  'estab-groupMinPax': ['joueur pour un groupe', 'joueurs pour un groupe'], 'estab-groupMinCumulative': ['joueur cumulé pour un groupe', 'joueurs cumulés pour un groupe'],
  'estab-keyClientMinSpend': ['€ pour un client clé', '€ pour un client clé'], 'estab-lateThreshold': ['minute avant le retard', 'minutes avant le retard'],
};
const EB_CASES_DITES = {
  'estab-preferAdjacent': ['Groupes sur des pistes voisines', 'Groupes plus forcément sur des pistes voisines'],
  'estab-requiresComplete': ['Le laser part avec le groupe complet', 'Le laser n’attend plus le groupe complet'],
  'estab-canSplit': ['Grands groupes coupés en deux au laser', 'Grands groupes plus coupés au laser'],
  'estab-tableLimit': ['Mail au-delà de la limite de tables', 'Plus de mail pour les tables'],
  'estab-holiday-enabled': ['Horaires de vacances tout seuls', 'Horaires de vacances à la main'],
  'estab-fbp-public': ['Formules bloquées les jours fériés', 'Formules permises les jours fériés'],
  'estab-fbp-short': ['Formules bloquées aux petits congés', 'Formules permises aux petits congés'],
  'estab-fbp-summer': ['Formules bloquées en juillet et août', 'Formules permises en juillet et août'],
  'estab-countFormulaAsGroup': ['Une formule compte comme un groupe', 'Une formule ne compte plus comme un groupe'],
  'estab-birthdayFromFormula': ['Anniversaire lu dans la formule', 'Anniversaire plus lu dans la formule'],
  'estab-bar-booking': ['Le comptoir prend les réservations', 'Le comptoir ne prend plus les réservations'],
  'estab-bar-briefing': ['Le comptoir donne les consignes', 'Le comptoir ne donne plus les consignes'],
  'estab-bar-food': ['Le comptoir sert à boire et à manger', 'Le comptoir ne sert plus à boire et à manger'],
  'estab-bar-escort': ['Le comptoir accompagne les groupes', 'Le comptoir n’accompagne plus les groupes'],
  'estab-arc-enabled': ['Cartes Arcades proposées', 'Cartes Arcades retirées'],
};
const EB_TEXTES_DITS = {
  'estab-logo': 'Logo changé', 'estab-logoDark': 'Fond du logo changé', 'estab-site': 'Site du centre changé',
  'estab-name': 'Nom du centre changé', 'estab-address': 'Adresse changée', 'estab-phone': 'Téléphone changé', 'estab-parking': 'Parking changé',
  'estab-book-min': 'Réservation en ligne : « au plus tard » changé', 'estab-book-horizon': 'Réservation en ligne : « au plus tôt » changé',
  'estab-timezone': 'Fuseau horaire changé', 'estab-secours-emails': 'Boîte de secours changée', 'estab-accent': 'Couleur du formulaire changée',
  'estab-payment-mode': 'Encaissement changé',
};
const EB_ZONES_DITES = { 'w:exceptions': 'Jours à part modifiés', 'w:installations': 'Autres installations modifiées', 'w:activites-perso': 'Activités à vous modifiées', 'w:suggestions': 'Suggestions modifiées', 'w:validation': 'Validation modifiée' };
function ebDireUnChangement(cle, v, avant) {
  if (EB_NOMBRES_DITS[cle]) { const [un, plusieurs] = EB_NOMBRES_DITS[cle]; return `${v} ${Number(v) > 1 ? plusieurs : un} au lieu de ${avant}`; }
  if (EB_CASES_DITES[cle]) return EB_CASES_DITES[cle][v === 'true' ? 0 : 1];
  if (EB_TEXTES_DITS[cle]) return EB_TEXTES_DITS[cle];
  if (EB_ZONES_DITES[cle]) return EB_ZONES_DITES[cle];
  if (cle === 'estab-status') return { active: 'Centre ouvert à la réservation', planned: 'Centre prévu', closed: 'Centre archivé' }[v] || 'Statut changé';
  if (cle === 'estab-customRequestFromPax') return v === '' ? 'Plus de demande sur mesure' : `Sur mesure dès ${v} joueurs`;
  if (/^estab-style-/.test(cle) || cle === 'estab-accent-picker') return 'Style du formulaire changé';
  if (/^estab-arc-/.test(cle)) return 'Cartes Arcades modifiées';
  const champ = document.getElementById(cle);
  if (champ && champ.dataset.capName) return `${champ.dataset.capName} : ${v} ${champ.dataset.capWhat} au lieu de ${avant}`;
  if (champ && champ.dataset.estabOffer) return `${champ.closest('[data-eb-nom]')?.dataset.ebNom || 'Une formule'} ${champ.checked ? 'remise au formulaire' : 'retirée du formulaire'}`;
  if (champ && champ.dataset.estabBday) return `${champ.closest('[data-eb-nom]')?.dataset.ebNom || 'Une formule'} ${champ.checked ? 'compte en anniversaire' : 'ne compte plus en anniversaire'}`;
  if (/^estab-act-/.test(cle)) {
    const nom = (staffCenterConfigCache.activities || []).find(a => `estab-act-${a.id}` === cle)?.label || 'Activité';
    return `${nom} ${v === 'true' ? 'réservable en ligne' : 'plus réservable en ligne'}`;
  }
  return '';
}
function ebDireUnJour(prefixe, jour, now) {
  const label = (ESTABLISHMENT_DAYS.find(([k]) => k === jour) || [])[1] || '';
  const suffixe = prefixe === 'estab-hday' ? ' en vacances' : '';
  const k = s => `${prefixe}-${jour}-${s}`;
  if (now[k('closed')] !== ebSnap[k('closed')]) return now[k('closed')] === 'true' ? `${label}${suffixe} fermé` : `${label}${suffixe} ouvert, ${now[k('open')]} à ${ebFermeDit(now[k('open')], now[k('close')])}`;
  const morceaux = [];
  if (now[k('open')] !== ebSnap[k('open')]) morceaux.push(`ouvre à ${now[k('open')]} au lieu de ${ebSnap[k('open')]}`);
  if (now[k('close')] !== ebSnap[k('close')]) morceaux.push(`ferme à ${ebFermeDit(now[k('open')], now[k('close')])} au lieu de ${ebFermeDit(ebSnap[k('open')], ebSnap[k('close')])}`);
  return morceaux.length ? `${label}${suffixe} ${morceaux.join(', ')}` : '';
}
function ebPhraseDesChangements(n) {
  if (!ebSnap) return '';
  const now = ebState();
  const phrases = [];
  const vus = new Set();
  Object.keys(now).forEach((cle) => {
    if (now[cle] === ebSnap[cle]) return;
    const jour = /^(estab-h?day)-(\d)-(?:open|close|closed)$/.exec(cle);
    const phrase = jour ? (vus.has(`${jour[1]}-${jour[2]}`) ? '' : ebDireUnJour(jour[1], jour[2], now)) : ebDireUnChangement(cle, now[cle], ebSnap[cle]);
    if (jour) vus.add(`${jour[1]}-${jour[2]}`);
    if (phrase && !phrases.includes(phrase)) phrases.push(phrase);
  });
  if (!phrases.length) return n === 1 ? '1 changement' : `${n} changements`;
  const autres = Math.max(phrases.length - 2, 0);
  return `${phrases.slice(0, 2).join(' · ')}${autres > 0 ? ` et ${autres} autre${autres > 1 ? 's' : ''}` : ''}`;
}

function ebMarquerRubriques() {
  const root = document.querySelector('[data-estab-page]');
  if (!root) return;
  const changees = new Set();
  const fautives = new Set();
  if (ebSnap) {
    const now = ebState();
    Object.keys(now).forEach((cle) => {
      if (now[cle] === ebSnap[cle]) return;
      const el = cle.startsWith('w:') ? root.querySelector(`[data-eb-watch="${cle.slice(2)}"]`) : document.getElementById(cle);
      const pan = el && el.closest('.eb-pan');
      if (pan) changees.add(pan.dataset.k);
    });
  }
  root.querySelectorAll('[aria-invalid="true"]').forEach((el) => { const pan = el.closest('.eb-pan'); if (pan) fautives.add(pan.dataset.k); });
  root.querySelectorAll('.eb-m[data-k]').forEach((m) => {
    m.classList.toggle('has-change', changees.has(m.dataset.k));
    m.classList.toggle('has-error', fautives.has(m.dataset.k));
  });
}

function ebTouch() {
  const n = ebCountChanges();
  state.establishmentEditing = n > 0;
  ebMarquerRubriques();
  const bar = document.getElementById('ebBar');
  if (!bar) return;
  document.getElementById('ebBarN').textContent = ebPhraseDesChangements(n);
  bar.hidden = n === 0;
}

function ebOnChange() { ebRefresh(); ebTouch(); }

function ebOnClick() {
  ebChampVoulu(null);
  // Les gestes qui changent la page sans passer par un champ (ajouter, retirer, suggestions, validation) se comptent
  // apres coup.
  setTimeout(() => { ebRefresh(); ebTouch(); }, 40);
}

// LA VALIDATION PAR L EQUIPE, telle que l ecran la montre (2026-10-05). Miroir
// de lib/situations-validation (SITUATIONS, NIVEAUX) : le gate
// situations-validation-check compare les deux, une derive y rougit.
const VALIDATION_SITUATIONS = [
  { id: 'bowling_secours', mot: 'Bowling en capacité de secours', explication: 'Le groupe ne tient qu’à 7 joueurs par piste au lieu de 6, la partie sera plus longue.', exemple: '13 joueurs sur 2 pistes, répartis 7 + 6.' },
  { id: 'laser_plein', mot: 'Arène laser presque pleine', explication: 'Le groupe rentre, mais avec lui la session laser partagée est presque complète (3 places libres ou moins).', exemple: 'Deux groupes, 27 joueurs pour 30 places.' },
  { id: 'apres_fermeture', mot: 'Dépasse la fermeture', explication: 'La dernière activité du groupe finit après l’heure de fermeture du centre.', exemple: 'Fin à 0 h 20 pour une fermeture à minuit.' },
  { id: 'laser_partage', mot: 'Laser partagé avec un autre groupe', explication: 'Le groupe jouera dans la même session laser qu’un autre groupe.', exemple: 'Un anniversaire placé avec 10 joueurs déjà inscrits.' },
  { id: 'enchainement_serre', mot: 'Enchaînement serré', explication: 'Moins de 5 minutes entre deux activités, pour un groupe de 12 personnes ou plus.', exemple: 'Bowling jusqu’à 16:00, laser à 16:00 pour 20 joueurs.' },
];
const VALIDATION_NIVEAUX = {
  minimal: { mot: 'Minimal', dit: 'Personne n’est dérangé. Ce qui rentre est confirmé, ce qui ne rentre pas est refusé au client avec d’autres horaires.', situations: [] },
  normal: { mot: 'Normal', dit: 'Vous validez vous-même ce qui rentre de justesse, comme le bowling à 7, l’arène laser presque complète ou une fin après la fermeture.', situations: ['bowling_secours', 'laser_plein', 'apres_fermeture'] },
  prudent: { mot: 'Prudent', dit: 'Aussi quand le laser est partagé avec un autre groupe ou que les activités s’enchaînent sans marge.', situations: ['bowling_secours', 'laser_plein', 'apres_fermeture', 'laser_partage', 'enchainement_serre'] },
};
function validationReglageDe(center) {
  const v = center && center.validationEquipe && typeof center.validationEquipe === 'object' ? center.validationEquipe : {};
  const niveau = Object.prototype.hasOwnProperty.call(VALIDATION_NIVEAUX, v.niveau) ? v.niveau : 'minimal';
  const situations = v.situations && typeof v.situations === 'object' ? v.situations : {};
  const actives = new Set(VALIDATION_NIVEAUX[niveau].situations);
  Object.entries(situations).forEach(([id, on]) => { if (typeof on === 'boolean') { if (on) actives.add(id); else actives.delete(id); } });
  return { niveau, situations, actives };
}
let establishmentValidationDraft = null;
function establishmentValidationHtml(center) {
  const r = establishmentValidationDraft || validationReglageDe(center);
  establishmentValidationDraft = r;
  return `<fieldset class="establishment-card estab-validation" id="estab-validation">
      <legend>Validation par l’équipe</legend>
      <p class="estab-card-hint">Ce qui ne rentre pas dans le planning est refusé au client, avec d’autres horaires, sans vous déranger. Ici, vous choisissez les cas qui rentrent de justesse et que vous voulez valider vous-même.</p>
      <div class="estab-seg" role="radiogroup" aria-label="Niveau de validation">${Object.entries(VALIDATION_NIVEAUX).map(([id, n]) => `<button type="button" role="radio" aria-checked="${r.niveau === id ? 'true' : 'false'}" class="estab-seg-btn${r.niveau === id ? ' is-on' : ''}" onclick="setEstablishmentValidationNiveau('${id}')">${escapeHtml(n.mot)}</button>`).join('')}</div>
      <p class="estab-valid-dit">${escapeHtml(VALIDATION_NIVEAUX[r.niveau].dit)}</p>
      <ul class="estab-situations">${VALIDATION_SITUATIONS.map(s => {
        const on = r.actives.has(s.id);
        return `<li class="estab-situation${on ? ' is-on' : ''}">
          <label class="eb-k"><input type="checkbox" ${on ? 'checked' : ''} ${s.toujours ? 'disabled' : ''} onchange="toggleEstablishmentValidationSituation('${s.id}', this.checked)"><span class="eb-k-b" aria-hidden="true"></span><span class="eb-k-t"><b>${escapeHtml(s.mot)}</b><small>${escapeHtml(s.explication)}</small><small class="estab-sit-ex">Exemple : ${escapeHtml(s.exemple)}</small></span></label>
        </li>`;
      }).join('')}</ul>
    </fieldset>`;
}
function setEstablishmentValidationNiveau(niveau) {
  if (!VALIDATION_NIVEAUX[niveau]) return;
  // Changer de niveau repart des situations de ce niveau : les interrupteurs
  // poses a la main pour l ancien niveau ne suivent pas.
  establishmentValidationDraft = { niveau, situations: {}, actives: new Set(VALIDATION_NIVEAUX[niveau].situations) };
  const zone = document.getElementById('estab-validation');
  if (zone) zone.outerHTML = establishmentValidationHtml(null);
}
function toggleEstablishmentValidationSituation(id, on) {
  const r = establishmentValidationDraft;
  if (!r || !VALIDATION_SITUATIONS.some(s => s.id === id)) return;
  const parDefaut = VALIDATION_NIVEAUX[r.niveau].situations.includes(id);
  if (on === parDefaut) delete r.situations[id]; else r.situations[id] = Boolean(on);
  if (on) r.actives.add(id); else r.actives.delete(id);
  const li = document.querySelector(`#estab-validation input[onchange*="'${id}'"]`)?.closest('.estab-situation');
  if (li) li.classList.toggle('is-on', Boolean(on));
}
function collectEstablishmentValidation() {
  const r = establishmentValidationDraft;
  if (!r) return undefined;
  return { niveau: r.niveau, situations: { ...r.situations } };
}
function establishmentSecoursHtml(center) {
  const emails = center && center.secours && Array.isArray(center.secours.emails) ? center.secours.emails : [];
  return `<fieldset class="establishment-card estab-secours">
      <legend>Boîte de secours</legend>
      <p class="estab-card-hint">Une copie complète de chaque réservation, de chaque demande sur mesure et la feuille du jour à imprimer partent vers ces adresses. Ce ne sont pas des demandes d’action : c’est ce qui permet d’accueillir les groupes si Pinlane est indisponible. Une boîte à part, protégée par une double authentification, plutôt que celle de l’accueil.</p>
      <div class="field"><label for="estab-secours-emails">Adresses (séparées par une virgule, 5 au plus)</label><input type="text" id="estab-secours-emails" inputmode="email" autocomplete="off" value="${escapeHtml(emails.join(', '))}" placeholder="secours@votrecentre.be"></div>
    </fieldset>`;
}

// HIERARCHIE DES PERMISSIONS COTE ECRAN (2026-08-19, demande de Movsar :
// « tout ce qui est contenu dans une option, faut que ce soit des sous-options »).
// MIROIR de PERMISSION_PARENTS (lib/staff-auth.js), qui reste la source de
// verite : le serveur normalise a chaque ecriture, l'ecran ne fait que rendre
// la meme regle lisible et evidente au clic.
const STAFF_PERMISSION_PARENTS = {
  'direction.view': 'dashboard.view',
  'reports.export': 'dashboard.view',
  'planning.bowling': 'planning.view',
  'planning.laser': 'planning.view',
  'planning.drag': 'planning.view',
  'planning.past': 'planning.view',
  'reservations.create': 'reservations.view',
  'reservations.quick': 'reservations.create',
  'reservations.edit': 'reservations.view',
  'reservations.cancel': 'reservations.view',
  'reservations.status': 'reservations.view',
  'clients.edit': 'clients.view',
  'payments.markPaid': 'payments.view',
  'exports.download': 'clients.view',
  'emails.send': 'emails.view',
  'campaigns.manage': 'emails.view',
  'marketing.agents': 'emails.view',
  'security.codes': 'users.manage',
};

// La profondeur d'une permission dans l'arbre (0 = option de premier niveau).
function staffPermissionDepth(permission) {
  let depth = 0;
  let current = STAFF_PERMISSION_PARENTS[permission];
  while (current && depth < 5) { depth += 1; current = STAFF_PERMISSION_PARENTS[current]; }
  return depth;
}

// Les descendants d'une permission (sous-options, et leurs sous-options).
function staffPermissionDescendants(permission) {
  const direct = Object.keys(STAFF_PERMISSION_PARENTS).filter(key => STAFF_PERMISSION_PARENTS[key] === permission);
  return direct.flatMap(child => [child, ...staffPermissionDescendants(child)]);
}

// Les parents d'une permission, du plus proche au plus lointain.
function staffPermissionAncestors(permission) {
  const chain = [];
  let current = STAFF_PERMISSION_PARENTS[permission];
  while (current && !chain.includes(current)) { chain.push(current); current = STAFF_PERMISSION_PARENTS[current]; }
  return chain;
}

